INSERT INTO `modx_site_htmlsnippets` VALUES ('13','footer','','0','7','0','<div id=\"box-footer\" class=\"vt-footer wrap\">    \n                \n<div class=\"footer-top\">\n	              \n		<div class=\"block block-footertop\">\n<div class=\"block-content\">\n<p class=\"title\">OPERATING INSTRUCTION MANUALS</p>\n<p class=\"bottom\">LOGIN TO THE OLEC CLUB AND DOWNLOAD YOUR WATCH OPERATING INSTRUCTION MANUAL</p>\n</div>\n<div class=\"clearfix\">&nbsp;</div>\n<div class=\"btn-login\"><a href=\"\">LOGIN AND DOWNLOAD</a></div>\n</div>   \n	</div>\n<div class=\"footer-bottom\">\n	<div class=\"container\">\n		<div class=\"row\">\n							<div class=\"spotlight-wrap\">\n					<div class=\"spotlight spotlight1 col-lg-3 col-md-3 col-sm-6 col-xs-12\">\n<div class=\"block-title\"><a href=\"/o-nas.html\" title=\"О нас\">О нас</a></div>\n<div class=\"block-content\">\n<p>Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.</p>\n<p><a href=\"/assets/templates/olec/index.php/about-us/\">Click to read more</a></p>\n</div>\n</div><div class=\"spotlight spotlight2 col-lg-3 col-md-3 col-sm-6 col-xs-12\">\n<div class=\"block-title\">Условия</div>\n<div class=\"block-content\">\n<ul>\n<li><a href=\"/oplata.html\" title=\"Оплата\">Оплата</a></li>\n\n    <li><a href=\"/dostavka.html\" title=\"Доставка\">Доставка</a></li>\n    <li><a href=\"/garantiya-i-servis-chasov-traser.html\" title=\"Гарантия и возврат\">Гарантия и возврат</a></li><li><a href=\"diskontnye-karty-traser.html\" title=\"Получить дисконтную карту\">Дисконтные карты</a></li>\n</ul>\n</div>\n<div class=\"block-title block-title-2\">Информация</div>\n<div class=\"block-content\">\n<ul>\n<li><a href=\"#\">Новости</a></li>\n<li><a href=\"/stati.html\" title=\"Обзоры и статьи\">Обзоры и статьи</a></li>\n\n</ul>\n</div>\n</div><div class=\"spotlight spotlight3 col-lg-3 col-md-3 col-sm-6 col-xs-12\">\n<div class=\"block-title\">Почему Traser H3</div>\n<div class=\"block-content\">\n<ul>\n<li><a href=\"#\">100% оригинал</a></li>\n<li><a href=\"#\">Бесплатная доставка</a></li>\n<li><a href=\"#\">Полное страхование</a></li>\n<li><a href=\"#\">Безопасность платежей</a></li>\n\n</ul>\n</div>\n</div><div class=\"spotlight spotlight4 col-lg-3 col-md-3 col-sm-6 col-xs-12\">\n<div class=\"block-title\">Contact Olec</div>\n<ul class=\"block-content\">\n<li class=\"address\">\n<span class=\"ico-contactus\">icon</span>\n<div class=\"inner\">Address : No 40 Baria Sreet 133/2 NewYork City, NY, United States.</div>\n</li>\n<li class=\"phone\">\n<span class=\"ico-contactus\">icon</span>\n<div class=\"inner\">+1 800 559 6580<br> +1 504 889 9898</div>\n</li>\n<li class=\"email\">\n<span class=\"ico-contactus\">icon</span>\n<div class=\"inner\">Email : <a href=\"mailto:contact@market.com\">mail@demolink.org</a></div>\n</li>\n</ul>\n</div>				</div>\n						\n		</div>\n		<div class=\"row\">\n			<div class=\"footer-bottom-wrap\">\n								<div class=\"social col-lg-4 col-md-4 col-sm-5 col-xs-12\">        \n					<ul>\n	<li><a title=\"Facebook\" href=\"#\" target=\"_blank\" class=\"icon-facebook\">&nbsp;</a></li>\n	<li><a title=\"Twitter\" href=\"#\" target=\"_blank\" class=\"icon-twitter\">&nbsp;</a></li>		\n	<li><a title=\"Linkedin\" href=\"#\" target=\"_blank\" class=\"icon-linkedin\">&nbsp;</a></li>\n	<li><a title=\"Google+\" href=\"#\" target=\"_blank\" class=\"icon-google-plus\">&nbsp;</a></li>\n	<li><a title=\"Pinterest\" href=\"#\" target=\"_blank\" class=\"icon-pinterest\">&nbsp;</a></li>\n</ul>				</div>\n				<div class=\"block-newsletter col-lg-8 col-md-8 col-sm-7 col-xs-12\">        \n					<div class=\"block-content\">\n\n</div>\n<script type=\"text/javascript\">// <![CDATA[\n        var newsletterSubscriberFormDetail = new VarienForm(\'newsletter-validate-detail\');\n// ]]></script>				</div>\n			</div>\n		</div>\n		<div class=\"row\">\n			<div class=\"footer-bottom-link\">\n				<div class=\"link-footer col-lg-8 col-md-7 col-sm-8 col-xs-12\">        \n					<ul>\n<li class=\"link1\"><a href=\"#\">Политика конфиденциальности</a></li>\n<li class=\"link2\"><a href=\"/o-nas.html\" title=\"О нас\">О нас</a></li>\n<li class=\"link3\"><a href=\"/oplata.html\" title=\"Оплата\">Оплата</a></li>\n<li class=\"link4\"><a href=\"/dostavka.html\" title=\"Доставка\">Доставка</a></li>\n<li class=\"link5\"><a href=\"/garantiya-i-servis-chasov-traser.html\" title=\"Гарантия и возврат\">Гарантия и возврат</a></li>\n<li class=\"link6\"><a href=\"/kontakty.html\" title=\"Контакты\">Контакты</a></li>\n\n</ul>				</div>\n				<div class=\"block-payment col-lg-4 col-md-5 col-sm-4 col-xs-12\">        \n					<ul class=\"payment\">\n<li class=\"p1\"><span>wepay</span></li>\n<li class=\"p2\"><span>master</span></li>\n<li class=\"p3\"><span>a</span></li>\n<li class=\"p4\"><span>paypal</span></li>\n<li class=\"p5\"><span>visa</span></li>\n</ul>				</div>\n			</div>\n		</div>\n	</div>\n</div>\n\n   \n            </div>','0');
