INSERT INTO `modx_site_htmlsnippets` VALUES ('27','sliderInner','','0','10','0','<div class=\"element shk-item\">\n				<h1><a href=\"[~[+id+]~]\">[+pagetitle+]</a></h1>\n				<div class=\"justifyright\">\n					<a href=\"[~[+id+]~]\"><img src=\"[+slider_image+]\" width=\"350\" /></a>\n					<div class=\"label\">\n						[[if? &is=`[+status+]:!empty:` &then=`<img src=\"[[DocInfo? &docid=`[+status+]` &tv=`1` &field=`image`]]\" />`]]\n					</div>\n				</div>\n	[[if? &is=`[+longtitle+]:!empty:` &then=`<div class=\"ptnarrow info\">[+longtitle+]</div>` &else=` `]]\n				<div class=\"ptnarrow info\">Артикул: [+articul+]</div>\n	<div class=\"descr\">[[if? &is=`[+sliderText+]:empty:` &then=`[[summary? &len=`200` &text=`[+content+]`]]` &else=`[+sliderText+]`]]</div>\n				<form action=\"[~281~]\" method=\"post\">\n					<input type=\"hidden\" name=\"shk-id\" value=\"[+id+]\" />\n					<input type=\"hidden\" name=\"shk-name\" value=\"[+pagetitle+]\" />\n					<input type=\"hidden\" name=\"shk-count\" value=\"1\" size=\"2\" maxlength=\"3\" />\n					<div class=\"shk-price\">[[formatPrice? &price=`[+price+]`]].-</div>\n					<button type=\"submit\">Купить</button>\n					<a href=\"[~299~]\" class=\"one_click fancybox.ajax\">Купить в 1 клик</a>\n				</form>\n			</div>','0');
