INSERT INTO `modx_site_htmlsnippets` VALUES ('29','sk_cartTpl','','0','10','0','<div class=\"block block-cart cart\" id=\"shopCart\">\n	<div class=\"block-title\">\n		<strong>\n			<span data-toggle=\"tooltip\" data-placement=\"left\" title=\"My Cart\">Корзина</span>\n			<span class=\"fa-stack\">0</span>\n		</strong>\n    </div>\n	[+plugin+]\n</div>\n<!--tpl_separator-->\n<div class=\"cart\" id=\"shopCart\">\n	<div id=\"cartInner\">\n[+fixMinPrice+]\n<form action=\"[+this_page_url+]#shopCart\" method=\"post\">\n    <fieldset>\n		<table id=\"shopping-cart-table\" class=\"data-table cart-table\">\n			<thead>\n				<tr class=\"first last\">\n					<th rowspan=\"1\"><span class=\"nobr\">Модель</span></th>\n					<th rowspan=\"1\" class=\"a-center\">Количество</th>\n					<th class=\"a-center\" colspan=\"1\">Стоимость</th>\n				</tr>\n			</thead>\n			\n			<tbody>\n				 [+inner+]\n			</tbody>\n		</table>\n		<div class=\"hidden buttons\">\n			<div class=\"tcart\"><span>Сумма по товарам:</span>[+price_wo_delivery+].-</div>\n			[+delivery+]\n			<div class=\"tcart\"><span>Сумма к оплате:</span>[+price_total+].-</div>\n		</div>\n	</fieldset>\n</form>\n[+plugin+]\n	</div>\n</div>\n<!--tpl_separator-->\n<div class=\"block block-cart cart\" id=\"shopCart\">\n	<div class=\"block-title\">\n		<strong>\n			<span data-toggle=\"tooltip\" data-placement=\"left\" title=\"My Cart\">Корзина</span>\n			<span class=\"fa-stack\">[[if? &is=`[+total_items_minus+]:eq:1` &then=`[[if? &is=`[+total_items+]-1` &math=`on`]]` &else=`[+total_items+]`]]</span>\n		</strong>\n    </div>\n	<div class=\"block-content\">    \n		<ol id=\"cart-sidebar\" class=\"mini-products-list\">\n		[+inner+]\n		</ol>\n		<script type=\"text/javascript\">decorateList(\'cart-sidebar\', \'none-recursive\')</script>\n		\n				<div class=\"actions clearfix\">\n						\n			<a type=\"button\" title=\"Checkout\" class=\"button\" href=\"[+order_page_url+]\"><span><span>Оформить заказ</span></span></a>\n		</div>\n			</div>\n	</div>\n','0');
