INSERT INTO `modx_site_htmlsnippets` VALUES ('84','articleTpl','','0','10','0','\n<li class=\"postWrapper item\">\n		<div class=\"item-inner\">\n			<div class=\"product-info row\">\n				[[if? &is=`[+image+]:!empty:` &then=`<div class=\"item-lb-image col-lg-3 col-md-3 col-sm-3 col-xs-12\"><a href=\"[~[+id+]~]\"><img alt=\"\" src=\"[[phpthumb? &input=`[+image+]` &options=`w=150,h=110,zc=1,f=jpeg,q=90`]]\"></a></div>` &else=``]]\n				<div class=\"inner-content col-lg-9 col-md-9 col-sm-9 col-xs-12\">\n					<div class=\"product-name\">\n						<h2><a class=\"title-blog-name\" href=\"[~[+id+]~]\">[[if? &is=`[+longtitle+]:!empty:` &then=`[+longtitle+]` &else=`[+pagetitle+]`]]</a></h2>\n					</div>\n					<div class=\"info-cat-blog\">\n												<div class=\"bottom-info-blog\">\n							<ul class=\"list-info-bottom\">\n								<li>[[aDate? &date=`[+createdon+]` &date2=`[+pub_date+]`]]</li>\n							</ul>\n						</div>\n					</div>					\n					<div class=\"postContent\">\n						<p>[[summary? &text=`[+content+]` &len=`500` &dot=`1`]]</p><a class=\"aw-blog-read-more\" href=\"[~[+id+]~]\">Читать полностью</a>						\n					</div>\n				</div>	\n			</div>\n		</div>\n    </li>','0');
