INSERT INTO `modx_site_htmlsnippets` VALUES ('49','catalogItems','','0','9','0','<div class=\"toolbar\">\n				<div class=\"container\">\n					<div class=\"row\">\n    					<div class=\"sorter col-lg-12\">\n                			<div class=\"limiter col-lg-4 col-md-4 col-sm-4 col-xs-12\">\n           				 		<label>Сортировка</label>\n           	 					<div class=\"wrap-show\" style=\"width: 80%;\">\n               						<div class=\"selected-limiter\"></div>\n									<ul class=\"select-limiter\">\n                                       	<li><a href=\"[~[*id*]~]?ord=desc&sor=price\"  class=\"selected\"  >цена (по убыванию)</a></li>\n                                        <li><a href=\"[~[*id*]~]?ord=asc&sor=price\"  >цена (по возрастанию)</a></li>\n                                        <li><a href=\"[~[*id*]~]?ord=desc&sor=new\">новизна (по убыванию)</a></li>\n										<li><a href=\"[~[*id*]~]?ord=asc&sor=new\">новизна (по возрастанию)</a></li>\n                                     </ul>                 \n            					</div>\n        					</div>\n							<div class=\"pager col-lg-8 col-md-8 col-sm-8 col-xs-12\">\n							[[if? &is=`[+catid_totalPages+]:eq:1` &then=` ` &else=`<div class=\"pages\"><ol>[+catid_previous+][+catid_pages+][+catid_next+]</ol></div>`]]\n        					</div>\n    					</div>\n    				</div>\n				</div>\n			</div>\n<script language=\"javascript\">\n    jQuery(document).ready(function($) {\n        $(\".selected-limiter\").html($(\'.select-limiter li a.selected\').html());\n         $(\".selected-order\").html($(\'.select-order li a.selected\').html());                   \n    });\n</script>\n    <script type=\"text/javascript\">                \n        jQuery(document).ready(function($){\n           $(\'.selected-limiter\').click(function(){\n            $(\'.select-limiter\').toggleClass(\'current-item\');\n            });\n            $(\'.selected-order\').click(function(){\n                $(\'.select-order\').toggleClass(\'current-item\');\n            });\n        });\n    </script>\n<ul class=\"products-grid m-lr first last odd\">[!catalogItems!]</ul>\n<script type=\"text/javascript\">decorateGeneric($$(\'ul.products-grid\'), [\'odd\',\'even\',\'first\',\'last\'])</script>\n<div class=\"toolbar-bottom\">\n        <div class=\"toolbar\">\n	<div class=\"container\">\n		<div class=\"row\">\n    \n       \n    	\n<div class=\"pager col-lg-12\">[[if? &is=`[+catid_totalPages+]:eq:1` &then=` ` &else=`<div class=\"pages\"><ol>[+catid_previous+][+catid_pages+][+catid_next+]</ol></div>`]]</div>\n	    \n    	</div>\n	</div>\n</div>\n\n    </div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('50','catalogWatchInner','','0','10','0','<li class=\"col-lg-4 col-md-4 col-sm-6 col-xs-12 item sub-item\" style=\"min-height: 500px;\">\n	<div class=\"item-wrap\">  \n		<div class=\"item-image\">                        \n			<a href=\"[~[+id+]~]\" class=\"product-image\" title=\"[+pagetitle+]\">\n				<img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=270&h=300&far=1&f=png`]]\" alt=\"[+pagetitle+]\" />\n				[[if? &is=`[+status+]:!empty:` &then=`<img class=\"status\" src=\"[[phpthumb? &input=`[[DocInfo? &docid=`[+status+]` &tv=`1` &field=`image`]]` &options=`w=90,f=png`]]\" />`]]\n			</a>\n		</div>\n        <div class=\"item-info\">    \n			<div class=\"item-inner\">                              \n				<div class=\"item-title product-name\"><a href=\"[~[+id+]~]\">[+pagetitle+]</a>[[if? &is=`[+nalichie+]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[+indate+]`]]</div>` &else=``]]</div>\n				<div class=\"item-desc product-desc\">[[if? &is=`[+longtitle+]:!empty` &then=`<p>[+longtitle+]</p>` &else=``]]\n					<!--<p>Производитель: [+proizvoditel+]</p>\n					<p>Серия: [[DocInfo? &docid=`[+parent+]` &field=`menutitle`]]</p>\n					<p>Стекло: [+steklo+]</p>\n					<p>Механизм: [+mechanism+]</p>\n					<p>Водозащита: [+vodozashita+]</p>-->\n				</div>\n				<div class=\"item-content\">\n					<div class=\"wrap-price\"> \n						<div class=\"price-box\">\n                       		<span class=\"regular-price\" id=\"product-price-14\">\n								<span class=\"price\">[[formatPrice? &price=`[+price+]`]] руб.</span>\n							</span>\n                        </div>\n					</div>                                 \n							</div>\n						</div>\n					</div>    \n                </div>        \n                \n            </li>','0');
