INSERT INTO `modx_site_htmlsnippets` VALUES ('55','catalogOtherInner','','0','10','0','<li class=\"col-lg-4 col-md-4 col-sm-6 col-xs-12 item sub-item\" style=\"min-height: 320px;\">\n	<div class=\"item-wrap\">  \n		<div class=\"item-image\">                        \n			<a href=\"[~[+id+]~]\" class=\"product-image\" title=\"[+pagetitle+]\">\n				<img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=270&h=300&far=1&f=png`]]\" alt=\"[+pagetitle+]\" />\n				[[if? &is=`[+status+]:!empty:` &then=`<img class=\"status\" src=\"[[phpthumb? &input=`[[DocInfo? &docid=`[+status+]` &tv=`1` &field=`image`]]` &options=`w=90,f=png`]]\" />`]]\n			</a>\n		</div>\n        <div class=\"item-info\">    \n			<div class=\"item-inner\">                              \n				<div class=\"item-title product-name\"><a href=\"[~[+id+]~]\">[+pagetitle+]</a>[[if? &is=`[+nalichie+]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[+indate+]`]]</div>` &else=``]]</div>\n				<div class=\"item-desc product-desc\">[[if? &is=`[+longtitle+]:!empty` &then=`<p>[+longtitle+]</p>` &else=``]]\n					<!--<p>Производитель: [+proizvoditel+]</p>\n					[[if? &is=`[+size-brelok+]:!empty:` &then=`<p>Размеры: [+size-brelok+]</p>`]]\n					[[if? &is=`[+water-brelok+]:!empty:` &then=`<p>Водонепроницаемость: [+water-brelok+]</p>`]]\n					[[if? &is=`[+how-long+]:!empty:` &then=`<p>видимость: [+how-long+]</p>`]]-->\n				</div>\n				<div class=\"item-content\">\n					<div class=\"wrap-price\"> \n						<div class=\"price-box\">\n                       		<span class=\"regular-price\" id=\"product-price-14\">\n								<span class=\"price\">[[formatPrice? &price=`[+price+]`]] руб.</span>\n							</span>\n                        </div>\n					</div>                                 \n							</div>\n						</div>\n					</div>    \n                </div>        \n                \n            </li>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('56','table_fix','','0','1','0','<script type=\"text/javascript\">\njQuery(document).ready(function(){\n	jQuery(\".chars_col tr, .shop-cart tr\").each(function(){\n		jQuery(\"td\",this).last().addClass(\"blnone\");\n	})\n	jQuery(\".shop-cart tr\").each(function(){\n		jQuery(\"td\",this).first().addClass(\"brnone\");\n	})\n	jQuery(\".chars_col tr, .shop-cart tr\").last().addClass(\"bbnone\");\n	jQuery(\".thead a\").on(\"click\",function(e){\n		e.preventDefault();\n		var id=jQuery(this).attr(\'rel\');\n		jQuery(\'.thead a\').removeClass(\"sel\");\n		jQuery(this).addClass(\"sel\");\n		jQuery(\".chars_col .twrap\").addClass(\"hidden\");\n		jQuery(\"#\"+id).removeClass(\"hidden\");\n	})\n})\n</script>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('57','main_info','','0','7','0','<!--<h1>[*pagetitle*]</h1>\n		[[if? &is=`[*longtitle*]:!empty:` &then=`<div class=\"ptnarrow info\">[*longtitle*]</div>`]]\n		[[if? &is=`[*articul*]:!empty:` &then=`<div class=\"ptnarrow info\">Артикул: [*articul*]</div>`]]\n		<div class=\"item_text\">[*content*]</div>\n		<div class=\"price\">[[formatPrice? &price=`[*price*]`]].-</div>\n[[if? &is=`[*nalichie*]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[*indate*]`]]</div>` &else=`\n		<div class=\"shk-item\">\n			<form action=\"[~281~]\" method=\"post\" class=\"element\">\n						<input type=\"hidden\" name=\"shk-id\" value=\"[*id*]\" />\n						<input type=\"hidden\" name=\"shk-name\" value=\"[*pagetitle*]\" />\n						<input type=\"hidden\" name=\"shk-count\" value=\"1\" size=\"2\" maxlength=\"3\" />\n						<button type=\"submit\">Купить</button>\n				[[if? &is=`[*price*]:>:900` &then=`<a href=\"[~299~]\" class=\"one_click fancybox.ajax\">Купить в 1 клик</a>` &else=``]]\n			</form>\n</div>\n`]]-->\n\n<div class=\"wrap-left col-lg-4 col-md-4 col-sm-4 col-xs-12\">\n	<div class=\"product-shop\">\n		<div class=\"product-name\">\n			<h1>[*pagetitle*]</h1>\n			[[if? &is=`[*longtitle*]:!empty:` &then=`<h3>[*longtitle*]</h3>`]]\n		</div>\n		<div class=\"product-code\">\n			[[if? &is=`[*articul*]:!empty:` &then=`<label>Артикул: </label><span class=\"pcode\">[*articul*]</span>`]]						\n		</div>	\n		<div class=\"price-box\">\n			<span class=\"regular-price\" id=\"product-price-14\">\n				<span class=\"price\">[[formatPrice? &price=`[*price*]`]] руб.</span>\n			</span>            \n		</div>\n		[[if? &is=`[*nalichie*]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[*indate*]`]]</div>` &else=`\n		<div class=\"add-to-box group-item\">\n			<div class=\"add-to-cart\">\n				<form action=\"[~281~]\" method=\"post\" class=\"element\">\n						<input type=\"hidden\" name=\"shk-id\" value=\"[*id*]\" />\n						<input type=\"hidden\" name=\"shk-name\" value=\"[*pagetitle*]\" />\n						<input type=\"hidden\" name=\"shk-count\" value=\"1\" size=\"2\" maxlength=\"3\" />\n						<button type=\"submit\" class=\"button btn-cart\">Купить</button>\n				[[if? &is=`[*price*]:>:900` &then=`<a href=\"[~299~]\" class=\"one_click fancybox.ajax button btn-cart\">Купить в 1 клик</a>` &else=``]]\n				</form>\n			</div>\n		</div>\n`]]\n	</div>\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('58','table_params','','0','7','0','<ul class=\"thead ptnarrow\">\n				<li class=\"first\"><a href=\"#\" rel=\"tab1\" class=\"sel\"><i></i><span></span>Характеристики</a></li>\n				<li><a href=\"#\" rel=\"tab2\"><span></span>Оплата</a></li>\n				<li class=\"last\"><span></span><a href=\"#\" rel=\"tab3\">Доставка</a></li>\n			</ul>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('59','oplata_dostavka','','0','7','0','<div id=\"vt_tab_reviewform\" class=\"tab-content\" style=\"display: none;\">                       \n	<div class=\"box-collateral box-reviews\" id=\"customer-reviews\">\n        [[DocInfo? &docid=`3` &field=`content`]]\n	</div>\n</div>\n<div id=\"vt_tab_deliv\" class=\"tab-content\" style=\"display: none;\">                       \n	<div class=\"box-collateral box-reviews\" id=\"delivery\">\n        [[DocInfo? &docid=`4` &field=`content`]]\n	</div>\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('60','bottom_form','','0','7','0','<div class=\"bottom_form shk-item\">\n	<form action=\"[~281~]\" method=\"post\" class=\"element\">\n		[[if? &is=`[*nalichie*]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[*indate*]`]]</div>` &else=`\n			<div class=\"price\">[[formatPrice? &price=`[*price*]`]].-</div>\n					<input type=\"hidden\" name=\"shk-id\" value=\"[*id*]\" />\n					<input type=\"hidden\" name=\"shk-name\" value=\"[*pagetitle*]\" />\n					<input type=\"hidden\" name=\"shk-count\" value=\"1\" size=\"2\" maxlength=\"3\" />\n					<button type=\"submit\">Купить</button>\n					[[if? &is=`[*price*]:>:900` &then=`<a href=\"[~299~]\" class=\"one_click fancybox.ajax\">Купить в 1 клик</a>` &else=``]]\n		`]]\n		</form>\n	<h1>[*pagetitle*]</h1>\n		[[if? &is=`[*longtitle*]:!empty:` &then=`<div class=\"ptnarrow info\">[*longtitle*]</div>`]]\n		[[if? &is=`[*articul*]:!empty:` &then=`<div class=\"ptnarrow info\">Артикул: [*articul*]</div>`]]\n	<div class=\"clear\"></div>\n		\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('61','photoItem','','0','7','0','\n<div class=\"wrap-middle col-lg-4 col-md-4 col-sm-4 col-xs-12\">\n						<div class=\"product-img-box\">\n							<div class=\"vt-detail-image\">\n    							<div class=\"product-image-zoom\">\n               		 				<div id=\"wrap\" style=\"top:0px;z-index:1;position:relative;\">\n										<a id=\"vt_cloudzoom\" class=\"cloud-zoom\" rel=\"zoomWidth:250, zoomHeight:250, adjustX: 20, adjustY: -3\" href=\"[*item_image*]\" class=\"mphoto\" title=\"[*pagetitle*]\"><img id=\"image\" src=\"[*item_image*]\" alt=\"[*pagetitle*]\" style=\"display: block;\"/></a>\n									</div>\n        							<div class=\"popup-btn  hidden-phone\">\n											\n											<a style=\"display:none;\" class=\"fancybox-image-hidden\" data-fancybox-group=\"button\" href=\"http://demo.7uptheme.com/olec/media/catalog/product/cache/1/thumbnail/9df78eab33525d08d6e5fb8d27136e95/5/_/5.png\">\n											</a>\n											\n											<a style=\"display:none;\" class=\"fancybox-button fancybox-image-hidden \" data-fancybox-group=\"button\" href=\"http://demo.7uptheme.com/olec/media/catalog/product/cache/1/thumbnail/9df78eab33525d08d6e5fb8d27136e95/7/_/7.png\">\n											</a>\n											\n											<a style=\"display:none;\" class=\"fancybox-button fancybox-image-hidden \" data-fancybox-group=\"button\" href=\"http://demo.7uptheme.com/olec/media/catalog/product/cache/1/thumbnail/9df78eab33525d08d6e5fb8d27136e95/8/_/8.png\">\n											</a>\n											\n											<a style=\"display:none;\" class=\"fancybox-button fancybox-image-hidden \" data-fancybox-group=\"button\" href=\"http://demo.7uptheme.com/olec/media/catalog/product/cache/1/thumbnail/9df78eab33525d08d6e5fb8d27136e95/6/_/6.png\">\n											</a>\n         							</div>\n    							</div>\n							</div>\n\n   \n<div class=\"more-views slide-gallery\">\n    <div class=\"wrap-jCarouselLite\">\n\n        <div class=\"jCarouselLite\" style=\"visibility: visible; overflow: hidden; position: relative; z-index: 2; left: 0px; width: 363px;\">\n            <ul style=\"margin: 0px; padding: 0px; position: relative; list-style-type: none; z-index: 1; width: 1210px; left: -363px;\">\n				[!multiTV? &rowTpl=`photos` &tvName=`photos`!]\n			</ul>\n\n        </div>\n    </div>\n       \n    <span class=\"prev\">prev</span> \n     <span class=\"next\">next</span>\n    </div>\n <script type=\"text/javascript\">\n    function init(){\n      \n        device = jQuery.fn.detectDevice(); \n        number_visible = 3 ;\n        \n        jQuery(\".jCarouselLite\").jCarouselLite({\n            btnNext: \".more-views .next\",\n            btnPrev: \".more-views .prev\",\n            visible: number_visible,\n            start: 0,\n            circular: true,\n            speed: 300,\n            //vertical: true,\n        });                 \n    }\n    init();  \n</script>\n\n<script type=\"text/javascript\">\n   \n    jQuery(document).ready(function($){\n        \n        $(\'.cloud-zoom, .cloud-zoom-gallery\').CloudZoom();  \n        \n        $(\'.fancybox-image-hidden\').each(function(){\n            attr = $(this).attr(\'href\');\n            href_current = $(\'a#vt_popup\').attr(\'href\');\n            if( attr == href_current ){\n                $(this).removeClass(\"fancybox-button\");\n            }\n        });\n        \n        $(\'a.cloud-zoom-gallery\').bind(\'click\', function(){\n            $(\'a#vt_popup\').attr(\'href\', $(this).attr(\'href\'));\n            $(\'.fancybox-image-hidden\').addClass(\"fancybox-button\");\n            $(\'.fancybox-image-hidden\').each(function(){\n                attr = $(this).attr(\'href\');\n                href_current = $(\'a#vt_popup\').attr(\'href\');\n                if( attr == href_current ){                 \n                    $(this).removeClass(\"fancybox-button\");\n                }\n            });\n        });         \n        \n        $(\".fancybox-button\").fancybox({\n            prevEffect      : \'none\',\n            nextEffect      : \'none\',\n            closeBtn        : true,\n            closeClick : true,\n            nextClick  : true,\n            mouseWheel : false, \n            helpers     : {\n                title   : true,\n                buttons : {}\n            },\n            afterLoad : function() {\n                this.title = \'Image \' + (this.index + 1) + \' of \' + this.group.length + (this.title ? \' - \' + this.title : \'\');\n            }          \n        });\n            \n        \n                \n        $(\'.jCarouselLite ul li a\').each(function(){\n            if($(this).hasClass(\'actived\')){\n                $(this).parent().addClass(\'selected\');  \n            }               \n        });                    \n        $(\'.jCarouselLite ul li a\').click(function(){\n            $this = $(this);\n            $(\'.jCarouselLite ul li a\').parent().removeClass(\'selected\');\n            if($this.hasClass(\'actived\')){              \n                $this.parent().addClass(\'selected\');\n            }\n        });\n    });\n</script>\n						</div>\n					</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('62','fancybox','','0','1','0','<!-- Add fancyBox -->\n<link rel=\"stylesheet\" href=\"assets/templates/traser/js/fancybox/jquery.fancybox.css?v=2.1.5\" type=\"text/css\" media=\"screen\" />\n<script type=\"text/javascript\" src=\"assets/templates/traser/js/fancybox/jquery.fancybox.pack.js?v=2.1.5\"></script>\n<!-- Optionally add helpers - button, thumbnail and/or media -->\n<link rel=\"stylesheet\" href=\"assets/templates/traser/js/fancybox/helpers/jquery.fancybox-buttons.css?v=1.0.5\" type=\"text/css\" media=\"screen\" />\n<script type=\"text/javascript\" src=\"assets/templates/traser/js/fancybox/helpers/jquery.fancybox-buttons.js?v=1.0.5\"></script>\n<script type=\"text/javascript\" src=\"assets/templates/traser/js/fancybox/helpers/jquery.fancybox-media.js?v=1.0.6\"></script>\n\n<link rel=\"stylesheet\" href=\"assets/templates/traser/js/fancybox/helpers/jquery.fancybox-thumbs.css?v=1.0.7\" type=\"text/css\" media=\"screen\" />\n<script type=\"text/javascript\" src=\"assets/templates/traser/js/fancybox/helpers/jquery.fancybox-thumbs.js?v=1.0.7\"></script>\n<script type=\"text/javascript\">\n	jQuery(document).ready(function(){\n		jQuery(\".mphoto\").on(\"click\",function(e){\n			e.preventDefault();\n			var par=jQuery(this).parent();\n			if (jQuery(\".images\",par).length){\n				jQuery(\".images a\",par).first().trigger(\"click\");\n			} else {\n				var hr=jQuery(this).attr(\"href\");\n				jQuery.fancybox.open([\n					{\n						href : hr,\n						title : \'[*pagetitle*]\'\n					}    \n				], {\n					padding : 0   \n				});\n			}\n		});\n		jQuery(\".fancybox-thumb\").fancybox({\n			prevEffect	: \'none\',\n			nextEffect	: \'none\',\n			helpers	: {\n				title	: {\n					type: \'outside\'\n				},\n				thumbs	: {\n					width	: 50,\n					height	: 50\n				}\n			},\n			padding:0\n		});\n	})\n	jQuery(document).ready(function(){\n		var elid\n		jQuery(\".one_click\").fancybox({\n			beforeLoad:function(){\n				var e=this.element.parent();\n				elid=jQuery(\'input[name=\"shk-id\"]\',e).val();\n			},\n			afterShow:function(){\n				jQuery(\"#oneClick input[name=\'itemid\']\").val(elid);\n				jQuery(\"#oneClick\").on(\"submit\",function(){\n					jQuery.ajax({\n						type:\'POST\',\n						cache:false,\n						url:\'[~299~]\',\n						data:jQuery(this).serialize(),\n						success:function(data){\n							jQuery(\'body\').append(\"<div id=\'appended\'>\");\n							jQuery(\"#appended\").html(data);\n							var h=jQuery(\"#appended form\").html();\n							jQuery(\"#appended\").remove();\n							jQuery(\"#oneClick\").html(h);\n						}\n					})\n					return false;\n				})\n			}\n		});\n	})\n</script>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('63','searchFormTpl','','0','10','0','[+as.showInputForm:is=`1`:then=`\n<form id=\"[+as.formId+]\" action=\"[+as.formAction+]\" method=\"post\">\n    [+as.showAsId:is=`1`:then=`<input type=\"hidden\" name=\"[+as.asName+]\" value=\"[+as.asId+]\" />`+]\n    <input type=\"hidden\" name=\"advsearch\" value=\"[+as.advSearch+]\" />\n    [+as.liveSearch:is=`0`:then=`\n    \n            <input id=\"[+as.submitId+]\" type=\"submit\" name=\"sub\" value=\"\" />\n    \n    `+]\n      <input id=\"[+as.inputId+]\"  type=\"text\" name=\"search\" value=\"[+as.inputValue+]\"[+as.inputOptions+] />\n</form>\n`+]','0');
