INSERT INTO `modx_site_htmlsnippets` VALUES ('70','sk_cartTplInner','','0','10','0','[[if? &is=`[+id+]:eq:284` &then=`` &else=`\n<tr class=\"cart-order\">\n	<td width=\"70%\" align=\"left\">\n		<div class=\"cart-item\">\n			[[getItemInfo? &id=`[+id+]`]]\n			\n			<a href=\"[+url_del_item+]\" title=\"Удалить\" class=\"shk-del\"><img src=\"assets/snippets/shopkeeper/style/default/img/delete.gif\" border=\"0\" width=\"17\" height=\"17\" alt=\"Удалить\" /></a>\n			<div class=\"clear\"></div>\n		</div>\n	</td>\n	<td width=\"15%\" nowrap=\"nowrap\" style=\"text-align: center;\"><button type=\"button\" class=\"minus quant\">-</button><input class=\"items-count input-text\" type=\"text\" size=\"2\" name=\"count[]\" maxlength=\"3\" title=\"изменить количество\" value=\"[+count+]\" data=\"index_[+index+]\" /><button type=\"button\" class=\"plus quant\">+</button></td>\n  <td width=\"15%\" nowrap=\"nowrap\">[+price_total+] [+currency+]</td>\n</tr>\n`]]','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('71','cart_bind','','0','1','0','<link href=\"assets/templates/traser/js/chosen/chosen.css\" rel=\"stylesheet\" type=\"text/css\" />\n<script type=\"text/javascript\" src=\"assets/templates/traser/js/chosen/chosen.jquery.js\"></script>\n<script type=\"text/javascript\">\n	var oldvalue=0;\n	var dostavkaArr = new Array();\n	function setCartActionsCallback(f){\n		jQuery.ajax({\n			type:\'POST\',\n			url:\'[~282~]\',\n			success:function(data){\n				var newval=data;\n				if (data==-1){\n					window.location.href=\"[(site_url)]\";\n				}\n				if (data==-2){\n					window.location.href=\"[~[*id*]~]\";\n				}\n				\n			}\n		})\n	}\n	\n	function fixOplata(){\n		var b=jQuery(\"select[name=\'etown\']\").val();\n		jQuery(\"#oplata .row\").removeClass(\"hidden\");\n		fixDostavka();\n		if (b!=1) {\n			jQuery(\"#oplata .row\").eq(3).addClass(\"hidden\");\n			jQuery(\"#dostavka .row\").eq(5).addClass(\"hidden\");\n			jQuery(\"#dostavka .row\").eq(0).addClass(\"hidden\");\n			\n			\n			\n		}\n		if (dostavkaArr[b]==\"4\" || dostavkaArr[b]==4)  {\n					\n					} else {\n						jQuery(\"#dostavka .row\").eq(4).addClass(\"hidden\");\n						\n					}\n	\n	};\n	function fixTown(c){\n		jQuery(\"#dostavka input\").prop(\"checked\",false);\n		jQuery(\".oplata label\").removeClass(\"ichecked\");\n		jQuery(\"select[name=\'etown\']\").val(\"\");\n		jQuery.ajax({\n			type:\'POST\',\n			url:\'[~[*id*]~]\',\n			cache:false,\n			data:{country:c},\n			success:function(data){\n				jQuery(\"select[name=\'etown\']\").html(data);\n				jQuery(\"select[name=\'etown\']\").trigger(\"chosen:updated\");\n				jQuery.refreshCart(true);\n			}\n		})\n		fixDostavka();\n	}\n	function fixDostavka(){\n		var a=jQuery(\"select[name=\'ecountry\']\").val();\n		var b=jQuery(\"select[name=\'etown\']\").val();\n		jQuery(\"#dostavka .row\").removeClass(\"hidden\");\n		jQuery(\"#oplata .row\").removeClass(\"hidden\");\n		if (b!=1 && b!=\"\" && a!=175) jQuery(\"#oplata .row\").eq(3).addClass(\"hidden\");\n		if (a!=\"\" && a!=175){\n			jQuery(\"#dostavka .row\").addClass(\"hidden\");\n			\n			jQuery(\"#dostavka .row\").eq(1).removeClass(\"hidden\");\n			jQuery(\"#dostavka .row\").eq(3).removeClass(\"hidden\");\n			jQuery(\"#oplata .row\").eq(3).addClass(\"hidden\");\n			\n		} else {\n			if (a!=\"\") {\n				\n				jQuery(\"#dostavka .row\").eq(1).addClass(\"hidden\");\n				jQuery(\"#dostavka .row\").eq(3).addClass(\"hidden\");\n				\n				/*jQuery(\"#oplata .row\").eq(3).addClass(\"hidden\");*/\n				if (b!=\"\"){\n					if (dostavkaArr[b]==\"4\" || dostavkaArr[b]==4)  {\n						\n					} else {\n						jQuery(\"#dostavka .row\").eq(4).addClass(\"hidden\");\n					}\n				}\n			}\n		}\n	}\n	\n	function fixInputs(){\n		var a=jQuery(\"select[name=\'ecountry\']\").val();\n		var b=jQuery(\"select[name=\'etown\']\").val();\n		jQuery(\"#dostavka .row\").removeClass(\"hidden\");\n		jQuery(\"#oplata .row\").removeClass(\"hidden\");\n		if (b!=\"\" && b!=1) jQuery(\"#oplata .row\").eq(3).addClass(\"hidden\");\n		if (a==175){\n			jQuery(\"#dostavka .row\").eq(1).addClass(\"hidden\");\n			jQuery(\"#dostavka .row\").eq(3).addClass(\"hidden\");\n			jQuery(\"#dostavka .row\").eq(6).addClass(\"hidden\");\n			if (b!=\"\" && b!=1){\n				jQuery(\"#dostavka .row\").eq(0).addClass(\"hidden\");\n				jQuery(\"#dostavka .row\").eq(5).addClass(\"hidden\");\n				\n			}\n		} else {\n			if (a!=\"\"){\n				jQuery(\"#dostavka .row\").addClass(\"hidden\");\n				jQuery(\"#dostavka .row\").eq(1).removeClass(\"hidden\");\n				jQuery(\"#dostavka .row\").eq(3).removeClass(\"hidden\");\n				jQuery(\"#oplata .row\").eq(3).addClass(\"hidden\");\n			}\n		}\n		if (b!=\"\"){\n					if (dostavkaArr[b]==\"4\" || dostavkaArr[b]==4)  {\n						\n					} else {\n						jQuery(\"#dostavka .row\").eq(4).addClass(\"hidden\");\n					}\n				}\n	}\n	function changeQuantity(v,ob){\n		jQuery.ajax({\n			type:\'POST\',\n			url:\'[~[*id*]~]\',\n			cache:false,\n			data:{a_quant:v,a_item:ob},\n			success:function(data){\n				switch (data){\n					case \'-1\': window.location.href=\"[~[*id*]~]\"; break;\n					default:\n						if (jQuery(\"#shopOrderForm\").length==0) {\n							window.location.href=\"[~[*id*]~]\"\n						}\n						jQuery.refreshCart(true);\n						break;\n				}\n			}\n		})\n	}\n	jQuery(document).ready(function(){\n		jQuery.ajax({\n			type:\'POST\',\n			url:\'[~[*id*]~]\',\n			cache:false,\n			data:{type:\'dhl\'},\n			success:function(data){\n				dostavkaArr=JSON.parse(data);\n				fixInputs();\n			}\n		})\n		\n		\n		jQuery(\".row select\").chosen();\n		jQuery(\".totalCart\").html(jQuery(\"#cartInner .buttons\").html());\n		jQuery(document).on(\"click\",\".quant\",function(){\n			var ob,val,old;\n			var data;\n			\n			if (jQuery(this).hasClass(\"minus\")){\n				ob=jQuery(this).next();\n				old=parseInt(jQuery(ob).val());\n				val=old-1;\n			} else {\n				ob=jQuery(this).prev();\n				old=parseInt(jQuery(ob).val());\n				val=old+1;\n			}\n			if (val<1) val=1;\n			jQuery(ob).val(val);\n			if (old !=val){\n				changeQuantity(val, jQuery(ob).attr(\"data\"));\n			}\n		})\n		jQuery(\".oplata label\").on(\"click\", function(){\n			var ty=jQuery(this).find(\"input\").attr(\"name\");\n			var ob=\"#dostavka\";\n			if (ty==\"opla\") ob=\"#oplata\";\n			jQuery(ob+\" label\").removeClass(\"ichecked\");\n			jQuery(this).addClass(\"ichecked\");\n			if (ob==\"#dostavka\"){\n				jQuery.ajax({\n					type:\'POST\',\n					url:\'[~[*id*]~]\',\n					cache:false,\n					data:{action_a:\'cart_add\',v:jQuery(this).find(\"input\").val()},\n					success:function(data){\n						jQuery.refreshCart(true);\n					}\n				})\n			}\n		})\n	})\n</script>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('73','cartRemTpl','','0','10','0','<div class=\"image\">\n				<a href=\"[+link+]\" title=\"[+name+]\"><img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=100,h=164,ra=90,far=1,f=jpeg`]]\" alt=\"[+name+]\" /></a>\n			</div>\n			<h3><a href=\"[+link+]\">[+name+]</a></h3>\n			[[if? &is=`[+longtitle+]:!empty:` &then=`<p class=\"ptnarrow\">[+longtitle+]</p>` &else=` `]]\n			[[if? &is=`[+articul+]:!empty:` &then=`<p class=\"ptnarrow\">Артикул: [+articul+]</p>` &else=` `]]\n			<p class=\"descr\">[[if? &is=`[+proizvoditel+]:!empty:` &then=`Производитель: [+proizvoditel+]<br />` &else=` `]]\n				Материал: [+material+]<br />\n				Размер: [+razmer+]<br />\n				Категория: [[DocInfo? &docid=`[+remtip+]` &field=`pagetitle`]]<br />\n			</p>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('74','cartOtherTpl','','0','10','0','<div class=\"image\">\n				<a href=\"[+link+]\" title=\"[+name+]\"><img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=100&h=164&far=1&f=png`]]\" alt=\"[+name+]\" /></a>\n			</div>\n			<h3><a href=\"[+link+]\">[+name+]</a></h3>\n			[[if? &is=`[+articul+]:!empty:` &then=`<p class=\"ptnarrow\">Артикул: [+articul+]</p>` &else=` `]]\n			<p class=\"descr\">[[if? &is=`[+proizvoditel+]:!empty:` &then=`Производитель: [+proizvoditel+]<br />` &else=` `]]\n				[[if? &is=`[+material+]:!empty:` &then=`Материал: [+material+]<br />` &else=` `]]\n				[[if? &is=`[+size-brelok+]:!empty:` &then=`Размеры: [+size-brelok+]<br />` &else=` `]]\n				[[if? &is=`[+water-brelok+]:!empty:` &then=`Водонепроницаемость: [+water-brelok+]<br />` &else=` `]]\n				[[if? &is=`[+how-long+]:!empty:` &then=`Видимость: [+how-long+]` &else=` `]]\n			</p>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('72','cartWatchTpl','','0','10','0','<div class=\"image\">\n				<a href=\"[+link+]\" title=\"[+name+]\"><img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=100&h=164&far=1&f=png`]]\" alt=\"[+name+]\" /></a>\n			</div>\n			<h3><a href=\"[+link+]\">[+name+]</a></h3>\n			[[if? &is=`[+longtitle+]:!empty:` &then=`<p class=\"ptnarrow\">[+longtitle+]</p>` &else=` `]]\n			[[if? &is=`[+articul+]:!empty:` &then=`<p class=\"ptnarrow\">Артикул: [+articul+]</p>` &else=` `]]\n			<p class=\"descr\">[[if? &is=`[+proizvoditel+]:!empty:` &then=`Производитель: [+proizvoditel+]<br />` &else=` `]]\n				Серия: [+parent+]<br />\n				Стекло: [+steklo+]<br />\n				Механизм: [+mechanism+]<br />\n				Водозащита: [+vodozashita+]<br />\n			</p>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('75','comments','','0','9','0','<div class=\"soputka\">\n<h1>Последние отзывы</h1>\n[!JotX? &captcha=`1` &moderated=`1` &notifyEmails=`sergey@timelight.ru`!]\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('77','shopOrderForm','','0','10','0','[+validationmessage+]\n<form method=\"post\" action=\"[~[*id*]~]\" id=\"shopOrderForm\" class=\"orderForm\" enctype=multipart/form-data>\n		<fieldset>\n		<!-- <div class=\"content oplata\" id=\"dostavka\">\n				 <h2><font color=\"red\">ВНИМАНИЕ!</font> <font color=\"#939598\">Расписание работы магазина в майские праздники</font></h2>\n				<div class=\"clear\"></div>\n				Пожалуйста, будьте внимательны — с 29 апреля по 13 мая 2018 года магазин <font color=\"red\">не работает.</font> Все заказы, сделанные в период с 29.04.2018 по 13.05.2018 включительно, будут обработаны и отправлены покупателям <font color=\"red\">после 14 мая 2018 года.</font> \n				<div class=\"clear\"></div>\n			</div> -->\n			<!-- <div class=\"content oplata\" id=\"dostavka\">\n				 <h2><font color=\"red\">ВНИМАНИЕ!</font> <font color=\"#939598\">Расписание работы магазина в новогодние праздники</font></h2>\n				<div class=\"clear\"></div>\n				Пожалуйста, будьте внимательны — с 30 декабря 2017 по 8 января 2018 магазин <font color=\"red\">не работает.</font> Все заказы, сделанные в период с 30.12.2017 по 08.01.2018 включительно, будут обработаны и отправлены покупателям <font color=\"red\">после 9 января 2018 года.</font> \n				<div class=\"clear\"></div>\n			</div> -->\n			<div class=\"content\">\n				<h2>Личные данные</h2>\n				<div class=\"note\"><span class=\"required\">*</span> - поля, отмеченные звездочкой, обязательны для заполнения.</div>\n				<div class=\"clear\"></div>\n				<input type=\"hidden\" name=\"formid\" value=\"shopOrderForm\" />\n				<input type=\"hidden\" name=\"reportTpl\" value=\"shopOrderReport\" eform=\"::::\" />\n				<div class=\"row first\">\n					<label for=\"ename\">Ф.И.О.<span class=\"required\">*</span></label>\n					<div class=\"input-box\">\n					<input class=\"input-text\" id=\"ename\" name=\"ename\" eform=\"Ф.И.О.::1\" value=\"[+ename+]\" />\n					</div>\n				</div>\n				<div class=\"row\">\n					<label for=\"ecountry\">Страна<span class=\"required\">*</span></label>\n					<div class=\"input-box\">\n					<select id=\"ecountry\" name=\"ecountry\" onchange=\"fixTown(this.value);\" data-placeholder=\"Выбор страны\" eform=\"::0::#EVAL return true;\">\n						<option></option>\n						[+countries+]\n					</select>\n					</div>\n				</div>\n				<div class=\"row first\">\n					<label for=\"email\">E-mail<span class=\"required\">*</span></label>\n					<div class=\"input-box\">\n					<input class=\"input-text\" id=\"email\" name=\"email\" eform=\"E-mail:email:1\" value=\"[+email+]\" />\n					</div>\n				</div>\n				<div class=\"row half\">\n					<label for=\"etown\">Город<span class=\"required\">*</span></label>\n					<div class=\"input-box\">\n					<select id=\"etown\" name=\"etown\" onchange=\"fixOplata();\" data-placeholder=\"Выбор города\" eform=\"::0::#EVAL return true;\">\n						<option></option>\n						[+towns+]\n					</select>\n					</div>\n				</div>\n				<div class=\"row half\">\n					<label for=\"eindex\">Индекс<span class=\"required\">*</span></label>\n					<div class=\"input-box\">\n					<input class=\"input-text\" id=\"eindex\" name=\"eindex\" eform=\"Индекс::1\" value=\"[+eindex+]\" />\n					</div>\n				</div>\n				<div class=\"row first\">\n					<label for=\"ephone\">Контактный телефон<span class=\"required\">*</span></label>\n					<div class=\"input-box\">\n					<input class=\"input-text\" id=\"ephone\" name=\"ephone\" eform=\"Телефон::1\" value=\"[+ephone+]\" />\n					</div>\n				</div>\n				<div class=\"row\">\n					<label for=\"eadsress\">Адрес доставки<span class=\"required\">*</span></label>\n					<div class=\"input-box\">\n					<input class=\"input-text\" id=\"eadsress\" name=\"eaddress\" eform=\"Адрес::1\" value=\"[+eaddress+]\" />\n					</div>\n				</div>\n				<div class=\"clear\"></div>\n			</div>\n			<div class=\"content oplata\" id=\"dostavka\">\n				<h2><font color=\"red\">Бесплатная</font><font color=\"#939598\"> доставка по России при покупке часов Traser</font></h2>\n				<div class=\"clear\"></div>\n				Доставку по России осуществляют курьерские службы SPSR, EMS,Pony Express по Москве - курьерская доставка.\n				При оформлении заказа, в графе «Способ доставки» выбирайте пункт «Бесплатная доставка <font color=\"red\">по России</font> при покупке часов Traser». \n				<div class=\"clear\"></div>\n			</div>\n			<div class=\"content oplata\" id=\"dostavka\">\n				<h2>Способ доставки</h2>\n				<div class=\"clear\"></div>\n				[+dostavka+]\n				<div class=\"clear\"></div>\n			</div>\n			<div class=\"content oplata\" id=\"oplata\">\n				<h2>Способы оплаты</h2>\n				<div class=\"clear\"></div>\n				[+oplata+]\n				<div class=\"clear\"></div>\n			</div>\n			<!-- <div class=\"content oplata\" id=\"dostavka\">\n				<h2><font color=\"red\">Только для предзаказа часов BALL:</font><font color=\"#939598\"> укажите в комментариях к заказу</font></h2>\n				<div class=\"clear\"></div>\n				На задней крышке часов возможно нанести персональную гравировку длиной 13 символов (только заглавные английские буквы и арабские цифры с учетом пробелов).\nЕсли вам необходима эта опция, напишите об этом в поле «Ваш комментарий к заказу».\n								<div class=\"clear\"></div>\n			</div> -->\n			<div class=\"content\">\n				<div class=\"row comment\">\n					<label for=\"ecomment\">Ваш комментарий к заказу</label>\n					<div class=\"input-box\">\n					<input class=\"input-text\" id=\"ecomment\" name=\"message\" value=\"[+message+]\" />\n					</div>\n					<div class=\"clear\"></div>\n				</div>\n			</div>\n			</fieldset>\n	</form>\n\n','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('78','dostavkaTpl','','0','10','0','<div class=\"row\">\n	<label class=\"[+checked+]\">\n		<input type=\"radio\" name=\"delivery\" value=\"[+id+]\" style=\"float: left; margin-right: 10px;\" [+selected+] />\n		<div class=\"i_img\"></div>\n		<div class=\"i_info\">\n			[+pagetitle+]<br />\n			<span class=\"required\">[+longtitle+]</span> [+description+]\n			<span class=\"price\">[+price+]</span>\n		</div>\n	</label>\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('79','oplataTpl','','0','10','0','<div class=\"row[+posted+]\">\n	<label class=\"[+checked+]\">\n		<input type=\"radio\" name=\"opla\" value=\"[+id+]\" style=\"float: left; margin-right: 10px;\" [+selected+] />\n		<div class=\"i_img\"></div>\n		<div class=\"i_info\">\n			[+pagetitle+]<br />\n			<span [+red+]>[+longtitle+]</span>\n		</div>\n	</label>\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('80','Duplicate of sk_cartTplInner','','0','10','0','[[if? &is=`[+id+]:eq:284` &then=`` &else=`\n<tr class=\"cart-order\">\n	<td width=\"70%\" align=\"left\">\n		<div class=\"cart-item\">\n			[[getItemInfo? &id=`[+id+]`]]\n			\n			<a href=\"[+url_del_item+]\" title=\"Удалить\" class=\"shk-del\"><img src=\"assets/snippets/shopkeeper/style/default/img/delete.gif\" border=\"0\" width=\"17\" height=\"17\" alt=\"Удалить\" /></a>\n			<div class=\"clear\"></div>\n		</div>\n	</td>\n	<td width=\"15%\" nowrap=\"nowrap\"><button type=\"button\" class=\"minus quant\"></button><input class=\"items-count\" type=\"text\" size=\"2\" name=\"count[]\" maxlength=\"3\" title=\"изменить количество\" value=\"[+count+]\" data=\"index_[+index+]\" /><button type=\"button\" class=\"plus quant\"></button></td>\n  <td width=\"15%\" nowrap=\"nowrap\">[+price_total+] [+currency+]</td>\n</tr>\n`]]','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('81','shopOrderReport','','0','10','0','<p><span>Здравствуйте, [+ename+]</span><xsl:value-of select=\"order_list/site_user_fio\">!</xsl:value-of></p>\n<p><span>Вами был оформлен&nbsp;</span><b>заказ №&nbsp;[+orderID+]&nbsp;<xsl:value-of select=\"order_list/order_account_number\"></xsl:value-of></b><span>на сайте&nbsp;</span><a href=\"http://%7Border_list/shop/site_alias_name%7D\"><xsl:value-of select=\"order_list/shop/site_alias_name\"></xsl:value-of></a><span>.</span></p>\n<p><span>[+orderData+]</span></p>\n<p><span>Выбранные Вами товары зарезервированы на нашем складе на 5 дней. За это время необходимо произвести оплату выбранным Вами способом. По истечению этого срока бронь автоматически снимается и наличие товаров не гарантируется.</span></p>\n<p><span><span>Доставка по указанному Вами адресу будет выполнена курьерской службой, которую Вы выбрали при оформлении заказа.&nbsp;</span></span></p>\n<p><span><span>При заказе доставки по Москве с Вами свяжется менеджер. Обработка заказов производится только в рабочее время.</span></span></p>\n<p></p>\n<p>Если у Вас возникли вопросы, мы с удовольствием на них ответим.</p>\n<p><span>С уважением,&nbsp;</span><br /><span>Официальный интернет-магазин www.traserh3.ru&nbsp;</span><br /><span>тел. +7 (495) 788-83-17<br/>e-mail: <a href=\"mailto:info@timelight.ru\">info@timelight.ru</a></span></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p><b>Данные покупателя:</b></p>\n<table cellpadding=\"3\">\n<tbody>\n<tr>\n<td>Ф.И.О.:</td>\n<td>[+ename+]</td>\n</tr>\n<tr>\n<td>E-mail:</td>\n<td><a href=\"mailto:[+email+]\">[+email+]</a></td>\n</tr>\n<tr>\n<td>Телефон:</td>\n<td>[+ephone+]</td>\n</tr>\n<tr>\n<td>Страна:</td>\n<td>[+country_name+]</td>\n</tr>\n<tr>\n<td>Город:</td>\n<td>[+city_name+]</td>\n</tr>\n<tr>\n<td>Индекс:</td>\n<td>[+eindex+]</td>\n</tr>\n<tr>\n<td>Адрес:</td>\n<td>[+eaddress+]</td>\n</tr>\n<tr>\n<td>Доставка:</td>\n<td>[+delivery_name+]</td>\n</tr>\n<tr>\n<td>Оплата:</td>\n<td>[+oplata_name+]</td>\n</tr>\n<tr>\n<td>Описание заказа:</td>\n<td>[+message+]</td>\n</tr>\n</tbody>\n</table>\n[+attachment+]','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('82','orderDataTpl','','0','10','0','<ul>\n[+loop+]\n  <li><b><a href=\"[+link+]\">[+name+]</a></b>, [+addit_data+] <b>x [+count+] шт.</b> = [+price+]</li>\n[+end_loop+]\n</ul>\n<p>Общая стоимость: <b>[+totalPrice+] [+currency+]</b></p>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('83','Duplicate of cart_actions','','0','1','0','<script type=\"text/javascript\">\n	function fillCartCallback(f){\n		$.ajax({\n			url:\'[~282~]\',\n			type:\'POST\',\n			cache:false,\n			success:function(data){\n				console.log(data);\n				if (data==1) {\n					window.location.href=\"[(site_url)][~281~]\";\n				}\n			}\n		})\n	}\n</script>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('85','oneClickTpl','','0','10','0','<form method=\"post\" action=\"[~[*id*]~]\" id=\"oneClick\" class=\"orderForm oneclick\">\n		<fieldset>\n			<div class=\"content\">\n				<h1>Купить в один клик</h1>\n				<div class=\"clear\"></div>\n				[+validationmessage+]\n				<input type=\"hidden\" name=\"formid\" value=\"oneclick\" />\n				<input type=\"hidden\" name=\"reportTpl\" value=\"oneClickReport\" eform=\"::::\" />\n				<input type=\"text\" name=\"itemid\" value=\"[+itemid+]\" eform=\"товар::1\" style=\"display:none;\" />\n				<div class=\"row\">\n 					<label for=\"ename\">Ваше имя<span class=\"required\">*</span></label>\n					<input id=\"ename\" name=\"ename\" eform=\"Имя::1\" value=\"[+ename+]\" />\n				</div>\n				<div class=\"row\">\n					<label for=\"ephone\">Телефон<span class=\"required\">*</span></label>\n					<input id=\"ephone\" name=\"ephone\" eform=\"Телефон::1\" value=\"[+ephone+]\" />\n				</div>\n				<div class=\"row\">\n					<label for=\"ephone\">Город<span class=\"required\">*</span></label>\n					<input id=\"ecity\" name=\"ecity\" eform=\"Город::1\" value=\"[+ecity+]\" />\n				</div>\n				<div class=\"row\">\n					<p>С вами свяжется менеджер и уточнит детали заказа.</p>\n				</div>\n				<div class=\"row comment\">\n					<label for=\"ecomment\">Комментарий к заказу</label>\n					<textarea id=\"ecomment\" name=\"message\">[+message+]</textarea>\n					<div class=\"clear\"></div>\n				</div>\n				<div class=\"row vericode\">\n					<label for=\"vericode\">Введите код с картинки</label>\n					<img class=\"feed\" src=\"[+verimageurl+]\" alt=\"Введите код\" />\n					<input type=\"text\" class=\"ver\" name=\"vericode\" id=\"vericode\" />\n				</div>\n				<div class=\"element justifyright\">\n					<button type=\"submit\">Отправить</button>\n				</div>\n				<div class=\"clear\"></div>\n			</div>\n		</fieldset>\n	</form>\n\n','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('86','fancybox2','','0','1','0','<!-- Add fancyBox -->\n<link rel=\"stylesheet\" href=\"assets/templates/traser/js/fancybox/jquery.fancybox.css?v=2.1.5\" type=\"text/css\" media=\"screen\" />\n<script type=\"text/javascript\" src=\"assets/templates/traser/js/fancybox/jquery.fancybox.pack.js?v=2.1.5\"></script>\n<script type=\"text/javascript\">\n	jQuery(document).ready(function(){\n		var elid\n		jQuery(\".one_click\").fancybox({\n			beforeLoad:function(){\n				var e=this.element.parent();\n				elid=jQuery(\'input[name=\"shk-id\"]\',e).val();\n			},\n			afterShow:function(){\n				jQuery(\"#oneClick input[name=\'itemid\']\").val(elid);\n				jQuery(\"#oneClick\").on(\"submit\",function(){\n					jQuery.ajax({\n						type:\'POST\',\n						cache:false,\n						url:\'[~299~]\',\n						data:jQuery(this).serialize(),\n						success:function(data){\n							jQuery(\'body\').append(\"<div id=\'appended\'>\");\n							jQuery(\"#appended\").html(data);\n							var h=jQuery(\"#appended form\").html();\n							jQuery(\"#appended\").remove();\n							jQuery(\"#oneClick\").html(h);\n						}\n					})\n					return false;\n				})\n			}\n		});\n	})\n</script>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('87','oneClickReport','','0','10','0','<p>В интернет-магазине Traser получен новый заказ в один клик.</p>\n<p><b>Подробности:</b></p>\n<table cellpadding=\"3\">\n	<tr><td>Товар:</td><td>[+item+]</td></tr>\n	<tr><td>Имя:</td><td>[+ename+]</td></tr>\n	<tr><td>Телефон:</td><td>[+ephone+]</td></tr>\n	<tr><td>Город:</td><td>[+ecity+]</td></tr>\n  <tr><td>Комментарий:</td><td>[+message+]</td></tr>\n</table>\n','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('88','oneClickThank','','0','10','0','<form>\n	<p>Ваш заказ принят. Наши менеджеры свяжутся с вами в ближайшее время.</p>\n</form>','0');
