INSERT INTO `modx_site_htmlsnippets` VALUES ('92','searchInnerItem','','0','10','0','<li class=\"col-lg-4 col-md-4 col-sm-6 col-xs-12 item sub-item\" style=\"min-height: 500px;\">\n	<div class=\"item-wrap\">  \n		<div class=\"item-image\">                        \n			<a href=\"[~[+id+]~]\" class=\"product-image\" title=\"[+pagetitle+]\">\n				<img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=270&h=300&far=1&f=png`]]\" alt=\"[+pagetitle+]\" />\n			</a>\n		</div>\n        <div class=\"item-info\">    \n			<div class=\"item-inner\">                              \n				<div class=\"item-title product-name\"><a href=\"[~[+id+]~]\">[+pagetitle+]</a>[[if? &is=`[+nalichie+]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[+indate+]`]]</div>` &else=``]]</div>\n				<div class=\"item-desc product-desc\">[[if? &is=`[+longtitle+]:!empty` &then=`<p>[+longtitle+]</p>` &else=``]]\n					\n				</div>\n				<div class=\"item-content\">\n					<div class=\"wrap-price\"> \n						<div class=\"price-box\">\n                       		<span class=\"regular-price\" id=\"product-price-14\">\n								<span class=\"price\">[[formatPrice? &price=`[+price+]`]] руб.</span>\n							</span>\n                        </div>\n					</div>                                 \n							</div>\n						</div>\n					</div>    \n                </div>        \n                \n            </li>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('93','photoItemRem','','0','7','0','<div class=\"photos\">\n	<a href=\"[*item_image*]\" class=\"mphoto\" title=\"[*pagetitle*]\"><img src=\"[[phpthumb? &input=`[*item_image*]` &options=`w=103,h=300,ra=90,far=1,f=jpeg,q=90`]]\" alt=\"[*pagetitle*]\" /></a>\n	[[if? &is=`[*status*]:!empty:` &then=`<img class=\"status reme\" src=\"[[phpthumb? &input=`[[DocInfo? &docid=`[*status*]` &tv=`1` &field=`image`]]` &options=`w=80,f=png`]]\" />`]]\n	[!multiTV? &tvName=`photos`!]\n</div>','0');
