INSERT INTO `modx_site_htmlsnippets` VALUES ('95','cartSmallInnerTpl','','0','10','0','<a href=\"[+link+]\" title=\"[+name+]\" class=\"product-image\"><img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=75&h=108&far=1&f=png`]]\" width=\"50\" height=\"50\" alt=\"[+name+]\"></a>\n        <div class=\"product-details\">\n        \n                <p class=\"product-name\"><a href=\"[+link+]\">[+name+]</a></p>\n        [[if? &is=`[+articul+]:!empty:` &then=`<p class=\"ptnarrow\">Артикул: [+articul+]</p>` &else=` `]]\n\n    \n                                <span class=\"price\">[+price+] руб.</span>                    \n\n\n    \n    \n            </div>','0');
