INSERT INTO `modx_site_htmlsnippets` VALUES ('99','robokassa','','0','0','0','<form id=\"fmain\" method=\"post\" action=\"http://auth.robokassa.ru:80/Merchant/Index.aspx?MrchLogin=[+mrh_login+]&amp;OutSum=[+out_summ+]&amp;InvId=[+inv_id+]&amp;IncCurrLabel=&amp;Desc=[+inv_desc+]&amp;SignatureValue=[+crc+]&amp;Shp_item=1&amp;Culture=ru&amp;Encoding=utf-8\">\n		<div class=\"formFL shadows lifted\">\n			<div class=\"element\">\n				<input type=\"text\" name=\"FreeOutSum\" value=\"\" maxlength=\"10\" style=\"display:none;\">\n				<a href=\"javascript:void(0)\" class=\"button\" onclick=\"fsubmit();\">Оплатить</button>\n				<img src=\"https://auth.robokassa.ru/Merchant/PaymentForm/Images/logo-l.png\">\n			</div>\n		</div>\n	</form>\n<style>\n	body {\n	margin: 0 auto;\n	padding: 0;\n	background-color: transparent;\n	color: #000;\n	font-family: Arial, Helvetica, sans-serif;\n}\n\n	.formFL div{text-align:center;}\n	.formFL button {\n		position:relative;\n		margin:-5px 10px 0 0;\n		top:-5px;\n}\n\n.formFL, .formM, .formS {\n	display: table;\n	border: 1px dashed rgb(182, 211, 234);\n	border-radius: 5px;\n	background: -webkit-linear-gradient(top, rgba(255,255,255,1) 0%,rgba(240,240,240,1) 100%);\n	background: linear-gradient(to bottom, rgba(255,255,255,1) 0%,rgba(240,240,240,1) 100%);\n}\n\n.formFL {\n	width: 448px;\n	height: 58px;\n}\n\n	.formFL.shadows {\n		width: 448px;\n		height: 58px;\n	}\n\n.formM {\n	width: 298px;\n	height: 58px;\n}\n\n	.formM.shadows {\n		width: 298px;\n		height: 60px;\n	}\n\n.formS {\n	width: 225px;\n	height: 43px;\n}\n\n	.formS.shadows {\n		width: 240px;\n		height: 45px;\n	}\n\n.formFL a,\n.formM a {\n	font-size: 11pt;\n}\n\n.formS a {\n	font-size: 9pt;\n}\n\n\n.formFL img,\n.formM img,\n.formS img {\n	position: relative;\n	top: 10px;\n}\n\n.formFL img,\n.formFL input,\n.formFL a,\n.formM img,\n.formM a {\n	margin-right: 5px;\n}\n\n.formFL input {\n	margin-top: 4px;\n	padding: 0 3pt;\n	width: 138px;\n	height: 36px;\n	border: 1px solid rgb(182, 211, 234);\n	border-radius: 5px;\n	background: -webkit-linear-gradient(top, rgba(230,230,230,1) 1%,rgba(255,255,255,1) 12%);\n	background: linear-gradient(to bottom, rgba(230,230,230,1) 1%,rgba(255,255,255,1) 12%);\n	color: #333333;\n	font-size: 16pt;\n}\n\n.formFL.shadows,\n.formM.shadows,\n.formS.shadows {\n	position: relative;\n	border: none;\n	background: rgb( 232, 237, 241);\n	-moz-box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);\n	-webkit-box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);\n	box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);\n}\n\n	.formFL.shadows:before,\n	.formFL.shadows:after,\n	.formM.shadows:before,\n	.formM.shadows:after,\n	.formS.shadows:before,\n	.formS.shadows:after {\n		position: absolute;\n		z-index: -2;\n		content: \"\";\n	}\n\n/* Lifted corners */\n\n.lifted {\n	-moz-border-radius: 4px;\n	border-radius: 4px;\n}\n\n	.lifted:before,\n	.lifted:after {\n		bottom: 15px;\n		left: 10px;\n		max-width: 300px;\n		max-height: 100px;\n		width: 50%;\n		height: 20%;\n		-moz-box-shadow: 0 15px 10px rgba(0, 0, 0, 0.4);\n		-webkit-box-shadow: 0 15px 10px rgba(0, 0, 0, 0.4);\n		box-shadow: 0 15px 10px rgba(0, 0, 0, 0.4);\n		-moz-transform: rotate(-3deg);\n		-ms-transform: rotate(-3deg);\n		-o-transform: rotate(-3deg);\n		-webkit-transform: rotate(-3deg);\n		transform: rotate(-3deg);\n	}\n\n	.lifted:after {\n		right: 10px;\n		left: auto;\n		-moz-transform: rotate(3deg);\n		-ms-transform: rotate(3deg);\n		-o-transform: rotate(3deg);\n		-webkit-transform: rotate(3deg);\n		transform: rotate(3deg);\n	}\n\n.formS > div > a {\n	width: 95px;\n	height: 27px;\n	background: url(\"../Images/button-s.png\");\n	line-height: 26px;\n}\n\n.formV {\n	width: 166px;\n	height: 71px;\n	border: 1px solid rgb( 182, 211, 234 );\n	border-radius: 5px;\n	background: rgb( 242, 242, 242 );\n	text-align: center;\n}\n\n	.formV img {\n		clear: both;\n	}\n\n	.formV a {\n		font-size: 12pt;\n		margin-top: 5px;\n		width: 153px;\n		height: 44px;\n		background: url(\"../Images/button-l.png\");\n		color: rgba(255,255,255,1);\n		line-height: 43px;\n	}\n\n		.formV a:active {\n			position: relative;\n			top: 2px;\n		}\n\n.formFL a:hover {\n	background: url(\"../Images/button-hover-m.png\") 0 0 no-repeat;\n}\n\n.formM a:hover {\n	background: url(\"../Images/button-hover-m.png\") 0 0 no-repeat;\n}\n\n.formS a:hover {\n	background: url(\"../Images/button-hover-s.png\") 0 0 no-repeat;\n}\n\n.formV a:hover {\n	background: url(\"../Images/button-hover-l.png\") 0 0 no-repeat;\n}\n\n.formL a:hover {\n	background: url(\"../Images/button-hover-xl.png\");\n}\n\n.formL {\n	display: table;\n	width: 368px;\n	height: 58px;\n	border: 1px solid rgb( 182, 211, 234 );\n	border-radius: 5px;\n	background: rgb( 242, 242, 242 );\n	text-align: center;\n}\n\n	.formL > div {\n		display: table-cell;\n		vertical-align: middle;\n	}\n\n	.formL a {\n		font-size: 14pt;\n		width: 171px;\n		height: 41px;\n		background: url(\"../Images/button-xl.png\") 0 0 no-repeat;\n		line-height: 40px;\n	}\n\n	.formL img {\n		position: relative;\n		top: 7px;\n		left: 5px;\n	}\n\n</style>\n<script type=\"text/javascript\">\n		function fsubmit() {\n			oform = document.getElementById(\"fmain\");\n			oform.submit();\n		}\n	</script>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('100','report_order_from_old','','0','0','0','<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!DOCTYPE xsl:stylesheet>\n<xsl:stylesheet version=\"1.0\" xmlns:xsl=\"http://www.w3.org/1999/XSL/Transform\">\n	<xsl:output xmlns=\"http://www.w3.org/TR/xhtml1/strict\" doctype-public=\"-//W3C//DTD XHTML 1.0 Strict//EN\" encoding=\"utf-8\" indent=\"yes\" method=\"html\" omit-xml-declaration=\"no\" version=\"1.0\" media-type=\"text/xml\" />\n	\n	<xsl:decimal-format name=\"my\" decimal-separator=\",\" grouping-separator=\" \" />\n	\n	<!-- ПисьмоПользователю -->\n	\n	<xsl:template match=\"/document_list\">\n		<html>\n			<head>\n				<style type=\"text/css\">html, body, td\n					{\n					font-family: Arial, Verdana, Tahoma, sans-serif;\n					font-size: 10pt;\n					background-color: #FFFFFF;\n					color: #000000;\n					}\n					\n					.td_main\n					{\n					border-top: black 1px solid;\n					border-left: black 1px solid;\n					}\n					\n					.td_header\n					{\n					border-left: black 1px solid;\n					border-top: black 1px solid;\n					border-bottom: black 1px solid;\n					text-align: center;\n					font-weight: bold;\n					}\n					\n					.td_main_2\n					{\n					border-left: black 1px solid;\n					border-bottom: black 1px solid;\n					}\n					\n					.tr_footer td\n					{\n					font-size: 11pt;\n					font-weight: bold;\n					white-space: nowrap;\n					}\n					\n					table, td\n					{\n					empty-cells: show;\n					}\n				</style>\n			</head>\n			<body bgcolor=\"#FFFFFF\" color=\"#000000\">\n				\n				<p>Здравствуйте, <xsl:value-of select=\"order_list/site_user_fio\" />!</p>\n				\n		<p>Вами был оформлен <b>заказ № <xsl:value-of select=\"order_list/order_account_number\" /></b> на сайте <a href=\"http://{order_list/shop/site_alias_name}\"><xsl:value-of select=\"order_list/shop/site_alias_name\" /></a>.</p>\n				\n				<xsl:apply-templates select=\"order_list\" />\n				\n				<br />\n				\n				<xsl:choose>\n					<xsl:when test=\"count(items_order) &gt; 0\">\n						<table cellpadding=\"3\" cellspacing=\"0\" width=\"100%\">\n							<tr>\n								<td class=\"td_header\">Номер</td>\n								<td class=\"td_header\">Артикул</td>\n								<td class=\"td_header\">Наименование</td>\n								<td class=\"td_header\">Кол-во</td>\n								<td class=\"td_header\">Цена</td>\n								<td class=\"td_header\" style=\"border-right: black 1px solid;\">Сумма</td>\n							</tr>\n							<xsl:apply-templates select=\"items_order\" />\n							<tr class=\"tr_footer\">\n							<td colspan=\"5\" align=\"right\"><b>Итого:</b></td>\n								<td style=\"white-space: nowrap\">\n									<xsl:value-of select=\"format-number(order_list/sum, \'### ##0,00\', \'my\')\" />&#xA0;<xsl:value-of select=\"order_list/currency/currency_name\" disable-output-escaping=\"yes\" /></td>\n							</tr>\n						</table>\n						\n						<!-- <p>Через некоторое время с Вами свяжется наш менеджер, чтобы согласовать заказанный товар и время доставки.</p> -->\n					</xsl:when>\n					<xsl:otherwise>\n					<p><b>Заказанных товаров нет</b></p>\n					</xsl:otherwise>\n				</xsl:choose>\n				\n				<p>Вам необходимо произвести оплату в течение 10 дней. На это время для Вас на складе зарезервированы часы Traser, выбранной Вами модели. По истечению этого срока бронь автоматически снимается и наличие часов не гарантируется.\n					<br />Отправка осуществляется в день поступления оплаты на наш расчетный счет. Доставка по указанному Вами адресу будет выполнена курьерской службой, которую Вы выбрали при оформлении заказа.\n					<br />При заказе доставки по Москве с Вами свяжется наш менеджер. Обработка заказов производится только в рабочее время.\n					<br />Мы не только продаем часы Traser, но и обеспечиваем их гарантийное и сервисное  обслуживание. У Вас всегда есть возможность решить все вопросы, связанные с эксплуатацией часов, а также приобрести дополнительные аксессуары к часам Traser в нашем интернет-магазине.\n					<br />Вы можете задать интересующий вопрос по электронной почте office@bratishka.ru</p>\n				<p>С уважением,\n					<br />Официальный интернет-магазин www.traserh3.ru\n					<br />тел. +7 (495) 788-83-17</p>\n				\n				<xsl:if test=\"count(shop_eitems/shop_eitem) > 0\">\n					<br /><br />\n					<b>Данные об электронных товарах:</b>\n					<br />\n					<div style=\"background-color: #eee; padding: 10px;\">\n						<xsl:apply-templates select=\"shop_eitems/shop_eitem\" />\n					</div>\n				</xsl:if>\n				\n				<p>\n					<hr />\n					Система управления сайтом HostCMS\n					<br />\n					<a href=\"http://www.hostcms.ru\">http://www.hostcms.ru</a>\n				</p>\n			</body>\n		</html>\n	</xsl:template>\n	\n	<!-- Шаблон вывода данных о заказе -->\n	<xsl:template match=\"order_list\">\n		\n		<p>\n			<xsl:if test=\"site_users_company != \'\'\">\n				Компания: <xsl:value-of select=\"site_users_company\" /><br />\n			</xsl:if>\n			\n			ФИО: <xsl:value-of select=\"site_user_fio\" /><br />\n			\n			E-mail: <xsl:value-of select=\"site_users_email\" /><br />\n			\n			<xsl:if test=\"site_users_phone != \'\'\">\n				Телефон: <xsl:value-of select=\"site_users_phone\" /><br />\n			</xsl:if>\n			<xsl:if test=\"site_users_fax != \'\'\">\n				Факс: <xsl:value-of select=\"site_users_fax\" /><br />\n			</xsl:if>\n			\n			<xsl:if test=\"order_status/order_status_name/node()\">\n				Статус:&#xA0;<xsl:value-of select=\"order_status/order_status_name\"/>, <xsl:value-of select=\"order_status/order_change_status_datetime\"/>.<br />\n			</xsl:if>\n			\n			Адрес:\n			<xsl:if test=\"index != \'\'\">\n				<xsl:value-of select=\"index\" /><xsl:text>, </xsl:text>\n			</xsl:if>\n			<xsl:if test=\"country_name != \'\'\">\n				<xsl:value-of select=\"country_name\" /><xsl:text>, </xsl:text>\n			</xsl:if>\n			<xsl:if test=\"location_name != \'\'\">\n				<xsl:value-of select=\"location_name\" /><xsl:text>, </xsl:text>\n			</xsl:if>\n			<xsl:if test=\"city_name != \'\'\">\n				<xsl:value-of select=\"city_name\" /><xsl:text>, </xsl:text>\n			</xsl:if>\n			<xsl:if test=\"city_area_name != \'\'\">\n				<xsl:value-of select=\"city_area_name\" /><xsl:text>, </xsl:text>\n			</xsl:if>\n			<xsl:if test=\"address != \'\'\">\n				<xsl:value-of select=\"address\" />\n			</xsl:if>\n			\n			<br />\n			\n			<xsl:if test=\"delivery_type/type_of_delivery_description != \'\'\">\n				Тип доставки: <xsl:value-of select=\"delivery_type/type_of_delivery_description\" /><br />\n			</xsl:if>\n			\n			<xsl:if test=\"system_of_pay_description != \'\'\">\n				Способ оплаты: <xsl:value-of select=\"system_of_pay_name\" /><br />\n			</xsl:if>\n			\n			Статус оплаты: <b><xsl:choose>\n					<xsl:when test=\"status_of_pay = \'1\'\">оплачено</xsl:when>\n					<xsl:otherwise>не оплачено</xsl:otherwise>\n			</xsl:choose></b>\n			\n			<br />\n			\n			<xsl:if test=\"shop_order_description != \'\'\">\n				Описание заказа: <xsl:value-of select=\"shop_order_description\" disable-output-escaping=\"yes\" /><br />\n			</xsl:if>\n		</p>\n	</xsl:template>\n	\n	<!-- Данные о товарах -->\n	<xsl:template match=\"items_order\">\n		<tr>\n			<td class=\"td_main_2\">\n				<xsl:value-of select=\"position()\" />\n			</td>\n			<td class=\"td_main_2\">\n				<xsl:choose>\n					<xsl:when test=\"order_items_marking != \'\'\">\n						<xsl:value-of select=\"order_items_marking\" />\n					</xsl:when>\n					<xsl:otherwise>&#8212;</xsl:otherwise>\n				</xsl:choose>\n			</td>\n			<td class=\"td_main_2\">\n				<xsl:value-of select=\"order_items_name\" />\n			</td>\n			<td class=\"td_main_2\" style=\"white-space: nowrap\">\n				<xsl:value-of select=\"order_items_quantity\" /><xsl:text> </xsl:text><xsl:value-of select=\"item/mesure\" />\n			</td>\n			<td class=\"td_main_2\" style=\"white-space: nowrap\">\n				<xsl:value-of select=\"format-number(order_items_price, \'### ##0,00\', \'my\')\" />&#xA0;<xsl:value-of select=\"/document_list/order_list/currency/currency_name\" disable-output-escaping=\"yes\" /></td>\n			<td class=\"td_main_2\" style=\"border-right: black 1px solid; white-space: nowrap\">\n				<xsl:value-of select=\"format-number(order_items_quantity * order_items_price, \'### ##0,00\', \'my\')\" />&#xA0;<xsl:value-of select=\"/document_list/order_list/currency/currency_name\" disable-output-escaping=\"yes\" /></td>\n		</tr>\n	</xsl:template>\n	\n	<!-- Данные о товарах -->\n	<xsl:template match=\"shop_eitem\">\n	<b><i><xsl:value-of select=\"shop_eitem_name\" /></i></b>\n		<br />\n		<xsl:if test=\"shop_eitem_value != \'\' and /document_list/order_list/shop/shop_shops_attach_eitem = 1\">\n			<i>Текст электронного товара:</i><br /><xsl:value-of select=\"shop_eitem_value\" /><br />\n		</xsl:if>\n		\n		<!-- Отображать ли ссылку на файл электронного товара-->\n		<xsl:if test=\"/document_list/order_list/shop/shop_shops_attach_eitem = 0 and shop_eitem_resource != \'\'\">\n		<a href=\"http://{/document_list/order_list/shop/site_alias_name}{/document_list/order_list/shop/shop_path}?download_file={shop_eitem_resource}\"><i>Скачать файл</i></a><br />\n		</xsl:if>\n		\n		<xsl:if test=\"shop_eitem_filename != \'\'\">\n			<i>Файл электронного товара:</i><br /><xsl:value-of select=\"shop_eitem_filename\" /><br />\n		</xsl:if>\n		<br />\n	</xsl:template>\n	\n</xsl:stylesheet>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('101','bank_order','','0','0','0','\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"ru\" lang=\"ru\">\n<head>\n	<title>Версия для печати</title>\n	<meta name=\"description\" content=\"Версия для печати\" />\n	<meta name=\"keywords\" content=\"Версия для печати\" />\n	<meta http-equiv=\"X-UA-Compatible\" content=\"IE=EmulateIE7\" />\n	<meta content=\"text/html; charset=UTF-8\" http-equiv=\"Content-Type\" />\n\n	</head>\n<body>\n<html xmlns=\"http://www.w3.org/1999/xhtml\"><head><meta content=\"text/html; charset=utf-8\" http-equiv=\"Content-Type\" /><meta http-equiv=\"X-UA-Compatible\" content=\"IE=EmulateIE7\" /></head><body bgcolor=\"#ffffff\" topmargin=\"0\" leftmargin=\"0\" marginwidth=\"0\" marginheight=\"0\"><style type=\"text/css\">\n					hr { height: 1px; margin: 0px; padding: 0px; color: #000000; background-color: #000000; line-height: 0; }\n					* html hr {margin:-7px 0; display: block; padding: 0; border: 0; /* для IE6 */}\n					*+html hr {margin:-7px 0; display: block; padding: 0; border: 0; /* для IE7 */}\n					hr { border: 0\\9 /* для IE8 */ }\n					\n					.main_div\n					{\n					margin-left: 0.5em;\n					margin-right: 0.5em;\n					margin-top: 2em;\n					margin-bottom: 1em;\n					}\n					.brdr\n					{\n					margin: 2px 0 -3px 0;\n					padding: 0 2px;\n					border-left: 1px solid #000;\n					border-top: 1px solid #000;\n					border-bottom: 1px solid #000;\n					float: left;\n					font-size: 9pt;\n					}\n					\n					.brdr-last\n					{\n					margin: 2px 0 -3px 0;\n					padding: 0 2px;\n					border: 1px solid #000;\n					float: left;\n					font-size: 9pt;\n					}\n				</style><div class=\"main_div\"><table xmlns=\"\" cellspacing=\"0\" cellpadding=\"5\" border=\"1\" width=\"680\" bordercolor=\"#000000\" rules=\"all\"><tr valign=\"top\"><td width=\"190\" height=\"275\"><table rules=\"none\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\"><tr><td align=\"center\"><font size=\"2\"><b>Извещение</b></font></td></tr><tr><td align=\"center\" valign=\"bottom\" height=\"240\"><font size=\"2\"><b>Кассир</b></font></td></tr></table></td><td><div align=\"right\"><font size=\"1\"><i>Форма №ПД-4</i></font></div><table rules=\"none\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\"><tr><td><font size=\"2\"><b>ООО \"Витязь-Братишка\"</b></font></td></tr><tr><td height=\"1\"><hr noshade=\"noshade\" size=\"1\" color=\"#000000\" /></td></tr><tr><td align=\"center\" valign=\"top\"><font size=\"1\">(наименование получателя платежа)</font></td></tr></table><table rules=\"none\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\"><tr><td width=\"175\"><div class=\"brdr\">7</div><div class=\"brdr\">7</div><div class=\"brdr\">1</div><div class=\"brdr\">8</div><div class=\"brdr\">6</div><div class=\"brdr\">4</div><div class=\"brdr\">8</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr-last\">9</div></td><td rowspan=\"3\" width=\"20\"></td><td><div class=\"brdr\">4</div><div class=\"brdr\">0</div><div class=\"brdr\">7</div><div class=\"brdr\">0</div><div class=\"brdr\">2</div><div class=\"brdr\">8</div><div class=\"brdr\">1</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">3</div><div class=\"brdr\">8</div><div class=\"brdr\">2</div><div class=\"brdr\">9</div><div class=\"brdr\">0</div><div class=\"brdr\">1</div><div class=\"brdr\">1</div><div class=\"brdr\">1</div><div class=\"brdr\">8</div><div class=\"brdr\">4</div><div class=\"brdr-last\">6</div></td></tr><tr><td height=\"1\"></td><td height=\"1\"></td></tr><tr><td align=\"center\" valign=\"top\"><font size=\"1\">(ИНН получателя платежа)</font></td><td align=\"center\" valign=\"top\"><font size=\"1\">(номер счета получателя платежа)</font></td></tr></table><table rules=\"none\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\"><tr><td width=\"5\"><font size=\"2\">в</font></td><td width=\"5\"></td><td width=\"300\"><font size=\"1\">Стромынское ОСБ 5281/1683 Сбербанка России ОАО г. Москва</font></td><td width=\"10\" rowspan=\"3\"></td><td width=\"20\"><font size=\"2\">БИК</font></td><td width=\"5\" rowspan=\"3\"></td><td><div class=\"brdr\">0</div><div class=\"brdr\">4</div><div class=\"brdr\">4</div><div class=\"brdr\">5</div><div class=\"brdr\">2</div><div class=\"brdr\">5</div><div class=\"brdr\">2</div><div class=\"brdr\">2</div><div class=\"brdr-last\">5</div></td></tr><tr><td></td><td></td><td height=\"1\"><hr noshade=\"noshade\" size=\"1\" color=\"#000000\" /></td><td></td><td height=\"1\"></td></tr><tr><td align=\"center\" valign=\"top\" colspan=\"3\"><font size=\"1\">(наименование банка получателя платежа)</font></td><td align=\"center\" valign=\"top\"></td><td align=\"center\" valign=\"top\"></td></tr></table><table rules=\"none\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\"><tr><td width=\"220\"><font size=\"1\">Номер кор./сч. банка получателя платежа</font></td><td width=\"10\"></td><td><div class=\"brdr\">3</div><div class=\"brdr\">0</div><div class=\"brdr\">1</div><div class=\"brdr\">0</div><div class=\"brdr\">1</div><div class=\"brdr\">8</div><div class=\"brdr\">1</div><div class=\"brdr\">0</div><div class=\"brdr\">4</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">0</div><div class=\"brdr\">2</div><div class=\"brdr\">2</div><div class=\"brdr-last\">5</div></td></tr></table><table rules=\"none\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\"><tr><td width=\"225\"><font size=\"2\">Оплата по счету № 2583</font></td><td width=\"10\"></td><td><font size=\"2\">КПП 771901001</font></td></tr><tr><td height=\"1\"><hr noshade=\"noshade\" size=\"1\" color=\"#000000\" /></td><