INSERT INTO `modx_site_htmlsnippets` VALUES ('102','shopOrderReport_old','','0','10','0','<p>В интернет-магазине Traser сделан заказ.</p>\n<p>Номер заказа: [+orderID+]</p>\n<b>Состав заказа:</b>\n[+orderData+]\n<br /><br />\n<b>Данные покупателя:</b><br />\n<table cellpadding=\"3\">\n	<tr><td>Ф.И.О.:</td><td>[+ename+]</td></tr>\n	<tr><td>E-mail:</td><td><a href=\"mailto:[+email+]\">[+email+]</a></td></tr>\n	<tr><td>Телефон:</td><td>[+ephone+]</td></tr>\n  <tr><td>Страна:</td><td>[+country_name+]</td></tr>\n  <tr><td>Город:</td><td>[+city_name+]</td></tr>\n  <tr><td>Индекс:</td><td>[+eindex+] </td></tr>\n	<tr><td>Адрес:</td><td>[+eaddress+] </td></tr>\n	<tr><td>Доставка:</td><td>[+delivery_name+] </td></tr>\n	<tr><td>Оплата:</td><td>[+oplata_name+] </td></tr>\n  <tr><td>Комментарий:</td><td>[+message+]</td></tr>\n</table>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('103','orderDataTpl2','','0','10','0','<table style=\"width:100%\" border=\"1\">\n	<tr>\n		<th>Номер</th>\n		<th>Артикул</th>\n		<th>Название</th>\n		<th>Кол-во</th>\n		<th>Цена</th>\n		<th>Сумма</th>\n	</tr>\n	[+loop+]\n	<tr>\n		<td>[[if? &is=`[+index+]+1` &math=`on`]]</td>\n		<td align=\"center\">[+articul+]</td>\n		<td>[[if? &is=`[+id+]:=:284` &then=`[+name+]` &else=`<a href=\"[+link+]\">[+name+]</a>`]]</td>\n		<td align=\"center\">[+count+]</td>\n		<td align=\"center\">[+price+] [+currency+]</td>\n		<td align=\"center\">[+price_count+] [+currency+]</td>\n	</tr>\n	[+end_loop+]\n</table>\n<div style=\"text-align:right\"><b>Итого [+totalPrice+] [+currency+]</b></div>','0');
