INSERT INTO `modx_site_htmlsnippets` VALUES ('106','yml_tpl','Яндекс маркет','0','0','0','<offer id=\"[+id+]\" available=\"true\">\n<url>[(site_url)][~[+id+]~]</url>\n<price>[+price+]</price>\n<currencyId>RUR</currencyId>\n<categoryId>[+parent+]</categoryId>\n<picture>[(site_url)][+item_image+]</picture>\n<delivery>true</delivery>\n<name>[+pagetitle:notags+]</name>\n<model>[+pagetitle:notags+] [+articul+]</model>	\n<vendorCode>[+articul+]</vendorCode>\n	<vendor>[+proizvoditel+]</vendor>\n<description>\n	 [+material+] [+razmer+] [+remtip+]\n[+how-long+]\n    [+keyring+]\n    [+kolba+]\n    [+size-brelok+]\n   [+srok_sveta+]\n    [+water-brelok+]\n	[+alarm+]\n[+battery+]\n[+besel+]\n[+box+]\n[+data+]\n[+dennedeli+]\n[+golvka+]\n[+hronograf+]\n[+korpus+]\n[+mechanism+]\n[+model+]\n[+podsvetka+]\n[+razmery+]\n[+soputka+]\n[+steklo+]\n[+strelki+]\n[+tip+]\n[+ves2+]\n[+vodozashita+]\n</description>\n<sales_notes> Минимальная сумма заказа - 900 рублей.</sales_notes>\n</offer>','0');
