INSERT INTO `modx_site_htmlsnippets` VALUES ('108','JivoSite','','0','0','0','<!-- BEGIN JIVOSITE CODE {literal} -->\n<script type=\'text/javascript\'>\n(function(){ var widget_id = \'8kQ6BbXudX\';var d=document;var w=window;function l(){\nvar s = document.createElement(\'script\'); s.type = \'text/javascript\'; s.async = true; s.src = \'//code.jivosite.com/script/widget/\'+widget_id; var ss = document.getElementsByTagName(\'script\')[0]; ss.parentNode.insertBefore(s, ss);}if(d.readyState==\'complete\'){l();}else{if(w.attachEvent){w.attachEvent(\'onload\',l);}else{w.addEventListener(\'load\',l,false);}}})();</script>\n<!-- {/literal} END JIVOSITE CODE -->','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('109','Duplicate of head','','0','7','0','<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" /> \n	<title>[*titl*]</title>\n<base href=\"[(site_url)]\" />\n	<meta name=\"keywords\" content=\"[*keyw*]\" />\n	<meta name=\"description\" content=\"[*desc*]\" />\n	<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n	<meta name=\"apple-mobile-web-app-capable\" content=\"yes\" />\n<script type=\"text/javascript\" src=\"assets/templates/traser/js/jquery-1.8.3.min.js\"></script>\n	<link rel=\"stylesheet\" href=\"assets/templates/traser/css/style.css\" media=\"screen\" />\n	<link rel=\"shortcut icon\" href=\"favicon.ico\" />\n	<link href=\'http://fonts.googleapis.com/css?family=PT+Sans+Narrow&subset=cyrillic,cyrillic-ext\' rel=\'stylesheet\' type=\'text/css\'>\n	<!--[if lt IE 9]> \n		<link rel=\"stylesheet\" href=\"assets/templates/traser/css/style9.css\" media=\"screen\" /> \n	<![endif]-->\n<script type=\"text/javascript\">\n	$(document).ready(function(){\n		$(\".cart a\").hover(function(){\n			//if ($(\".cartShort\").hasClass(\"hidden\")){\n				$(\".cartShort\").removeClass(\"hidden\");\n			//} else {\n			//	$(\".cartShort\").fadeOut();\n			//}\n		});\n		$(\".close-but\").on(\"click\",function(e){\n			$(\'.cartShort\').addClass(\"hidden\");\n		})\n		$(\".text-content .hiddenElement\").each(function(){\n			$(this).append(\'<a class=\"show_hidden\" href=\"#\">подробнее</a>\');\n		})\n		$(document).on(\"click\",\".show_hidden\",function(e){\n			e.preventDefault();\n			$(this).parent().next().removeClass(\"hidden\");\n			$(this).remove();\n		})\n	})\n	\n</script>','0');
