INSERT INTO `modx_site_htmlsnippets` VALUES ('115','Duplicate of catalogWatchInner','','0','10','0','<div class=\"shk-item catalog-item\">\n	<div class=\"image\">\n		<a href=\"[~[+id+]~]\" title=\"[+pagetitle+]\"><img src=\"[[phpthumb? &input=`[+item_image+]` &options=`w=104&h=170&far=1&f=png`]]\" alt=\"[+pagetitle+]\" /></a>\n	</div>\n	<div class=\"item\">\n		<h3><a href=\"[~[+id+]~]\">[+pagetitle+]</a>[[if? &is=`[+nalichie+]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[+indate+]`]]</div>` &else=``]]</h3>\n	</div>\n	[[if? &is=`[+longtitle+]:!empty` &then=`<p>[+longtitle+]</p>` &else=``]]\n	[[if? &is=`[+articul+]:!empty` &then=`<p>Артикул: [+articul+]</p>` &else=``]]\n	<div class=\"item-description\">\n		<ul>\n			<li class=\"first\">Производитель: [+proizvoditel+]</li>\n			<li>Серия: [[DocInfo? &docid=`[+parent+]` &field=`menutitle`]]</li>\n			<li>Стекло: [+steklo+]</li>\n			<li>Механизм: [+mechanism+]</li>\n			<li>Водозащита: [+vodozashita+]</li>\n		</ul>\n	</div>\n	<div class=\"price\">[[formatPrice? &price=`[+price+]`]].-</div>\n	<div class=\"clear\"></div>\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('116','Duplicate of main_info','','0','7','0','<h1>[*pagetitle*]</h1>\n		[[if? &is=`[*longtitle*]:!empty:` &then=`<div class=\"ptnarrow info\">[*longtitle*]</div>`]]\n		[[if? &is=`[*articul*]:!empty:` &then=`<div class=\"ptnarrow info\">Артикул: [*articul*]</div>`]]\n		<div class=\"item_text\">[*content*]</div>\n		<div class=\"price\">[[formatPrice? &price=`[*price*]`]].-</div>\n[[if? &is=`[*nalichie*]:eq:1` &then=`<div class=\"errors\">Поставка [[aDate? &date=`[*indate*]`]]</div>` &else=`\n		<div class=\"shk-item\">\n			<form action=\"[~281~]\" method=\"post\" class=\"element\">\n						<input type=\"hidden\" name=\"shk-id\" value=\"[*id*]\" />\n						<input type=\"hidden\" name=\"shk-name\" value=\"[*pagetitle*]\" />\n						<input type=\"hidden\" name=\"shk-count\" value=\"1\" size=\"2\" maxlength=\"3\" />\n						<button type=\"submit\">Купить</button>\n				[[if? &is=`[*price*]:>:900` &then=`<a href=\"[~299~]\" class=\"one_click fancybox.ajax\">Купить в 1 клик</a>` &else=``]]\n			</form>\n</div>\n`]]','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('117','Duplicate of photoItem','','0','7','0','<div class=\"photos\">\n	<a href=\"[*item_image*]\" class=\"mphoto\" title=\"[*pagetitle*]\"><img src=\"[[phpthumb? &input=`[*item_image*]` &options=`w=160,far=1,f=jpeg,q=90`]]\" alt=\"[*pagetitle*]\" /></a>\n	[[if? &is=`[*status*]:!empty:` &then=`<img class=\"status\" src=\"[[phpthumb? &input=`[[DocInfo? &docid=`[*status*]` &tv=`1` &field=`image`]]` &options=`w=90,f=png`]]\" />`]]\n	[!multiTV? &tvName=`photos`!]\n</div>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('118','photos','','0','0','0','<li style=\"overflow: hidden; float: left; width: 112px; height: 129px;\">\n                    <a onclick=\"$$(\'.cloud-zoom-gallery\').each(function(e,i){e.removeClassName(\'actived\');});this.addClassName(\'actived\')\" class=\"cloud-zoom-gallery\" rel=\"useZoom: \'vt_cloudzoom\', smallImage: \'[+image+]\'\" href=\"[+image+]\" title=\"\"> \n                        <img src=\"[[phpthumb? &input=`[+image+]` &options=`w=160,far=1,f=jpeg,q=90`]]\" alt=\"\" title=\"\">\n                    </a>\n</li>','0');
INSERT INTO `modx_site_htmlsnippets` VALUES ('119','box_header','','0','0','0','<div class=\"box-header-01\">\n			<div class=\"container\">\n				<div class=\"row\">\n					<div class=\"row\">\n						  \n						<div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12 cl-left\" style=\"padding-left: 150px;\">\n								<div class=\"wrap-block-cl icon-phone\">\n									<span>Телефоны: +7 (495) 7-888-317, 8 (800) 5555-041</span>\n								</div>\n							</div>\n						<div class=\"col-lg-6 col-md-6 col-sm-6 col-xs-12 cl-right\">\n							<div class=\"wrap-block-cl\">\n							\n								<div class=\"quick-access\">\n						<form id=\"ajaxSearch_form\" action=\"rezultaty-poiska.html\" method=\"post\">\n    <div class=\"form-search\">   \n		<input type=\"hidden\" name=\"advsearch\" value=\"oneword\">\n		<input id=\"ajaxSearch_input\" type=\"text\" class=\"input-text\" name=\"search\" value=\"Запрос для поиска...\" onfocus=\"this.value=(this.value==\'Запрос для поиска...\')? \'\' : this.value ;\">\n        <button id=\"ajaxSearch_submit\" type=\"submit\" title=\"Search\" class=\"button\"><span><span>Поиск</span></span></button>\n    </div>\n</form>\n					</div>\n								      \n							</div>\n						</div>\n					</div>\n				</div>\n			</div>\n		</div>','0');
