INSERT INTO `modx_site_snippets` VALUES ('22','include','<strong>1.1</strong> Include non-cached chunks and snippets from files','0','0','0','$output = \'\';\n\n#############################################\nif(!empty($file)){\n\n  if(file_exists(MODX_BASE_PATH.$file))\n    $output = include MODX_BASE_PATH.$file;\n  else\n    $output = \'File not found: \'.$file;\n\n#############################################\n}else if(!empty($chunk)){\n  \n  if(!function_exists(\'fetchTpl\')){\n    function fetchTpl($tpl){\n    	global $modx;\n      $template = \"\";\n    	if(substr($tpl, 0, 6) == \"@FILE:\"){\n    	  $tpl_file = MODX_BASE_PATH . substr($tpl, 6);\n    		$template = file_get_contents($tpl_file);\n    	}else if(substr($tpl, 0, 6) == \"@CODE:\"){\n    		$template = substr($tpl, 6);\n    	}else if($modx->getChunk($tpl) != \"\"){\n    		$template = $modx->getChunk($tpl);\n    	}else{\n    		$template = false;\n    	}\n    	return $template;\n    }\n  }\n  \n  if(!isset($parse)) $parse = true;\n  \n  $output = fetchTpl($chunk);\n  if($parse){\n    $output = str_replace(array(\'[!\',\'!]\'),array(\'[[\',\']]\'),$output);\n    $output = $modx->parseDocumentSource($output);\n  }\n\n#############################################\n}else if(!empty($placeholder)){\n\n  $output = isset($modx->placeholders[$placeholder]) ? $modx->placeholders[$placeholder] : \'\';\n  \n#############################################\n}else if(!empty($session)){\n\n  $output = isset($_SESSION[$session]) && (!is_array($_SESSION[$session])) ? (string) $_SESSION[$session] : \'\';\n  \n}\n\nreturn $output;\n\n','0','','');
INSERT INTO `modx_site_snippets` VALUES ('23','Shopkeeper','<strong>1.3.4</strong> Shopping cart for MODx Evolution','0','13','0','$output = \'\';\n\nrequire MODX_BASE_PATH.\"assets/snippets/shopkeeper/shopkeeper.inc.php\";\n\nreturn $output;\n\n','0','&tplPath=Папка с чанками;textarea;','');
INSERT INTO `modx_site_snippets` VALUES ('24','submenu','','0','5','0','\n$id=isset($id)?(int)$id:$modx->documentIdentifier;\n$output=\"\";\nswitch ($id){\n	case 13:\n		$params=array(\n			\'id\'=>\'uine\',\n			\'tpl\'=>\'innerMenuRowRem\',\n			\'tplLast\'=>\'innerMenuRowLastRem\',\n			\'outerTpl\'=>\'innerMenuOuter\',\n			\'parents\'=>270,\n			\'orderBy\'=>\'menuindex asc\',\n			\'noResults\'=>\'\'\n		);\n		break;\n	default:\n		$params=array(\n			\'id\'=>\'uine\',\n			\'tpl\'=>\'innerMenuRow\',\n			\'tplLast\'=>\'innerMenuRowLast\',\n			\'outerTpl\'=>\'innerMenuOuter\',\n			\'parents\'=>$id,\n			\'filter\'=>\'isfolder,1,1\',\n			\'orderBy\'=>\'menuindex asc\',\n			\'noResults\'=>\'\'\n		);\n		break;\n}\n$output=$modx->runSnippet(\'Ditto\',$params);\nreturn $output;\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('25','sliderMain','','0','18','0','\n$output=\"\";\n$docs=explode(\",\",$modx->documentObject[\"main_slider\"][1]);\n$im_array=array();\nforeach ($docs as $k=>$v){\n	//$images=$modx->getTemplateVarOutput(array(\"item_image\",\"photos\"),$v);\n	//if ($images[\"item_image\"]==\"\"){\n	//	$im=\"\";\n	//	if ($images[\"photos\"]!=\"\"){\n	//		$t=json_decode($images[\"photos\"],true);\n	//		$im=$t[\'fieldValue\'][0][\'image\'];\n	//	}\n	//} else {\n	//	$im=$images[\"item_image\"];\n	//}\n	//$im_array[]=$im;\n	$image=$modx->getTemplateVarOutput(array(\"slider_image\"),$v);\n	$im_array[]=$image[\'slider_image\'];\n}\n//print_r($im_array);\n$t=$im_array;\n$left_html=\'<img src=\"[[phpthumb? &input=`\'.array_pop($t).\'` &options=`w=110,h=80,far=C,aoe=1,bg=FFFFFF,f=jpeg,q=90`]]\" />\';\nforeach ($t as $k=>$v){\n	$left_html.=\'<img src=\"[[phpthumb? &input=`\'.$v.\'` &options=`w=110,h=80,far=C,aoe=1,bg=FFFFFF,f=jpeg,q=90`]]\" />\';\n}\n$left_html=\'<div class=\"car_wrapl\"><div id=\"carousel_left\">\'.$left_html.\'</div></div>\';\n$t=$im_array;\n$right_html=\"\";\nforeach ($t as $k=>$v){\n	if (!$k){\n		$right_last.=\'<img src=\"[[phpthumb? &input=`\'.$v.\'` &options=`w=110,h=80,far=C,aoe=1,bg=FFFFFF,f=jpeg,q=90`]]\" />\';\n	} else {\n		$right_html.=\'<img src=\"[[phpthumb? &input=`\'.$v.\'` &options=`w=110,h=80,far=C,aoe=1,bg=FFFFFF,f=jpeg,q=90`]]\" />\';\n	}\n}\n$right_html=\'<div class=\"car_wrapr\"><div id=\"carousel_right\">\'.$right_html.$right_last.\'</div></div>\';\n$params=array(\n	\'documents\'=>$modx->documentObject[\"main_slider\"][1],\n	\'tpl\'=>\'sliderInner\',\n	\'outerTpl\'=>\'sliderOuter\',\n	\'display\'=>\'all\',\n	\'extenders\'=>\'nosort\'\n);\n$c=$modx->runSnippet(\'Ditto\',$params);\n$output=$left_html.$c.$right_html;\nreturn $output;\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('26','summary','','0','0','0','\n/**\n * summary\n *\n * @category extender\n * @license GNU General Public License (GPL), http://www.gnu.org/copyleft/gpl.html\n * @author Agel_Nash <Agel_Nash@xaker.ru>\n * @see http://blog.agel-nash.ru/addon/summary.html\n * @date 31.07.2013\n * @version 1.0.2\n */\n if(!defined(\'MODX_BASE_PATH\')) {die(\'HACK?\');}\n$text=strip_tags($text);\n \n$dir = MODX_BASE_PATH. (isset($dir) ? $dir : \'assets/snippets/summary/\');\n$summary = $dir . \"class.summary.php\";\nif (isset($doc)){\n	$tv=$modx->getPageInfo($doc,1,\'*\');\n	$text=$tv[\'content\'];\n}\nif(file_exists($summary) && !class_exists(\'SummaryText\',false)){\n		include_once($summary);\n}\n\nif(class_exists(\'SummaryText\',false)){\n  $action = array();\n  \n  if(empty($tags)){\n  	$action[]=\'notags\';\n  }\n  \n  if(!empty($noparser)){\n  	$action[]=\'noparser\';\n  }\n  \n  if(!empty($len)){\n  	$action[]=\'len\'.((int)$len>0 ? \':\'.(int)$len : \'\');\n  }\n  \n  \n  $action=implode(\",\",$action);\n  \n  if(!isset($dot)){\n       $dot = 0;\n    }\n\n	\n  $summary = new SummaryText($text,$action);\n  if(!empty($cut)){\n    $summary->setCut($cut);   \n  }\n  $out = $summary->run($dot);\n  unset($summary,$action);\n}else{\n	$out = $text;\n}\n\nreturn $out;\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('27','formatPrice','','0','0','0','\n$price=isset($price)?(int)$price:\"\";\nreturn number_format($price,0,\'\',\' \');\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('28','aDate','','0','7','0','\nif(!defined(\'MODX_BASE_PATH\')){\ndie(\'What are you doing? Get out of here!\');}\n$output = \"\";\n$format = \"%d.%m.%Y\";\nif (isset($date2) && $date2>0 ) {\n$output = strftime($format,$date2);\n}\nelse{\n$output = strftime($format,\"\"+$date);\n}\n$date=explode(\".\", $output);\nswitch ($date[1]){\ncase 1: $m=\'января\'; break;\ncase 2: $m=\'февраля\'; break;\ncase 3: $m=\'марта\'; break;\ncase 4: $m=\'апреля\'; break;\ncase 5: $m=\'мая\'; break;\ncase 6: $m=\'июня\'; break;\ncase 7: $m=\'июля\'; break;\ncase 8: $m=\'августа\'; break;\ncase 9: $m=\'сентября\'; break;\ncase 10: $m=\'октября\'; break;\ncase 11: $m=\'ноября\'; break;\ncase 12: $m=\'декабря\'; break;\n}\nreturn $date[0].\' \'.$m.\' \'.$date[2];\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('29','checkCartMinPrice','','0','7','0','\n$rez=-1;\nif (!isset($_SESSION[\'purchases\'])) return $rez;\n$ss=unserialize($_SESSION[\'purchases\']);\n$total=0;\nif (is_array($ss) && count($ss)){\n	foreach ($ss as $item){\n		if ($item[0]!=284) $total+=$item[2]*$item[1];\n	}\n	if ($total==0 && count($ss)==1){\n		unset($_SESSION[\'purchases\']);\n		return -1;\n	}\n} else {\n	return $rez;\n}\n$tv=$modx->getTemplateVarOutput(array(\"minprice\"),1);\n$rez=0;\nif ($total > $tv[\'minprice\']) $rez=1;\nif ($_SESSION[\'total_cart_sum\']>$tv[\'minprice\'] && $total<$tv[\'minprice\']){\n	$_SESSION[\'total_cart_sum\']=$total;\n	return -2;\n}\nreturn $rez;\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('30','catalogmenu','','0','5','0','\n$parent=$modx->runSnippet(\"UltimateParent\",array(\'id\'=>$modx->documentIdentifier,\'topLevel\'=>2));\n$output=\"\";\nswitch ($parent){\n	case 13:\n		$params=array(\n			\'id\'=>\'uine\',\n			\'tpl\'=>\'catalogMenuInnerRem\',\n			\'tplLast\'=>\'catalogMenuInnerRemLast\',\n			\'outerTpl\'=>\'catalogMenuOuter\',\n			\'parents\'=>270,\n			\'orderBy\'=>\'menuindex asc\',\n			\'noResults\'=>\'\',\n			\'extenders\'=>\'catalog_menu\',\n			\'uparent\'=>$parent\n		);\n		break;\n	default:\n		$params=array(\n			\'id\'=>\'uine\',\n			\'tpl\'=>\'catalogMenuInner\',\n			\'tplLast\'=>\'catalogMenuInnerLast\',\n			\'outerTpl\'=>\'catalogMenuOuter\',\n			\'parents\'=>$parent,\n			\'filter\'=>\'isfolder,1,1\',\n			\'orderBy\'=>\'menuindex asc\',\n			\'noResults\'=>\'\',\n			\'extenders\'=>\'catalog_menu\',\n			\'uparent\'=>$parent\n		);\n		break;\n}\n$output=$modx->runSnippet(\'Ditto\',$params);\nreturn $output;\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('31','catalogItems','','0','0','0','\n$docid=$modx->documentIdentifier;\n$parents=$modx->documentObject[\'parent\'];\nif ($parents==10) {\n	$parents=$docid;\n}\n$category=isset($_GET[\'category\']) ? (int) $_GET[\'category\'] : false;\n$uparent=$modx->runSnippet(\"UltimateParent\",array(\'id\'=>$modx->documentIdentifier,\'topLevel\'=>2));\n$filter=\"\";\n$orderBy=\'parent asc\';\nswitch ($uparent){\n	case 13:\n		$tpl=\'catalogRemeshokInner\';\n		if ($category) $filter=\'remtip,\'.$category.\',1\';\n		$orderBy=\'menuindex asc\';\n		break;\n	case 19:\n		$tpl=\'catalogOtherInner\';\n		break;\n	default:\n		$tpl=\'catalogWatchInner\';\n		break;\n}\n$sortBy=$sortDir=\"\";\nif (isset($_GET[\'ord\']) && isset($_GET[\'sor\'])){\n	$ord=$modx->db->escape($_GET[\'ord\']);\n	$sor=$modx->db->escape($_GET[\'sor\']);\n	$ord=$ord==\'asc\'?\'asc\':\'desc\';\n	$sor=$sor==\'price\'?\'price\':\'pub_date\';\n	$_SESSION[\'cat_sorting\'][$docid][\'sortBy\']=$sor;\n	$_SESSION[\'cat_sorting\'][$docid][\'sortDir\']=$ord;\n}\nif (isset($_SESSION[\'cat_sorting\'][$docid])){\n	$orderBy=\'\';\n	$sortBy=$_SESSION[\'cat_sorting\'][$docid][\'sortBy\'];\n	$sortDir=$_SESSION[\'cat_sorting\'][$docid][\'sortDir\'];\n	$plh=($sortDir==\'asc\' ? \'up\' : \'do\').($sortBy==\'price\' ? \'pr\' : \'ne\').\'acte\';\n	$modx->setPlaceholder($plh,$sortDir==\'asc\' ? \' upactive\' : \' doactive\');\n}\n$params=array(\n	\'parents\'=>$parents,\n	\'tpl\'=>$tpl,\n	\'display\'=>12,\n	\'depth\'=>2,\n	\'where\'=>\'isfolder=0\',\n	\'paginate\'=>1,\n	\'id\'=>\'catid\',\n	\'tplPaginateNext\'=>\'catalogNext\',\n	\'tplPaginatePrevious\'=>\'catalogPrev\'\n);\nif ($filter!=\"\") $params[\"filter\"]=$filter;\nif ($orderBy!=\"\") {\n	$params[\"orderBy\"]=$orderBy;\n} else {\n	$params[\'sortBy\']=$sortBy;\n	$params[\'sortDir\']=$sortDir;\n}\nreturn $modx->runSnippet(\'Ditto\',$params);\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('32','showManual','','0','0','0','\nfunction human_filesize($bytes, $decimals = 2) {\n  $sz = \'BKMGTP\';\n  $factor = floor((strlen($bytes) - 1) / 3);\n  return sprintf(\"%.{$decimals}f\", $bytes / pow(1024, $factor)) . @$sz[$factor];\n}\n	\n$manual= isset($modx->documentObject[\'manual\']) ? $modx->documentObject[\'manual\'][1] : \"\";\nif ($manual==\"\") return \"\";\nif (!file_exists($manual)) return \'\';\n$filesize=filesize($manual);\nif (!$filesize) return \"\";\necho \'<tr><td>Инструкция</td><td><a href=\"\'.$manual.\'\">Скачать инструкцию</a> (\'.human_filesize($filesize).\')</td></tr>\';\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('34','getItemInfo','','0','0','0','\n$id=isset($id)?(int)$id:$modx->documentIdentifier;\n$doc=$modx->getPageInfo($id,1,\'*\');\nif (isset($type)){\n	$tvs=$modx->getTemplateVarOutput(array(\"item_image\",\"articul\",\"price\"),$id);\n	$image=$tvs[\'item_image\'];\n	$articul=$tvs[\'articul\'];\n	$price=number_format($tvs[\'price\'],0,\'\',\' \').\'.-\';\n	$tpl=\'cartSmallInnerTpl\';\n	$plh=array(\'[+link+]\',\'[+name+]\',\'[+item_image+]\',\'[+longtitle+]\',\'[+articul+]\',\'[+price+]\');\n	$plhVal=array($modx->makeUrl($doc[\'id\'],\'\',\'\',\'full\'),$doc[\'pagetitle\'],$image,$doc[\'longtitle\'],$articul,$price);\n} else {\n	switch($doc[\'template\']){\n		case 10:\n		case 12:\n			$tpl=\'cartOtherTpl\';\n			$tvs=$modx->getTemplateVarOutput(array(\"item_image\",\"articul\",\"proizvoditel\",\"material\",\"size-brelok\",\"water-brelok\",\"how-long\"),$id);\n			$plh=array(\'[+item_image+]\',\'[+articul+]\',\'[+proizvoditel+]\',\'[+material+]\',\'[+size-brelok+]\',\'[+water-brelok+]\',\'[+how-long+]\',\'[+link+]\',\'[+name+]\');\n			$plhVal=array($tvs[\'item_image\'],$tvs[\'articul\'],$tvs[\'proizvoditel\'],$tvs[\'material\'],$tvs[\'size-brelok\'],$tvs[\'water-brelok\'],$tvs[\'how-long\'],$modx->makeUrl($doc[\'id\'],\'\',\'\',\'full\'),$doc[\'pagetitle\']);\n			break;\n		case 11:\n			$tpl=\'cartRemTpl\';\n			$tvs=$modx->getTemplateVarOutput(array(\"item_image\",\"articul\",\"proizvoditel\",\"material\",\"razmer\",\"remtip\"),$id);\n			$plh=array(\'[+item_image+]\',\'[+articul+]\',\'[+proizvoditel+]\',\'[+material+]\',\'[+razmer+]\',\'[+remtip+]\',\'[+link+]\',\'[+name+]\');\n			$plhVal=array($tvs[\'item_image\'],$tvs[\'articul\'],$tvs[\'proizvoditel\'],$tvs[\'material\'],$tvs[\'razmer\'],$tvs[\'remtip\'],$modx->makeUrl($doc[\'id\'],\'\',\'\',\'full\'),$doc[\'pagetitle\']);\n			break;\n		default:\n			$tpl=\'cartWatchTpl\';\n			$tvs=$modx->getTemplateVarOutput(array(\"item_image\",\"articul\",\"proizvoditel\",\"steklo\",\"mechanism\",\"vodozashita\"),$id);\n			$parent=$modx->getPageInfo($doc[\'parent\'],1,\'*\');\n			$plh=array(\'[+item_image+]\',\'[+longtitle+]\',\'[+articul+]\',\'[+proizvoditel+]\',\'[+parent+]\',\'[+steklo+]\',\'[+mechanism+]\',\'[+vodozashita+]\',\'[+link+]\',\'[+name+]\');\n			$plhVal=array($tvs[\'item_image\'],$doc[\'longtitle\'],$tvs[\'articul\'],$tvs[\'proizvoditel\'],$parent[\'menutitle\'],$tvs[\'steklo\'],$tvs[\'mechanism\'],$tvs[\'vodozashita\'],$modx->makeUrl($doc[\'id\'],\'\',\'\',\'full\'),$doc[\'pagetitle\']);\n			break;\n	}\n}\n$chunk=$modx->getChunk($tpl);\nreturn str_replace($plh,$plhVal,$chunk);\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('35','checkCart','','0','0','0','\n//unset($_SESSION[\'purchases\']);\n$deliveryDoc=284;\nif (isset($_POST[\'a_quant\']) && isset($_POST[\'a_item\']) && isset($_SESSION[\'purchases\'])){\n	$q=(int)$_POST[\'a_quant\'];\n	$item=str_replace(\"index_\",\"\",$_POST[\'a_item\']);\n	$goods=unserialize($_SESSION[\'purchases\']);\n	if (is_array($goods) && count($goods)){\n		$totalPrice = 0;\n		$goods[$item][1]=$q;\n		foreach($goods as $item){\n			if ($item[0]!=$deliveryDoc) $totalPrice += $item[2]*$item[1];\n		}\n		$_SESSION[\'purchases\']=serialize($goods);\n	}\n	if (!isset($_SESSION[\'total_cart_sum\'])) $_SESSION[\'total_cart_sum\']=$totalPrice;\n	if ($totalPrice<1000) {\n		echo \"-1\"; die();\n	}\n	if (($totalPrice > $_SESSION[\'total_cart_sum\']) && ($_SESSION[\'total_cart_sum\']<1000) ){\n		$_SESSION[\'total_cart_sum\']=$totalPrice;\n		echo \"-1\"; die();\n	}\n		die($totalPrice);\n}\nif (isset($_POST[\'country\'])){\n	$c=(int)$_POST[\'country\'];\n	if (in_array($c,array(175,88,24))){\n		$sql=\"select t1.shop_city_id, t1.shop_city_name from shop_city_table as t1 left join shop_location_table as t2 on t1.shop_location_id=t2.shop_location_id where t2.shop_country_id=\".$c.\" order by shop_city_name asc\";\n			$rez=$modx->db->query($sql);\n		$list=$addlist=\"\";\n			while($r=$modx->db->getRow($rez)){\n				if ($r[\'shop_city_name\']==\"Москва\" || $r[\'shop_city_name\']==\"Санкт-Петербург\"){\n					$addlist.=\'<option value=\"\'.$r[\'shop_city_id\'].\'\"\'.$selected.\'>\'.$r[\'shop_city_name\'].\'</option>\';\n				} else {\n				$list.=\'<option value=\"\'.$r[\'shop_city_id\'].\'\">\'.$r[\'shop_city_name\'].\'</option>\';\n				}\n			}\n		$list=\'<option value=\"\">Выбор города</option>\'.$addlist.$list;\n	}\n	$goods=unserialize($_SESSION[\'purchases\']);\n	$indexDeliv=\"\";\n	foreach($goods as $i=>$item){\n		if ($item[0]==$deliveryDoc) $indexDeliv=$i;\n	}\n	if ($indexDeliv!=\"\"){\n		unset($goods[$indexDeliv]);\n		$_SESSION[\'purchases\']=serialize($goods);\n		$_SESSION[\'deliveryID\']=\"\";\n	}\n	\n	die($list);\n}\n\nif (isset($_POST[\'action_a\']) && $_POST[\'action_a\']==\'cart_add\'){\n	$purchases=unserialize($_SESSION[\'purchases\']);\n	$indexDeliv=-1;\n	foreach ($purchases as $i=>$good) {\n		if ($good[0]==284) $indexDeliv=$i;\n	}\n	$deliveryPrice=$modx->getTemplateVarOutput(array(\"price\"),$_POST[\'v\']);\n	$deliveryPrice=$deliveryPrice[\'price\'];\n	if ($indexDeliv>-1){\n		$purchases[$indexDeliv]=array(0=>284, \'catalog\'=>0, 1=>1, 2=>$deliveryPrice);\n	} else {\n		$purchases[]=array(0=>284, \'catalog\'=>0, 1=>1, 2=>$deliveryPrice);\n	}\n	$_SESSION[\'deliveryID\']=$_POST[\'v\'];\n	$_SESSION[\'purchases\']=serialize($purchases);\n	die();\n}\nif (isset($_POST[\'type\']) && $_POST[\'type\']==\'dhl\'){\n	$sql=\"select * from shop_cond_of_delivery_table\";\n	$rez=$modx->db->query($sql);\n	$ret=array();\n	while($r=$modx->db->getRow($rez)){\n		$ret[$r[\'shop_city_id\']]=$r[\'shop_type_of_delivery_id\'];\n	}\n	echo json_encode($ret);\n	die();\n}\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('36','eFormActions','','0','6','0','\nif (!function_exists(\"fillForm\")){\n	function fillForm(&$fields, &$templates){\n		global $modx;\n		$na=$modx->getPlaceholder(\'notAllowZakaz\');\n		if ($na==1) return false;\n		$sql=\"select * from shop_country_table where shop_country_id in(175,24,88) order by shop_country_id desc\";\n		$rez=$modx->db->query($sql);\n		$ecountry=0;\n		if (isset($_POST[\'ecountry\'])) $ecountry=$_POST[\'ecountry\'];\n		$list=\'\';\n		$addlist=\"\";\n		$selected_id=0;\n		$cursel=isset($_POST[\'country\'])?(int)$_POST[\'country\']:0;\n		while($r=$modx->db->getRow($rez)){\n			if ($ecountry==0){\n				$selected=\"\";\n				if ($r[\'shop_country_id\']==$cursel){\n					$selected=\' selected=\"selected\"\';\n					$selected_id=$cursel;\n				}\n				$list.=\'<option value=\"\'.$r[\'shop_country_id\'].\'\"\'.$selected.\'>\'.$r[\'shop_country_name\'].\'</option>\';\n			} else {\n				$selected=\"\";\n				if ($ecountry==$r[\'shop_country_id\']){\n					$selected=\' selected=\"selected\"\';\n					$selected_id=$r[\'shop_country_id\'];\n				}\n				\n				$list.=\'<option value=\"\'.$r[\'shop_country_id\'].\'\"\'.$selected.\'>\'.$r[\'shop_country_name\'].\'</option>\';\n			}\n		}\n		$fields[\'countries\']=$list;\n		if ($selected_id){\n			$sql=\"select t1.shop_city_id, t1.shop_city_name from shop_city_table as t1 left join shop_location_table as t2 on t1.shop_location_id=t2.shop_location_id where t2.shop_country_id=\".$selected_id.\" order by shop_city_name asc\";\n			$rez=$modx->db->query($sql);\n			$list=\"\";\n			$etown=isset($_POST[\'etown\']) ? (int) $_POST[\'etown\']:0;\n			$list=$addlist=\"\";\n			while($r=$modx->db->getRow($rez)){\n				$selected = $etown == $r[\'shop_city_id\'] ? \' selected=\"selected\"\' : \'\';\n				if ($r[\'shop_city_name\']==\"Москва\" || $r[\'shop_city_name\']==\"Санкт-Петербург\"){\n					$addlist.=\'<option value=\"\'.$r[\'shop_city_id\'].\'\"\'.$selected.\'>\'.$r[\'shop_city_name\'].\'</option>\';\n				} else {\n				$list.=\'<option value=\"\'.$r[\'shop_city_id\'].\'\"\'.$selected.\'>\'.$r[\'shop_city_name\'].\'</option>\';\n				}\n			}\n		$list=\'<option value=\"\">Выбор города</option>\'.$addlist.$list;\n			$fields[\'towns\']=$list;\n		}\n		$docs=$modx->getActiveChildren(284);\n		$list=\"\";\n		$tpl=$modx->getChunk(\"dostavkaTpl\");\n		$plh=array(\'[+checked+]\',\'[+id+]\',\'[+selected+]\',\'[+pagetitle+]\',\'[+longtitle+]\',\'[+description+]\',\'[+price+]\');\n		$eoplata=isset($_POST[\'delivery\'])?(int)$_POST[\'delivery\']:0;\n		foreach($docs as $doc){\n			$page=$modx->getPageInfo($doc[\'id\'],1,\'*\');\n			$checked=$selected=\"\";\n			if ($page[\'id\']==$eoplata){\n				$selected=\' checked=\"checked\"\';\n				$checked=\" ichecked\";\n			}\n			$tv=$modx->getTemplateVarOutput(\"price\",$page[\'id\']);\n			$price=$tv[\'price\'].\'.-\';\n			$plhv=array($checked,$page[\'id\'],$selected,$page[\'pagetitle\'],$page[\'longtitle\'],$page[\'description\'],$price);\n			$list.=str_replace($plh,$plhv,$tpl);\n		}\n		$fields[\'dostavka\']=$list;\n		\n		$docs=$modx->getActiveChildren(291);\n		$list=\"\";\n		$tpl=$modx->getChunk(\"oplataTpl\");\n		$plh=array(\'[+checked+]\',\'[+id+]\',\'[+selected+]\',\'[+pagetitle+]\',\'[+longtitle+]\',\'[+red+]\',\'[+posted+]\');\n		$eoplata=isset($_POST[\'opla\'])?$_POST[\'opla\']:0;\n		foreach($docs as $doc){\n			$page=$modx->getPageInfo($doc[\'id\'],1,\'*\');\n			$checked=$selected=$red=\"\";\n			if ($page[\'id\']==$eoplata){\n				$selected=\' checked=\"checked\"\';\n				$checked=\" ichecked\";\n			}\n			if ($page[\'id\']==295) $red=\' class=\"required\"\';\n			$posted=\"\";\n			$plhv=array($checked,$page[\'id\'],$selected,$page[\'pagetitle\'],$page[\'longtitle\'],$red,$posted);\n			$list.=str_replace($plh,$plhv,$tpl);\n		}\n		$fields[\'oplata\']=$list;\n	}\n}\n\nif (!function_exists(\"validateFields\")){\n	function validateFields(&$fields,&$rMsg,&$vMsg){\n		if (!isset($fields[\'ecountry\']) || $fields[\'ecountry\']==\"\") $vMsg[]=\'Страна\';\n		if (!isset($fields[\'etown\']) || $fields[\'etown\']==\"\") $vMsg[]=\'Город\';\n		if (!isset($fields[\'opla\']) || $fields[\'opla\']==\"\") $vMsg[]=\'Тип оплаты\';\n		if (!isset($fields[\'delivery\']) || $fields[\'delivery\']==\"\") $vMsg[]=\'Тип доставки\';\n	}\n}\n\nif (!function_exists(\"populateFields\")){\n	function populateFields(&$fields){\n		global $modx;\n		$sql=\"select * from shop_country_table where shop_country_id=\".(int) $fields[\'ecountry\'];\n		$rez=$modx->db->query($sql);\n		if ($modx->db->getRecordCount($rez)){\n			$r=$modx->db->getRow($rez);\n			$fields[\'country_name\']=$r[\'shop_country_name\'];\n		}\n		$sql=\"select * from shop_city_table where shop_city_id=\".(int) $fields[\'etown\'];\n		$rez=$modx->db->query($sql);\n		if ($modx->db->getRecordCount($rez)){\n			$r=$modx->db->getRow($rez);\n			$fields[\'city_name\']=$r[\'shop_city_name\'];\n		}\n		$doc=$modx->getPageInfo((int)$fields[\'delivery\'],1,\'*\');\n		$fields[\'delivery_name\']=$doc[\'pagetitle\'];\n		$doc=$modx->getPageInfo((int)$fields[\'opla\'],1,\'*\');\n		$fields[\'oplata_name\']=$doc[\'pagetitle\'];\n		$_SESSION[\'oplata_type\']=$fields[\'opla\'];\n		$fields[\'payment_online\']=$modx->runSnippet(\'showKeeper\',array());\n		$fields[\'attachment\']=\"\";\n		if ($fields[\'opla\']==294){\n			$tpl=$modx->getChunk(\'bank_kvit\');\n			$plh=array(\'[+fullname+]\',\'[+address+]\');\n			$address=$fields[\'eindex\'].\',\'.$fields[\'country_name\'].\',\'.$fields[\'city_name\'].\',\'.$fields[\'eaddress\'];\n			$plhv=array($fields[\'ename\'],$address);\n			$body=str_replace($plh,$plhv,$tpl);\n			$_SESSION[\'kvit_oplat\']=$body;\n			$_SESSION[\'kvit_oplat_file\']=md5($fields[\'email\'].time()).\'.html\';\n			$fields[\'attachment\']=\'<p><a href=\"\'.$modx->config[\'site_url\'].\'order/\'.$_SESSION[\'kvit_oplat_file\'].\'\">Квитанция к оплате</a></p>\';\n		}\n		unset($fields[\'countries\']);\n		unset($fields[\'towns\']);\n		unset($fields[\'dostavka\']);\n		unset($fields[\'oplata\']);\n		//print_r($fields);die();\n	}\n}\nif(!function_exists(\"fixItem\")){\n	function fixItem(&$fields, &$templates){\n		global $modx;\n	}\n}\nif (!function_exists(\"populateOneClick\")){\n	function populateOneClick(&$fields){\n		global $modx;\n		$doc=$modx->getPageInfo($fields[\'itemid\']);\n		$fields[\'item\']=\'<a href=\"\'.$modx->makeUrl($doc[\'id\'],\'\',\'\',\'full\').\'\" title=\"\'.$doc[\'pagetitle\'].\'\">\'.$doc[\'pagetitle\'].\'</a>\';\n	}\n}\nif (!function_exists(\"fixFile\")){\n	function fixFile(&$fields){\n		if (isset($_SESSION[\'kvit_oplat\'])){\n			$plh=array(\'[+shk_id+]\',\'[+totalPrice+]\');\n			$plhv=array($_SESSION[\'shk_order_id\'],$_SESSION[\'shk_order_price\']);\n			$body=str_replace($plh,$plhv,$_SESSION[\'kvit_oplat\']);\n			file_put_contents(dirname(__FILE__).\'/../../order/\'.$_SESSION[\'kvit_oplat_file\'],$body);\n			unset($_SESSION[\'kvit_oplat\']);\n		}\n	}\n}\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('37','sitemap','','0','0','0','//<?php\n/**\n * Sitemap\n * \n * Outputs a machine readable site map for search engines and robots.\n *\n * @category snippet\n * @version 1.0.11 (2012-10-01)\n * @license LGPL\n * @author Grzegorz Adamiak [grad], ncrossland, DivanDesign (http://www.DivanDesign.biz)\n * @internal @modx_category Navigation\n * \n * @param startid {integer} - Id of the \'root\' document from which the sitemap starts. Default: 0.\n * @param format {string} - Which format of sitemap to use: sp (Sitemap Protocol used by Google), txt (text file with list of URLs), ror (Resource Of Resources). Default: sp.\n * @param seeThruUnpub {0; 1} - See through unpublished documents. Default: 1.\n * @param priority {string} - Name of TV which sets the relative priority of the document. If there is no such TV, this parameter will not be used. Default: \'sitemap_priority\'.\n * @param changefreq {string} - Name of TV which sets the change frequency. If there is no such TV this parameter will not be used. Default: \'sitemap_changefreq\'.\n * @param excludeTemplates {comma separated string} - Documents based on which templates should not be included in the sitemap. Comma separated list with names of templates. Default: \'\'.\n * @param excludeTV {string} - Name of TV (boolean type) which sets document exclusion form sitemap. If there is no such TV this parameter will not be used. Default: \'sitemap_exclude\'.\n * @param xsl {string; integer} - URL to the XSL style sheet or doc ID of the XSL style sheet. Default: \'\'.\n * @param excludeWeblinks {0; 1} - Should weblinks be excluded? You may not want to include links to external sites in your sitemap, and Google gives warnings about multiple redirects to pages within your site. Default: 0.\n */\n \n \n/*\nSupports the following formats:\n\n- Sitemap Protocol used by Google Sitemaps\n  (http://www.google.com/webmasters/sitemaps/)\n\n- URL list in text format\n  (e.g. Yahoo! submission)\n\n\nChangelog:\n# 1.0.11 (2012-10-01) by DivanDesign (http://www.DivanDesign.biz)\n+ Document will be excluded from sitemap when changefreq parameter equals \'exclude\'.\n* [(site_url)] (without alias) is using now for the start page ($modx->config[\'start_page\']) document url.\n# 1.0.10 (2012-02-08) by DivanDesign (http://www.DivanDesign.biz)\n+ Snippet can see through unpublished documents (by default). See the «seeThruUnpub» parameter.\n* Minor changes of code and comments (see the code).\n# 1.0.9 (2010-06-09) by ncrossland\n- update metadata format for use in ModX 1.0.x installer\n# 1.0.8 (2008-08-21)\n- excludeTemplates can now also be specified as a template ID instead of template name. \n  Useful if you change the names of your templates frequently. (ncrossland)\n  e.g. &excludeTemplates=`myTemplateName,3,4`\n# 1.0.7 (2008-07-30)\n- Unpublished and deleted documents were showing up in the sitemap. Even though they could not be viewed, \n  they were showing up as broken links to search engines. (ncrossland)\n# 1.0.6 (2008-02-28)\n- Add optional parameter (excludeWeblinks) to exclude weblinks from the sitemap, since they often point to external\n  sites (which don\'t belong on your sitemap), or redirecting to other internal pages (which are already\n  in the sitemap). Google Webmaster Tools generates warnings for excessive redirects.	\n  Default is false - e.g. default behaviour remains unchanged. (ncrossland)\n# 1.0.5 (2008-02-24)\n- Modification about non searchable documents, as suggested by forum user JayBee\n  (http://modxcms.com/forums/index.php/topic,5754.msg99895.html#msg99895)\n# 1.0.4 (2008-02-06) by Bert Catsburg, bert@catsburg.com\n- Added display option \'ulli\'. \n  An <ul><li> list of all published documents.\n# 1.0.3 (2007-05-16)\n- Added ability to specify the XSL URL - you don\'t always need one and it \n  seems to create a lot of support confusion!\n  It is now a parameter (&xsl=``) which can take either an alias or a doc ID (ncrossland)\n- Modifications suggested by forum users Grad and Picachu incorporated\n  (http://modxcms.com/forums/index.php/topic,5754.60.html)\n# 1.0.2 (2006-07-12)\n- Reworked fetching of template variable value to\n  get INHERITED value.\n# 1.0.1\n- Reworked fetching of template variable value,\n  now it gets computed value instead of nominal;\n  however, still not the inherited value.\n# 1.0\n- First public release.\n\nTODO:\n- provide output for ROR\n--------------------------------------------------\n*/\n\n/* Parameters */\n$startid = (isset($startid)) ? $startid : 0;\n$seeThruUnpub = (isset($seeThruUnpub) && $seeThruUnpub == \'0\') ? false : true;\n$format = (isset($format) && ($format != \'ror\')) ? $format : \'sp\';\n$priority = (isset($priority)) ? $priority : \'sitemap_priority\';\n$changefreq = (isset($changefreq)) ? $changefreq : \'sitemap_changefreq\';\n$excludeTemplates = (isset($excludeTemplates)) ? $excludeTemplates : array();\n$excludeTV = (isset($excludeTV)) ? $excludeTV : \'sitemap_exclude\';\n$xsl = (isset($xsl)) ? $xsl : \'\';\nif (is_numeric($xsl)){ $xsl = $modx->makeUrl($xsl); }\n$excludeWeblinks = (isset($excludeWeblinks)) ? $excludeWeblinks : false;\n/* End parameters */\n\n# get list of documents\n$docs = getDocs($modx, $startid, $priority, $changefreq, $excludeTV, $seeThruUnpub);\n\n\n# filter out documents by template or TV\n# ---------------------------------------------\n// get all templates\n$select = $modx->db->select(\"id, templatename\", $modx->getFullTableName(\'site_templates\'));\nwhile ($query = $modx->db->getRow($select)){\n	$allTemplates[$query[\'id\']] = $query[\'templatename\'];\n}\n\n$remainingTemplates = $allTemplates;\n\n// get templates to exclude, and remove them from the all templates list\nif (!empty ($excludeTemplates)){\n	\n	$excludeTemplates = explode(\",\", $excludeTemplates);	\n	\n	// Loop through each template we want to exclude\n	foreach ($excludeTemplates as $template){\n		$template = trim($template);\n		\n		// If it\'s numeric, assume it\'s an ID, and remove directly from the $allTemplates array\n		if (is_numeric($template) && isset($remainingTemplates[$template])){\n			unset($remainingTemplates[$template]);\n		}else if (trim($template) && in_array($template, $remainingTemplates)){ // If it\'s text, and not empty, assume it\'s a template name\n			unset($remainingTemplates[array_search($template, $remainingTemplates)]);			\n		}\n	}\n}\n\n$output = array();\n// filter out documents which shouldn\'t be included\nforeach ($docs as $doc){\n	//by template, excludeTV, published, searchable\n	if (isset($remainingTemplates[$doc[\'template\']]) && !$doc[$excludeTV] && $doc[$changefreq] != \'exclude\' && $doc[\'published\'] && $doc[\'template\'] != 0 && $doc[\'searchable\']){\n		//exclude weblinks\n		if (!$excludeWeblinks || ($excludeWeblinks && $doc[\'type\'] != \'reference\')){\n			$output[] = $doc;\n		}\n	}\n}\n$docs = $output;\nunset ($output, $allTemplates, $excludeTemplates);\n\n\n# build sitemap in specified format\n# ---------------------------------------------\n\nswitch ($format){\n	// Next case added in version 1.0.4\n	case \'ulli\': // UL List\n		$output .= \"<ul class=\\\"sitemap\\\">\\n\";\n		// TODO: Sort the array on Menu Index\n		// TODO: Make a nested ul-li based on the levels in the document tree.\n		foreach ($docs as $doc){\n			$s  = \"  <li class=\\\"sitemap\\\">\";\n			$s .= \"<a href=\\\"\".($doc[\'id\'] != $modx->config[\'site_start\']) ? \'[(site_url)][~\'.$doc[\'id\'].\'~]\' : \'[(site_url)]\'.\"\\\" class=\\\"sitemap\\\">\" . $doc[\'pagetitle\'] . \"</a>\";\n			$s .= \"</li>\\n\";\n			$output .= $s;\n		}\n		\n		$output .= \"</ul>\\n\";\n	break;\n		\n	case \'txt\': // plain text list of URLs\n\n		foreach ($docs as $doc){\n			$url = ($doc[\'id\'] != $modx->config[\'site_start\']) ? \'[(site_url)][~\'.$doc[\'id\'].\'~]\' : \'[(site_url)]\';\n\n			$output .= $url.\"\\n\";\n		}\n		\n	break;\n\n	case \'ror\': // TODO\n	default: // Sitemap Protocol\n		$output = \'<?xml version=\"1.0\" encoding=\"UTF-8\"?>\'.\"\\n\";\n		if ($xsl != \'\'){\n			$output .=\'<?xml-stylesheet type=\"text/xsl\" href=\"\'.$xsl.\'\"?>\'.\"\\n\";\n		}\n		$output .=\'<urlset xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://www.sitemaps.org/schemas/sitemap/0.9 http://www.sitemaps.org/schemas/sitemap/0.9/sitemap.xsd\" xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\'.\"\\n\";\n		\n		\n		foreach ($docs as $doc)	{\n			$url = ($doc[\'id\'] != $modx->config[\'site_start\']) ? \'[(site_url)][~\'.$doc[\'id\'].\'~]\' : \'[(site_url)]\';\n			$date = $doc[\'editedon\'];\n			$date = date(\"Y-m-d\", $date);\n			$docPriority = ($doc[$priority]) ? $doc[$priority] : 0; // false if TV doesn\'t exist\n			$docChangefreq = ($doc[$changefreq]) ? $doc[$changefreq] : 0; // false if TV doesn\'t exist\n	\n			$output .= \"\\t\".\'<url>\'.\"\\n\";\n			$output .= \"\\t\\t\".\'<loc>\'.$url.\'</loc>\'.\"\\n\";\n			$output .= \"\\t\\t\".\'<lastmod>\'.$date.\'</lastmod>\'.\"\\n\";\n			$output .= ($docPriority) ? (\"\\t\\t\".\'<priority>\'.$docPriority.\'</priority>\'.\"\\n\") : \'\'; // don\'t output anything if TV doesn\'t exist\n			$output .= ($docChangefreq) ? (\"\\t\\t\".\'<changefreq>\'.$docChangefreq.\'</changefreq>\'.\"\\n\") : \'\'; // don\'t output anything if TV doesn\'t exist\n			$output .= \"\\t\".\'</url>\'.\"\\n\";\n		}\n		\n		$output .= \'</urlset>\';\n\n}\n\nreturn $output;\n\n# functions\n# ---------------------------------------------\n\n# gets (inherited) value of templat e variable\n//TODO: wtf? In MODx 0.9.2.1 O_o Is this actually?\nfunction getTV($modx, $docid, $doctv){\n/* apparently in 0.9.2.1 the getTemplateVarOutput function doesn\'t work as expected and doesn\'t return INHERITED value; this is probably to be fixed for next release; see http://modxcms.com/bugs/task/464\n	$output = $modx->getTemplateVarOutput($tv,$docid);\n	return $output[$tv];\n*/\n	\n	while ($pid = $modx->getDocument($docid, \'parent\')){\n		$tv = $modx->getTemplateVar($doctv,\'*\',$docid);\n		if (($tv[\'value\'] && substr($tv[\'value\'],0,8) != \'@INHERIT\') or !$tv[\'value\']){ // tv default value is overriden (including empty)\n			$output = $tv[\'value\'];\n			break;\n		}else{ // there is no parent with default value overriden \n			$output = trim(substr($tv[\'value\'],8));\n		}\n		\n		// move up one document in document tree\n		$docid = $pid[\'parent\'];\n	}\n	\n	return $output;\n}\n\n# gets list of published documents with properties\nfunction getDocs($modx, $startid, $priority, $changefreq, $excludeTV, $seeThruUnpub){\n	//If need to see through unpublished\n	if ($seeThruUnpub){\n		//Get all children documents, filter later\n		$docs = $modx->getAllChildren($startid, \'menuindex\', \'asc\', \'id,editedon,template,published,searchable,pagetitle,type\');\n	}else{\n		//Get only published children documents\n		$docs = $modx->getActiveChildren($startid, \'menuindex\', \'asc\', \'id,editedon,template,published,searchable,pagetitle,type\');\n	} \n\n	// add sub-children to the list\n	foreach ($docs as $key => $doc){\n		$id = $doc[\'id\'];\n		\n		$docs[$key][$priority] = getTV($modx, $id, $priority); // add priority property\n		$docs[$key][$changefreq] = getTV($modx, $id, $changefreq); // add changefreq property\n		$docs[$key][$excludeTV] = getTV($modx, $id, $excludeTV); // add excludeTV property\n		\n		//TODO: $modx->getAllChildren & $modx->getActiveChildren always return the array\n// 		if ($modx->getAllChildren($id)){\n			$docs = array_merge($docs, getDocs($modx, $id, $priority, $changefreq, $excludeTV, $seeThruUnpub));\n// 		}\n\n	}\n	return $docs;\n}','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('38','searchCatalogItems','','0','0','0','\n$tpl=\'searchInnerItem\';\n$params=array(\n	\'ajaxSearch\'=>0,\n	\'whereSearch\'=>\'content:pagetitle,introtext,content|tv:null\',\n	\'landingPage\'=>283,\n	\'showResults\'=>1,\n	\'showInputForm\'=>0,\n	\'pagingType\'=>0,\n	\'parents\'=>\'in:10\',\n	\'filter\'=>\'isfolder,1,2\',\n	\'tplResult\'=>\'searchResult\',\n	\'grabMax\'=>0,\n	\'tplResults\'=>\'searchResults\',\n	\'tplGrpResult\'=>\'tplGrpResult\'\n);\nif (!isset($_SESSION[\'searchRezult\'][$_POST[\'search\']])) {\n	$out=$modx->runSnippet(\'AjaxSearch\',$params);\n	$_SESSION[\'searchRezult\'][$_POST[\'search\']]=$out;\n} else {\n	$out=$_SESSION[\'searchRezult\'][$_POST[\'search\']];\n}\n$params=array(\n	\'documents\'=>$out,\n	\'tpl\'=>$tpl,\n	\'display\'=>\'all\',\n	\'orderBy\'=>\'pub_date desc\',\n	\'depth\'=>2,\n	\'where\'=>\'isfolder=0\',\n	\'paginate\'=>0,\n	\'id\'=>\'catid\',\n	\'tplPaginateNext\'=>\'catalogNext\',\n	\'tplPaginatePrevious\'=>\'catalogPrev\'\n);\nreturn $modx->runSnippet(\'Ditto\',$params);\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('39','Duplicate of sliderMain','','0','19','0','\n$output=\"\";\n$docs=explode(\",\",$modx->documentObject[\"main_slider\"][1]);\n$im_array=array();\nforeach ($docs as $k=>$v){\n	$images=$modx->getTemplateVarOutput(array(\"item_image\",\"photos\"),$v);\n	if ($images[\"item_image\"]==\"\"){\n		$im=\"\";\n		if ($images[\"photos\"]!=\"\"){\n			$t=json_decode($images[\"photos\"],true);\n			$im=$t[\'fieldValue\'][0][\'image\'];\n		}\n	} else {\n		$im=$images[\"item_image\"];\n	}\n	$im_array[]=$im;\n}\n//print_r($im_array);\n$t=$im_array;\n$left_html=\'<img src=\"[[phpthumb? &input=`\'.array_pop($t).\'` &options=`w=78,h=136,far=1,f=jpeg,q=90`]]\" />\';\nforeach ($t as $k=>$v){\n	$left_html.=\'<img src=\"[[phpthumb? &input=`\'.$v.\'` &options=`w=78,h=136,far=1,f=jpeg,q=90`]]\" />\';\n}\n$left_html=\'<div class=\"car_wrapl\"><div id=\"carousel_left\">\'.$left_html.\'</div></div>\';\n$t=$im_array;\n$right_html=\"\";\nforeach ($t as $k=>$v){\n	if (!$k){\n		$right_last.=\'<img src=\"[[phpthumb? &input=`\'.$v.\'` &options=`w=78,h=136,far=1,f=jpeg,q=90`]]\" />\';\n	} else {\n		$right_html.=\'<img src=\"[[phpthumb? &input=`\'.$v.\'` &options=`w=78,h=136,far=1,f=jpeg,q=90`]]\" />\';\n	}\n}\n$right_html=\'<div class=\"car_wrapr\"><div id=\"carousel_right\">\'.$right_html.$right_last.\'</div></div>\';\n$params=array(\n	\'documents\'=>$modx->documentObject[\"main_slider\"][1],\n	\'tpl\'=>\'sliderInner\',\n	\'outerTpl\'=>\'sliderOuter\',\n	\'display\'=>\'all\',\n	\'extenders\'=>\'nosort\'\n);\n$c=$modx->runSnippet(\'Ditto\',$params);\n$output=$left_html.$c.$right_html;\nreturn $output;\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('40','dropDownTvDoc','','0','0','0','\nglobal $modx;\n	$docid=isset($docid)?(int)$docid:false;\n	$field=isset($field)?$field:\'pagetitle\';\n	$useNull=isset($useNull)?$useNull:1;\n	if ($useNull) $output=\"  ==0\";\n	if($docid){\n		$childs=$modx->getActiveChildren($docid,$field,\'ASC\');\n		foreach($childs as $children){\n			$output.=strlen($output)>0?\'||\':\'\';\n			$output.=$children[\'pagetitle\'].\"==\".$children[\'id\'];\n		}\n	}\n	return $output;\n','0','',' ');
