INSERT INTO `modx_site_snippets` VALUES ('42','Paykeeper','','0','0','0','\n\n/*******************************************\n* http://modx-shopkeeper.ru/\n* ----------------------------------\n* Paykeeper 1.5\n* Snippet for payments in MODx + Shopkeeper\n*******************************************/\n\n$output = \'\';\n\nrequire_once \"assets/snippets/paykeeper/paykeeper.inc.php\";\n\nreturn $output;\n\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('43','showKeeper','','0','0','0','\nswitch ($_SESSION[\'oplata_type\']){\n	case 292:\n	case 293:\n	 $modx->setPlaceholder(\'allow_online\',1);\n		\n	// 1.\n	// Оплата заданной суммы с выбором валюты на сайте мерчанта\n	// Payment of the set sum with a choice of currency on merchant site \n	\n	// регистрационная информация (логин, пароль #1)\n	// registration info (login, password #1)\n	$mrh_login = \"traserh3\";\n	$mrh_pass1 = \"War564Craft\";\n	\n	// номер заказа\n	// number of order\n	$inv_id = $_SESSION[\'shk_order_id\'];\n	\n	// описание заказа\n	// order description\n	$inv_desc = \"Оплата счета\";\n	\n	// сумма заказа\n	// sum of order\n	$out_summ = $_SESSION[\'shk_order_price\'];\n	\n	// тип товара\n	// code of goods\n	$shp_item = 1;\n	\n	// предлагаемая валюта платежа\n	// default payment e-currency\n	$in_curr = \"\";\n	\n	// язык\n	// language\n	$culture = \"ru\";\n	\n	// кодировка\n	// encoding\n	$encoding = \"utf-8\";\n	\n	// формирование подписи\n	// generate signature\n	$crc  = md5(\"$mrh_login:$out_summ:$inv_id:$mrh_pass1:Shp_item=$shp_item\");\n	$plh=array(\'[+mrh_login+]\',\'[+out_summ+]\',\'[+inv_id+]\',\'[+inv_desc+]\',\'[+crc+]\');\n		$plhv=array($mrh_login,$out_summ,$inv_id,$inv_desc,$crc);\n	// HTML-страница с кассой\n	// ROBOKASSA HTML-page\n	echo \'<p>Перейти к оплате</p>\'.str_replace($plh,$plhv,$modx->getChunk(\"robokassa\"));\n	break;\n	case 294:\n		if (isset($_SESSION[\'kvit_oplat_file\'])) {\n			echo \'<p>На вашу электронную почту отправлена квитанция на оплату<br /><a href=\"/order/\'.$_SESSION[\'kvit_oplat_file\'].\'\">Распечатайте бланк квитанции по форме ПД-4 </a></p>\';\n			unset($_SESSION[\'kvit_oplat_file\']);\n		}\n		break;\n	case 470:\n	//echo \'<!--<p>Вы выбрали оплату при помощи системы Net Pay</p>-->\';\n		echo $modx->runSnippet(\'netpay\');\n	default:\n		echo $modx->documentObject[\'content\'];\n		break;\n\n}\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('44','netpay','','0','13','0','\n\n// Рабочий режим\n	$AuthSign = \'590\';\n	$api_key = \'oqsj61t9v6jj3d7612hkc84lm8\';\n$submitval = \'Оплатить\';\n	$netpay_url = \'https://my.net2pay.ru/billingService/paypage/\';\n$host = \'\';\n$inn = \'7718648009\';\n\n	\n	// Тестовый режим\n/*	$AuthSign = \'1\';\n	$api_key = \'js4cucpn4kkc6jl1p95np054g2\';\n	$netpay_url = \'https://demo.net2pay.ru/billingService/paypage/\';\n$host = \'test2.atol.ru\';\n$inn=\'7717586110\';*/\n\nif (empty($email) && isset($_SESSION[\'shk_order_user_email\'])) {\n	$email = $_SESSION[\'shk_order_user_email\'];\n}\n	\n\n	$order_id_field_id = \'shk_order_id\';\n	$price_field_id = \'shk_order_price\';\n	\n$hint = \"Для оплаты заказа нажмите кнопку \\\"$submitval\\\" и Вы будете перенаправлены на защищённую страницу компании Net Pay.\";\n	\n	if (!function_exists(\'encrypt\'))\n	{\n	function encrypt($input, $key) {\n			$size = mcrypt_get_block_size(MCRYPT_RIJNDAEL_128, MCRYPT_MODE_ECB); \n			$input = pkcs5_pad($input, $size); \n			$td = mcrypt_module_open(MCRYPT_RIJNDAEL_128, \'\', MCRYPT_MODE_ECB, \'\'); \n			$iv = mcrypt_create_iv (mcrypt_enc_get_iv_size($td), MCRYPT_RAND); \n			mcrypt_generic_init($td, $key, $iv); \n			$data = mcrypt_generic($td, $input); \n			mcrypt_generic_deinit($td); \n			mcrypt_module_close($td); \n			$data = base64_encode($data); \n			return $data; \n		} \n	}\n	if (!function_exists(\'pkcs5_pad\'))\n	{\n	function pkcs5_pad ($text, $blocksize) { \n			$pad = $blocksize - (strlen($text) % $blocksize); \n			return $text . str_repeat(chr($pad), $pad); \n		}\n	}\n	\n	$order_id = $_SESSION[$order_id_field_id]; \n	$amount = $_SESSION[$price_field_id]; \n	$successUrl = \'http://\'.$_SERVER[\'HTTP_HOST\'];\n	$failUrl = \'http://\'.$_SERVER[\'HTTP_HOST\'];\n	//$netpay_url = \'https://demo.net2pay.ru/billingService/paypage/\'; \n	//$api_key = \'8d4mntd3ls51q6me5au0n0102b\';\n	//$AuthSign= \'2\';\n	$md5_Api_key = base64_encode(md5($api_key, true));    \n	$dateClass = new DateTime();\n	$dateClass->modify(\'+1 day\');\n	$order_date = $dateClass->format(\'Y-m-dVH:i:s\');\n	$cryptoKey = substr(base64_encode(md5($md5_Api_key.$order_date, true)),0,16);\n	$params = array();\n	$params[\'description\'] = \'ORDER \'.$order_id;\n	$params[\'amount\'] = $amount;\n	$params[\'currency\'] = \'RUB\';\n	$params[\'orderID\'] = $order_id;\n	$params[\'phone\'] = $phone;\n	$params[\'email\'] = $email;\n	$params[\'cardHolderCity\'] = \"\";\n	$params[\'cardHolderCountry\'] = \"\";\n	$params[\'cardHolderPostal\'] = \"\";\n	$params[\'cardHolderRegion\'] = \"\";\n	$params[\'successUrl\'] = $successUrl;\n	$params[\'failUrl\'] = $failUrl;\n	$manager_email = \'\';\n\n	// Cashbox	\n	require_once(MODX_BASE_PATH.\'/netpay/netpay_atol.php\');\n	\n	$netpayAtol = new NetpayAtol($inn, $params[\'email\'], $params[\'amount\'], $host, $params[\'phone\']);\n	\n	// get order items\n//if ($_SERVER[\'REMOTE_ADDR\'] == \'213.33.206.154\') { \n	if (isset($_SESSION[\'npready\'])) { // on first load can not load order from db\n		//var_dump($params[\'orderID\']);var_dump($order_id);\n		global $modx;\n		$tn = $modx->getFullTableName(\'manager_shopkeeper\');\n		//var_dump($tn);\n		//var_dump($_SESSION);\n		$res1 = $modx->db->select(\"content\", $modx->getFullTableName(\'manager_shopkeeper\'), \"id=\".($order_id));\n		//var_dump($res1);\n		$cont = $modx->db->getValue($res1);\n		//echo \'content: \';\n		//var_dump($cont);\n		$products = unserialize($cont);\n		foreach ($products as $product) {\n			if ($product[\'2\'] * $product[\'1\'] > 0) // now Business.ru not allow null sum\n			$netpayAtol->addItem(\n				$product[\'3\'], \n				$product[\'2\'], \n				$product[\'1\'], \n				$product[\'2\'] * $product[\'1\'], \n				\'none\'\n			);\n		}\n		\n		$params[\'cashbox_data\'] = $netpayAtol->getJSON(); \n	}\n//}	\n	$params_crypted = array();\n\n	foreach ($params as $key=>$param){            \n		$cripter = encrypt($key.\'=\'.$param, $cryptoKey);\n		$params_crypted[] = $cripter;\n	}\n	\n	$params_crypted_str = implode(\'&\', $params_crypted);\n\nif (!isset($_SESSION[\'npready\'])) {\n	$_SESSION[\'npready\'] = 1;\n	$button = \'<script> document.location.href += \"?npreload=\"; </script>\';\n}\nelse {\n  	$button = \'<form action=\"\'.$netpay_url.\'\" method=\"POST\" target=\"_blank\">\n                 \n                <input type=\"hidden\" name=\"data\" value=\"\'.urlencode($params_crypted_str).\'\">\n                <input type=\"hidden\" name=\"auth\" value=\"\'.$AuthSign.\'\">\n                <input type=\"hidden\" name=\"expire\" value=\"\'.urlencode($order_date).\'\">\n\n                <input type=\"image\" src=\"http://traserh3.ru/assets/images/cart_buy_oplatit.png\" name=\"Submit\"	value=\"\'.$submitval.\'\"> \n        </form>\';\n}\n\n	$link = $netpay_url.\"?data=\".urlencode($params_crypted_str).\"&auth=\".$AuthSign.\"&expire=\".urlencode($order_date);\n	$link = str_replace(\"%\", \"%25\", $link);\n	\n	$link = \"http://\".$_SERVER[\'SERVER_NAME\'].\"/netpay/?data=\".urlencode($params_crypted_str).\"&auth=\".$AuthSign.\"&expire=\".urlencode($order_date);\n	$link = str_replace(\"%\", \"%25\", $link);        	\n	$html = $method->textinsteadbutton;\n	$headers = \"From: \".$method->mailforsend.\"\\r\\n\" . \'X-Mailer: PHP/\' . phpversion();\n	$text = \"ID: \".$order_id.\"\\n\\n\";\n	$text .= \"summ: \".$amount.\" RUB\\n\\n\";        	\n	$text .= \"link: \\n\\n\".$link;\n	if ($manager_email)\n	{\n		mail($manager_email, \"Order №\".$order_id.\" from \".$_SERVER[\'SERVER_NAME\'], $text, $headers);\n		\n		return \'После уточнения деталей заказа мы отправим Вам ссылку на оплату\';\n	}\n	else       		\n		return \"<p>\".$hint.\"</p>\\n\\r\".$button.\"\\n\\r\";\n\n	return \'\';\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('45','netpay_notification','','0','13','0','\n$api_key = \'8d4mntd3ls51q6me5au0n0102b\';\n$auth = 2;\n\nrequire_once(\'netpay/notification/npnotification_class.php\');\n$notification = new Npnotification();\n\nif (array_key_exists(\'data\', $_GET) && array_key_exists(\'auth\', $_GET) && array_key_exists(\'expire\', $_GET))\n{\n	if ($_GET[\'auth\'] == $auth)\n	{\n		$getData = $notification->getdata($_GET[\'data\'], $_GET[\'expire\'], $api_key);\n\n		if (($getData[\'error\'] == \'000\') || ($getData[\'error\'] == \'0\') && $getData[\'status\'] === \'APPROVED\')\n		{\n			// У заказа устанавливается статус \"Оплата получена\"\n			$modx->addPackage(\'shopkeeper3\', $modx->getOption(\'core_path\').\'components/shopkeeper3/model/\');\n			$order = $modx->getObject(\'shk_order\', $getData[\'orderID\']);\n			$order->set(\'status\', 6); // Статус \"Оплата получена\"\n			$order->save();\n\n			$getData[\'status\'] = \'1\';\n			$getData[\'error\'] = \'\';\n\n			$notification->giveanswer($getData);\n		}\n		else\n		{\n			$getData[\'status\'] = \'0\';\n			$notification->giveanswer($getData);\n		}\n	}\n	else\n	{\n		$getData[\'status\'] = 0;\n		$getData[\'error\'] = \'Wrong auth value\';\n		$notification->giveanswer($getData);\n	}\n}\nelse\n{\n	$getData[\'status\'] = 0;\n	$getData[\'error\'] = \'Required parameters missing\';\n	$notification->giveanswer($getData);\n}\n\n\n','0','',' ');
INSERT INTO `modx_site_snippets` VALUES ('46','showKeeper_bak','','0','0','0','\nswitch ($_SESSION[\'oplata_type\']){\n	case 292:\n	case 293:\n	 $modx->setPlaceholder(\'allow_online\',1);\n		\n	// 1.\n	// Оплата заданной суммы с выбором валюты на сайте мерчанта\n	// Payment of the set sum with a choice of currency on merchant site \n	\n	// регистрационная информация (логин, пароль #1)\n	// registration info (login, password #1)\n	$mrh_login = \"traserh3\";\n	$mrh_pass1 = \"War564Craft\";\n	\n	// номер заказа\n	// number of order\n	$inv_id = $_SESSION[\'shk_order_id\'];\n	\n	// описание заказа\n	// order description\n	$inv_desc = \"Оплата счета\";\n	\n	// сумма заказа\n	// sum of order\n	$out_summ = $_SESSION[\'shk_order_price\'];\n	\n	// тип товара\n	// code of goods\n	$shp_item = 1;\n	\n	// предлагаемая валюта платежа\n	// default payment e-currency\n	$in_curr = \"\";\n	\n	// язык\n	// language\n	$culture = \"ru\";\n	\n	// кодировка\n	// encoding\n	$encoding = \"utf-8\";\n	\n	// формирование подписи\n	// generate signature\n	$crc  = md5(\"$mrh_login:$out_summ:$inv_id:$mrh_pass1:Shp_item=$shp_item\");\n	$plh=array(\'[+mrh_login+]\',\'[+out_summ+]\',\'[+inv_id+]\',\'[+inv_desc+]\',\'[+crc+]\');\n		$plhv=array($mrh_login,$out_summ,$inv_id,$inv_desc,$crc);\n	// HTML-страница с кассой\n	// ROBOKASSA HTML-page\n	echo \'<p>Перейти к оплате</p>\'.str_replace($plh,$plhv,$modx->getChunk(\"robokassa\"));\n	break;\n	case 294:\n		if (isset($_SESSION[\'kvit_oplat_file\'])) {\n			echo \'<p>На вашу электронную почту отправлена квитанция на оплату<br /><a href=\"/order/\'.$_SESSION[\'kvit_oplat_file\'].\'\">Распечатайте бланк квитанции по форме ПД-4 </a></p>\';\n			unset($_SESSION[\'kvit_oplat_file\']);\n		}\n		break;\n	default:\n		echo $modx->documentObject[\'content\'];\n		break;\n\n}\n','0','',' ');
