"/assets/templates/olec/index.php/?___store=sweden\">\n        		Cyan			</a>\n		</li>\n                <li>\n        	<a class=\"italy actived\" href=\"/assets/templates/olec/index.php/\">\n        		Brown			</a>\n		</li>\n            </ul>  \n</div>\n        </div>\n        <div class=\"box-layout\">\n			<h3>Layout</h3>\n			<select name=\"cpitem_layoutstyle\" class=\"cpitem_layoutstyle\">\n				<option value=\"1\"  selected=\"selected\">Full Width</option>\n				<option value=\"2\" >Boxed</option>\n			</select>\n		</div>\n		<div class=\"box-menu\">\n			<h3>Menu</h3>\n			<select name=\"cpitem_menustyle\" class=\"cpitem_menustyle\">\n				<option value=\"mega\"  selected=\"selected\">Mega Menu</option>\n				<option value=\"css\" >Css Menu</option>\n			</select>\n		</div>\n		<!--<div class=\"box-btncp\">\n			<button class=\"btn-cpdefault\">Default</button>\n			<button class=\"btn-apply\">Apply</button>\n		</div>-->	\n		<div id=\"btn_toggle\" class=\"btnclose\"></div>\n</div>\n            </div>\n                        <div id=\"box-content\" class=\"category-products\">\n\n								<div class=\"box-slideshow\">\n					<script type=\"text/javascript\">\n	// <![CDATA[\n		jQuery(document).ready(function($) {			\n		  $(\'#vt_slideshow9018602861536094304\').revolution({\n			 delay:9000,\n			 startwidth:1170,\n			 startheight:500,\n	 		 \n	 		 navigationArrows:\"nextto\", // nextto, solo, none\n\n			 navigationType:\"bullet\", // bullet, thumb, none\n			 navigationStyle:\"round\", // round,square,navbar,round-old,square-old,navbar-old\n\n	 					 \n	 \n			 fullScreenOffsetContainer:\"#vt_header, #vt_menu\"\n		  });\n	   });\n	// ]]>\n</script>\n		    <div class=\"vt-slideshow\" id=\"vt_slideshow9018602861536094304\">\n		<ul>\n    	\n<li data-transition=\"fade\" data-slotamount=\"5\" data-masterspeed=\"700\"><img style=\"background-color: #f7f7f9;\" src=\"/assets/templates/olec/media/wysiwyg/sl1.jpg\" alt=\"\" data-bgfit=\"cover\" data-bgposition=\"left top\" data-bgrepeat=\"no-repeat\" />\n<div class=\"tp-caption large_text sft\" data-x=\"230\" data-y=\"230\" data-start=\"1000\" data-speed=\"1000\" data-easing=\"Linear.easeNone\" data-endspeed=\"300\" data-endeasing=\"Power1.easeIn\"><span class=\"hidden-text\">the world at your fingertips</span></div>\n</li>\n\n<li data-transition=\"fade\" data-slotamount=\"15\" data-masterspeed=\"300\" data-delay=\"7500\"><img style=\"background-color: #f7f7f9;\" src=\"/assets/templates/olec/media/wysiwyg/sl2.jpg\" alt=\"\" data-bgfit=\"cover\" data-bgposition=\"left top\" data-bgrepeat=\"no-repeat\" />\n<div class=\"tp-caption large_text randomrotate\" data-x=\"230\" data-y=\"230\" data-start=\"1000\" data-speed=\"1000\" data-easing=\"Power4.easeOut\" data-endspeed=\"300\" data-endeasing=\"Power1.easeIn\" data-captionhidden=\"off\"><span class=\"slide2-title hidden-text\">The world\'s best materials</span></div>\n</li>\n\n<li data-transition=\"fade\" data-slotamount=\"15\" data-masterspeed=\"300\" data-delay=\"7500\"><img style=\"background-color: #f7f7f9;\" src=\"/assets/templates/olec/media/wysiwyg/sl3.jpg\" alt=\"\" data-bgfit=\"cover\" data-bgposition=\"left top\" data-bgrepeat=\"no-repeat\" />\n<div class=\"tp-caption large_text randomrotate\" data-x=\"230\" data-y=\"230\" data-start=\"1000\" data-speed=\"1000\" data-easing=\"Power4.easeOut\" data-endspeed=\"300\" data-endeasing=\"Power1.easeIn\" data-captionhidden=\"off\"><span class=\"slide2-title hidden-text\">the world at your fingertips</span></div>\n</li>\n\n		</ul>\n		<div class=\"tp-bannertimer tp-bottom\"></div>\n    </div>\n        				</div>    \n								                				\n				                <div class=\"box-banner-home\">\n                    <div class=\"container\">\n                        <div class=\"row\">\n							<div class=\"wrap-banner-home\">\n<div class=\"banner-1 col-lg-4 col-md-4 col-sm-4 col-xs-12\">\n<div class=\"item-box\"><a href=\"#\"> <img src=\"/assets/templates/olec/media/wysiwyg/images/banner1.png\" alt=\"banner 1\" /></a>\n<div class=\"bg-hover\">&nbsp;</div>\n<div class=\"item-box-hover\">\n<p class=\"item-box-title\">CK WATCHES</p>\n<p class=\"item-box-desc\">Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor</p>\n<p class=\"item-box-detail\"><a href=\"#\">SHOP NOW</a></p>\n</div>\n</div>\n</div>\n<div class=\"banner-2 col-lg-8 col-md-8 col-sm-8 col-xs-12\">\n<div class=\"item-box row1\"><a class=\"row1\" href=\"#\"><img src=\"/assets/templates/olec/media/wysiwyg/images/banner2.png\" alt=\"banner 2\" /></a>\n<div class=\"bg-hover\">&nbsp;</div>\n<div class=\"item-box-hover\">\n<p class=\"item-box-title\">CK WATCHES</p>\n<p class=\"item-box-desc\">Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor</p>\n<p class=\"item-box-detail\"><a href=\"#\">SHOP NOW</a></p>\n</div>\n</div>\n<div class=\"item-box row2\"><a class=\"row2\" href=\"#\"> <img src=\"/assets/templates/olec/media/wysiwyg/images/banner3.png\" alt=\"banner 3\" /></a>\n<div class=\"bg-hover\">&nbsp;</div>\n<div class=\"item-box-hover\">\n<p class=\"item-box-title\">CK WATCHES</p>\n<p class=\"item-box-desc\">Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor</p>\n<p class=\"item-box-detail\"><a href=\"#\">SHOP NOW</a></p>\n</div>\n</div>\n<div class=\"item-box\"><a href=\"#\"><img src=\"/assets/templates/olec/media/wysiwyg/images/banner4.png\" alt=\"banner4\" /></a>\n<div class=\"bg-hover\">&nbsp;</div>\n<div class=\"item-box-hover\">\n<p class=\"item-box-title\">CK WATCHES</p>\n<p class=\"item-box-desc\">Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor</p>\n<p class=\"item-box-detail\"><a href=\"#\">SHOP NOW</a></p>\n</div>\n</div>\n</div>\n</div>							\n                        </div>\n                    </div>                    \n                </div>    \n                				\n                				\n                <div class=\"main-container col1-layout\">\n                    <div class=\"main\">           \n                        <div class=\"box-breadcrumbs\">\n							<div class=\"container\">\n								<div class =\"row\">\n																	</div>\n							</div>\n						</div>\n                        <div class=\"col-main\">\n							<div class=\"container\">\n								<div class=\"row\">\n																	</div>\n							</div>\n							<div class=\"std\"><div class=\"no-display\">&nbsp;</div></div>\n<script type=\"text/javascript\">\n//<![CDATA[\njQuery(document).ready(function($){\n	(function(element){\n			var $element = $(element),\n				itemNav = $(\'.item-nav\',$element),\n				itemContent = $(\'.pdt-content\',$element),\n				btn_loadmore = $(\'.btn-loadmore\',$element),\n				ajax_url=\"/assets/templates/olec/index.php/ajaxtabs/index/ajax\",\n				catids = \'17,18,19,20\',\n				label_allready = \'All Ready\',\n				label_loading = \'Loading ...\',\n				label_loadmore = \'Load More\';\n\n			function setAnimate(el){\n				$_items = $(\'.item-animate\',el);\n				$(\'.btn-loadmore\',el).fadeOut(\'fast\');\n				$_items.each(function(i){\n					$(this).attr(\"style\", \"-webkit-animation-delay:\" + i * 150 + \"ms;\"\n			                + \"-moz-animation-delay:\" + i * 150 + \"ms;\"\n			                + \"-o-animation-delay:\" + i * 150 + \"ms;\"\n			                + \"animation-delay:\" + i * 150 + \"ms;\");\n			        if (i == $_items.size() -1) {\n			            $(\".pdt-list\", el).addClass(\"play\");\n			            $(\'.btn-loadmore\', el).fadeIn(i*0.3);\n			        }\n				});\n			}\n			setAnimate($(\'.tab-content-actived\',$element));\n\n			itemNav.click(function(){\n				var $this = $(this);\n				if($this.hasClass(\'tab-nav-actived\')) return false;\n				itemNav.removeClass(\'tab-nav-actived\');\n				$this.addClass(\'tab-nav-actived\');\n				var itemActive = \'.\'+$this.attr(\'data-href\');\n				itemContent.removeClass(\'tab-content-actived\');\n				$(\".pdt-list\").removeClass(\"play\");$(\".pdt-list .item\").removeAttr(\'style\');\n				$(\'.item\',$(itemActive, $element)).addClass(\'item-animate\').removeClass(\'animated\');\n				$(itemActive, $element).addClass(\'tab-content-actived\');\n\n				contentLoading = $(\'.content-loading\',$(itemActive, $element));\n				isLoaded = $(itemActive, $element).hasClass(\'is-loaded\');\n				if(!isLoaded && !$(itemActive, $element).hasClass(\'is-loading\')){\n					$(itemActive, $element).addClass(\'is-loading\');\n					contentLoading.show();\n					pdt_type = $this.attr(\'data-type\');\n					catid = $this.attr(\'data-catid\');\n					orderby = $this.attr(\'data-orderby\');\n					$.ajax({\n						type: \'POST\',\n						url: ajax_url,\n						data:{\n							numberstart: 0,\n							catid: catid,\n							orderby: orderby,\n							catids: catids,\n							pdt_type: pdt_type\n						},\n						success: function(result){\n							if(result.listProducts !=\'\'){\n								$(\'.pdt-list\',$(itemActive, $element)).html(result.listProducts);\n								$(itemActive, $element).addClass(\'is-loaded\').removeClass(\'is-loading\');\n								contentLoading.remove();\n								setAnimate($(itemActive, $element));\n								setResult($(itemActive, $element));\n							}\n						},\n						dataType:\'json\'\n					});\n				}else{\n					$(\'.item\', itemContent ).removeAttr(\'style\');\n					setAnimate($(itemActive, $element));\n				}\n			});\n			function setResult(content){\n				$(\'.btn-loadmore\', content).removeClass(\'loading\');\n				itemDisplay = $(\'.item\', content).length;\n				$(\'.btn-loadmore\', content).parent(\'.pdt-loadmore\').attr(\'data-start\', itemDisplay);\n				total = $(\'.btn-loadmore\', content).parent(\'.pdt-loadmore\').attr(\'data-all\');\n				loadnum = $(\'.btn-loadmore\', content).parent(\'.pdt-loadmore\').attr(\'data-loadnum\');\n				if(itemDisplay < total){\n					$(\'.load-number\', content).attr(\'data-total\', (total - itemDisplay));\n     				if((total - itemDisplay)< loadnum ){\n     					$(\'.load-number\',  content).attr(\'data-more\', (total - itemDisplay));\n     				}\n				}\n				if(itemDisplay == total){\n					$(\'.load-number\', content).css({display: \'none\'});\n					$(\'.btn-loadmore\', content).addClass(\'loaded\');\n					$(\'.load-text\', content).text(label_allready);\n				}else{\n					$(\'.load-text\', content).text(label_loadmore);\n				}\n			}\n			btn_loadmore.on(\'click.loadmore\', function(){\n				var $this = $(this);\n				itemActive = \'.\'+$this.parent(\'.pdt-loadmore\').attr(\'data-href\');\n				$(\".pdt-list\").removeClass(\"play\");$(\".pdt-list .item\").removeAttr(\'style\');\n				$(\'.item\',$(itemActive, $element)).addClass(\'animated\').removeClass(\'item-animate\');\n				if ($this.hasClass(\'loaded\') || $this.hasClass(\'loading\')){\n					return false;\n				}else{\n					$this.addClass(\'loading\'); $(\'.load-text\', $this).text(label_loading);\n					numberstart = $this.parent(\'.pdt-loadmore\').attr(\'data-start\');\n					catid = $this.parent(\'.pdt-loadmore\').attr(\'data-catid\');\n					pdt_type = $this.parent(\'.pdt-loadmore\').attr(\'data-type\');\n					orderby = $this.parent(\'.pdt-loadmore\').attr(\'data-orderby\');\n					$.ajax({\n						type: \'POST\',\n						url: ajax_url,\n						data:{\n							numberstart: numberstart,\n							catid: catid,\n							orderby: orderby,\n							catids: catids,\n							pdt_type: pdt_type\n						},\n						success: function(result){\n							if(result.listProducts !=\'\'){\n								animateFrom = $(\'.item\',$(itemActive, $element)).size();\n								$(result.listProducts).insertAfter($(\'.item\',$(itemActive, $element)).nextAll().last());\n								setAnimate($(itemActive, $element));\n								setResult($(itemActive, $element));\n							}\n						},\n						dataType:\'json\'\n					});\n				}\n				return false;\n			});\n	})(\'#vt_ajaxtabs7560228111536094305\');\n});\n//]]>\n</script><div id=\"vt_ajaxtabs7560228111536094305\" class=\"vt-ajaxtabs\">\n	<div class=\"container\">\n		<div class=\"row\">			\n			<div class=\"vt-ajaxtabs-left col-lg-3 col-md-3 col-sm-3 col-xs-12\">\n