INSERT INTO `modx_site_templates` VALUES ('21','Заказ в 1 клик','','0','22','','0','[!eFormActions!]\n[!eForm? &formid=`oneclick` &tpl=`oneClickTpl` &vericode=`1` &ccsender=`1` &report=`oneClickReport` &subject=`Новый заказ в магазине Traser (купить в 1 клик)` &to=`[[DocInfo? &docid=`1` &tv=`1` &field=`manemail`]]` &thankyou=`oneClickThank` &onBeforeFormParse=`fixItem` &eFormOnBeforeMailSent=`populateOneClick`!]\n{{oneClickJS}}','0');
INSERT INTO `modx_site_templates` VALUES ('23','Онлайн-оплата','','0','21','','0','<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"en\" lang=\"en\">\n<head>\n{{head}}\n	{{cart_actions}}\n	{{table_fix}}\n	{{fancybox}}\n</head>\n<body class=\"vt_olec   catalog-category-view categorypath-men category-men\">\n<script type=\"text/javascript\">\n//<![CDATA[\n	var ajaxcartConfig = null;\n    var defaultConfig = {\"enable\":1,\"loadingImage\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/media\\/flycart\\/config\\/default\\/ajax-loader1.gif\",\"loadingAlign\":\"top\",\"custom_cart\":false,\"visible_top_cart\":\"1\",\"loadingText\":\"\",\"show_confirmation\":null,\"updateqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateQty\\/\",\"updatecartqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateCartQty\\/\",\"updateattqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateAttQty\\/\",\"updateproductqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateProductQty\\/\",\"qty_update_cart_page\":\"0\",\"qty_update_category_page\":\"0\",\"qty_update_product_page\":0,\"qty_update_crosssell\":\"0\",\"show_window\":\"1\",\"auto_hide_window\":\"10\",\"redirect_to\":\"0\",\"effect\":\"1\",\"cart_button_color\":\"orange\",\"window_width\":\"550\",\"related_product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/relatedProduct\\/\",\"name_url_encoded\":\"uenc\"};     \n    var defaultQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyDown(#flycart_item, #validate_qty)\\\">down<\\/a>\\r\\n<input class=\\\"input-text qty flycart-qty\\\" type=\\\"text\\\" id=\\\"flycart_prod_id_#flycart_item\\\" value=\\\"1\\\" \\/>\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyUp(#flycart_item, #validate_qty)\\\">up<\\/a>\";\n    var cartQtyTemp = \"\";\n    var productQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyProductDown(#product_id)\\\">down<\\/a>\\r\\n#flycart_qty_input\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyProductUp(#product_id)\\\">up<\\/a>\";\n    var continueMessage = \'Continue Shopping\'; \n		Event.observe(window, \'load\', function() {\n		new Ajax.Request(\'http://demo.7uptheme.com/olec/index.php/flycart/index/topcart/isAjax/1/\', {\n			onSuccess: function(transport) {\n				eval(\'var response = \'+transport.responseText);\n				$$(\".header-container .top-link-cart\").each(function(s){\n					s.innerHTML = response.cart;\n				});	\n			}\n		});\n		\n	});\n	//]]>\n</script>\n\n<div id=\"flycart_confirm_window\" style=\"display: none;\" class=\"flycart-continue-gray flycart-checkout-orange\">\n	<div class=\"inner\">\n		<p class=\"flycart_msg_title\">\n			<span id=\"confirm_qty\"></span>	\n			<span class=\"flycart_msg_x\"></span>			\n			<span id=\"flycart_productname\"></span>\n			<span id=\"flycart_singular\" style=\"display: none;\">was</span>\n			<span id=\"flycart_plural\" style=\"display: none;\">were</span>\n			<span id=\"confirm_addtocart_cart\" class=\"confirm_addtocart\" style=\"display: none;\">added to your cart.</span>\n			<span id=\"confirm_addtocart_wishlist\" class=\"confirm_addtocart\" style=\"display: none;\">added to wishlist.</span>\n			<span id=\"confirm_addtocart_compare\" class=\"confirm_addtocart\" style=\"display: none;\">added to compare products.</span>\n		</p>\n		<div class=\"flycart_confirm_window_actions\">\n		<button onclick=\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide()\" class=\"flycart_msg_bnt flycart_msg_bnt_cs\"><span><span id=\"flycart_confirm_continue\">Continue Shopping</span></span></button>\n		<button class=\"flycart_msg_bnt flycart_msg_bnt_ptc\" onclick=\"setLocation(\'http://demo.7uptheme.com/olec/index.php/checkout/cart/\')\"><span><span id=\"flycart_confirm_checkout\">Go to Shopping Cart</span></span></button>\n						<script type=\"text/javascript\">\n			//<![CDATA[			\n				var _flycart_data = {\"cart\":{\"text\":\"Go to Shopping Cart\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/checkout\\/cart\\/\')\"},\"wishlist\":{\"text\":\"Go to Wishlist\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/wishlist\\/\')\"},\"compare\":{\"text\":\"Show Compare Products\",\"onclick\":\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide();popWin(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/catalog\\/product_compare\\/index\\/uenc\\/aHR0cDovL2RlbW8uN3VwdGhlbWUuY29tL29sZWMvaW5kZXgucGhwL21lbi8,\\/\',\'compare\',\'top:0,left:0,width=820,height=600,resizable=yes,scrollbars=yes\');\"}}			//]]>\n			</script>\n		</div>\n	</div>\n</div>\n<script type=\"text/javascript\">\n//<![CDATA[			\n	function showCartPopup()\n	{\n		//new Effect.Appear($(\'fly-cart-content\'));\n		new $(\'fly-cart-content\').show();\n	}\n	function hideCartPopup(element, event)\n	{\n		element = $(element.id); \n		var popup = $(\'fly-cart-content\'); if (!popup) return;\n		var current_mouse_target = null;\n		if (event.toElement)\n		{\n			current_mouse_target = event.toElement;\n		}\n		else if (event.relatedTarget)\n		{\n			current_mouse_target = event.relatedTarget;\n		}\n		if (!isChildOf(element, current_mouse_target) && element != current_mouse_target)\n		{\n			if (!isChildOf(popup, current_mouse_target) && popup != current_mouse_target)\n			{\n				$(\'fly-cart-content\').hide();\n			}\n		}\n	}\n\n	function isChildOf(parent, child)\n	{\n		if (child != null)\n		{\n			while (child.parentNode)\n			{\n				if ((child = child.parentNode) == parent)\n				{\n					return true;\n				}\n			}\n		}\n		return false;\n	}\n//]]>\n</script><div  id=\"box-wrapper\" class=\"wrapper\">\n        <noscript>\n        <div class=\"global-site-notice noscript\">\n            <div class=\"notice-inner\">\n                <p>\n                    <strong>JavaScript seems to be disabled in your browser.</strong><br />\n                    You must have JavaScript enabled in your browser to utilize the functionality of this website.                </p>\n            </div>\n        </div>\n    </noscript>\n    \n		<div id=\"box-header\" class=\"header1-wrap \">\n        	<div class=\"header-container \">\n    <div class=\"header\">     \n		{{box_header}}\n		<div class=\"container mainmegaMenu\">\n			<div class=\"row\">\n				<div class=\"s-logo col-lg-2 col-md-2 col-sm-12 col-xs-12\">\n					<a href=\"/\" title=\"Olec\"><img src=\"/assets/templates/olec/skin/frontend/vt_olec/default/images/brow/logo.png\" alt=\"Olec\" /></a>\n				</div> \n				\n				<div id=\"vt_menu\" class=\"wrap col-lg-7 col-md-7 col-sm-7 col-xs-12\">\n					<div class=\"inner\">\n						<div id=\"vt-responsivemenu\" class=\"vt-responsivemenu\">\n								<button type=\"button\" class=\"button sidebar\">\n		<i class=\"icon-reorder\"></i>\n    </button>\n    <div id=\"s-menu-sidebar\">\n		{{menu_block1}} \n	</div>\n	<script type=\"text/javascript\">\n		jQuery(document).ready(function($){\n			$(\'body\').append(\'<div class=\"block-slidebar\"><nav id=\"inner-block-slidebar\"><ul class=\"siderbar-menu\"></ul></nav></div>\');\n			$(\'#inner-block-slidebar ul.siderbar-menu\').html($(\'#s-menu-sidebar ul.nav-menu\').html());\n\n			$(\'#vt-responsivemenu .button.sidebar\').click(function(){\n				if($(\'body\').hasClass(\'onpen-sidebar\')){\n					$(\'body\').removeClass(\'onpen-sidebar\');\n				}else{\n					$(\'body\').addClass(\'onpen-sidebar\');\n				}\n			});\n		});\n	</script>\n						</div>						\n						<div id=\"vt_megamenu_menu5b8ef0c3aa6e0\" class=\"container vt-megamenu-wrap horizontal-menu using-effect\">\n	{{menu_block}}\n</div>\n\n\n     \n					</div>                \n				</div>\n				<div class=\"header-cart col-lg-3 col-md-3 col-sm-3 col-xs-12\">\n					{{cart_block}}\n					<div class=\"quick-access\">\n						<form id=\"search_mini_form\" action=\"http://demo.7uptheme.com/olec/index.php/catalogsearch/result/\" method=\"get\">\n    <div class=\"form-search\">        \n        <input id=\"search\" type=\"text\" name=\"q\" value=\"\" class=\"input-text\" maxlength=\"128\" />\n        <button type=\"submit\" title=\"Search\" class=\"button\"><span><span>Search</span></span></button>\n        <div id=\"search_autocomplete\" class=\"search-autocomplete\"></div>\n        <script type=\"text/javascript\">\n        //<![CDATA[\n            var searchForm = new Varien.searchForm(\'search_mini_form\', \'search\', \'Enter keyword...\');\n            searchForm.initAutocomplete(\'http://demo.7uptheme.com/olec/index.php/catalogsearch/ajax/suggest/\', \'search_autocomplete\');\n        //]]>\n        </script>\n    </div>\n</form>\n					</div>\n				</div>\n			</div>                   \n        </div>                   \n    </div>\n</div>\n<div id=\"settings-box\">\n		<h2>Panel Tool</h2>	\n        <div class=\"box-store\">\n        	<h3>Store View and Color</h3>\n        	\n<div class=\"store-switcher\">\n    <span class=\"italy\">\n	    Brown    </span>\n    <ul>\n                <li>\n        	<a class=\"default\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=default\">\n        		Olec			</a>\n		</li>\n                <li>\n        	<a class=\"french\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=french\">\n        		Olec Layout Home 02			</a>\n		</li>\n                <li>\n        	<a class=\"german\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=german\">\n        		Boocdo			</a>\n		</li>\n                <li>\n        	<a class=\"spain\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=spain\">\n        		Blue			</a>\n		</li>\n                <li>\n        	<a class=\"sweden\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=sweden\">\n        		Cyan			</a>\n		</li>\n                <li>\n        	<a class=\"italy actived\" href=\"http://demo.7uptheme.com/olec/index.php/\">\n        		Brown			</a>\n		</li>\n            </ul>  \n</div>\n        </div>\n        <div class=\"box-layout\">\n			<h3>Layout</h3>\n			<select name=\"cpitem_layoutstyle\" class=\"cpitem_layoutstyle\">\n				<option value=\"1\"  selected=\"selected\">Full Width</option>\n				<option value=\"2\" >Boxed</option>\n			</select>\n		</div>\n		<div class=\"box-menu\">\n			<h3>Menu</h3>\n			<select name=\"cpitem_menustyle\" class=\"cpitem_menustyle\">\n				<option value=\"mega\"  selected=\"selected\">Mega Menu</option>\n				<option value=\"css\" >Css Menu</option>\n			</select>\n		</div>\n		<!--<div class=\"box-btncp\">\n			<button class=\"btn-cpdefault\">Default</button>\n			<button class=\"btn-apply\">Apply</button>\n		</div>-->	\n		<div id=\"btn_toggle\" class=\"btnclose\"></div>\n</div>\n		</div>\n		<div id=\"box-content\">\n			<div class=\"box-breadcrumbs\">\n				<div class=\"container\">\n					<div class =\"row\">\n						{{breadcrumbs}}\n					</div>\n				</div>\n			</div>\n			<div class=\"box-main-container\">\n				<div class=\"container\">\n					<div class =\"row\">\n						<div class=\"main-container col2-left-layout\">	\n							<h1 class=\"cpad\">[[if? &is=`[*longtitle*]:!empty:` &then=`[*longtitle*]` &else=`[*pagetitle*]`]]</h1>							\n							<div class=\"main\">	\n									[*content*]	\n								[!showKeeper!]\n							</div>\n						</div>\n					</div>\n				</div>\n			</div>\n		</div>\n		{{footer}}\n                \n\n \n<script type=\"text/javascript\">\n	//<![CDATA[\n	jQuery(document).ready(function ($) {\n		var _check_tem_def = false,\n			_ceck_tem_rwd  = false ;\n	   function _QuickView(){	\n			var	pathbase = \'quickview/index/view\',\n				_item_cls = $(\'.products-grid .item .item-image, .products-list .item .item-image, .products-grid .item-wrap .item-image\'),\n				//_base_url = \'http://demo.7uptheme.com/olec/\',\n				_base_url = \'http://demo.7uptheme.com/olec/index.php/\',\n				pathbase = \'quickview/index/view\';\n			var baseUrl = _base_url + pathbase;\n			if(_item_cls.length > 0){\n				_item_cls.each(function(index, el) {\n					var $this = $(this)\n					if($this.find(\"a.vt_quickview_handler\").length <= 0){\n						if( $this.find(\'a\').length > 0 ){\n							var _href =	$($this.find(\'a\')[0]);				\n							var	producturlpath = _href.attr(\'href\').replace(_base_url,\"\");\n								producturlpath = ( producturlpath.indexOf(\'index.php\') >= 0 ) ? producturlpath.replace(\'index.php/\',\'\') : producturlpath;\n							var	reloadurl = baseUrl+ (\"/path/\"+producturlpath).replace(/\\/\\//g,\"/\"),\n								_quickviewbutton = \"<a  class=\'vt_quickview_handler\' title=\'Quick View\' href=\'\"+reloadurl+\"\'>Quick View</a>\";\n							$(el).append(_quickviewbutton);	\n						}\n					}\n				});\n			}\n		}\n		var _object  = \'\';\n		$(\'.vt_quickview_handler\').fancybox({\n			title: null,\n			 width				: \'75%\',\n			 height				: \'90%\',\n			 autoSize			:  0,\n			 scrolling          : \'auto\',\n			 type				: \'ajax\',\n			 openEffect		    : \'elastic\',\n			 closeEffect		: \'elastic\',\n			 helpers		    :{\n										overlay : {\n						showEarly : true\n					}\n								 },\n			 afterLoad : function () {\n				if($(\'#product_addtocart_form\').length > 0){\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty\');\n					_qty.attr(\'id\',\'qty_primary\');\n					if(typeof productAddToCartForm != \'undefined\' ) {\n						_object = productAddToCartForm ;\n					}\n					$(\'#product_addtocart_form\').attr(\'id\',\'product_addtocart_form_qv_clone\');\n				}\n			 },\n			 beforeShow : function(){\n				\n				var $this = this.element, _parent = $(\'.quickview-main\');\n					if(_parent.length > 0 ){\n						var _price_box =  _parent.find(\'.price-box\');\n						if(_price_box.length > 0){\n							var idprice = $(\'[id]\', _price_box ),\n								value_idprice =  idprice.attr(\'id\'),\n								_cls = idprice.attr(\'class\');\n								\n							if(idprice.length > 0){\n								idprice.addClass(\'price-box-qv\');\n								if($(\'.\'+_cls).length > 0) {\n									$(\'.\'+_cls).each(function(i, el){\n										if(!$(el).hasClass(\'price-box-qv\')) {\n											if($(el).attr(\'id\') == value_idprice){\n												$(el).attr(\'data-idprice\',value_idprice);\n												$(el).attr(\'id\',value_idprice+\'_qv_clone\');\n											}\n										}\n										\n									});	\n								}\n								\n							}\n						}\n					}\n					if(typeof product_zoom){\n						product_zoom = \'undefined\';\n					}\n			 },\n			 afterShow	: function(){\n				if( _check_tem_def){\n					product_zoom_ = new Product.Zoom(\'image\', \'track\', \'handle\', \'zoom_in\', \'zoom_out\', \'track_hint\');\n				} \n				if(_ceck_tem_rwd){ \n					ProductMediaManager.initZoom();\n					ProductMediaManager.wireThumbnails();\n				} \n				\n				if(typeof initcajax != \'undefined\' && $.isFunction(initcajax)){\n					initcajax();\n				}\n				\n				if(typeof updateProductCompareLinks != \'undefined\' && $.isFunction(updateProductCompareLinks)){\n					updateProductCompareLinks();\n				}else{\n					$(\"a.link-compare\").on (\"click\",function(e){\n							e.preventDefault();\n							urlcompare = $(this).attr(\"href\");\n							urlcompare = urlcompare.replace(\"catalog/product_compare/add\",\"quickview/index/compare\");\n							window.location =  urlcompare;\n							return false;\n					  });\n				} \n\n				if(typeof updateWishlistLinks != \'undefined\' && $.isFunction(updateWishlistLinks)) {\n	\n					if(enable_ajax_wishlist){\n					 updateRemoveWishLinks();\n					 if(islogin==\"1\"){\n						 updateWishlistLinks(); \n					 }\n					 updateWishlistAddCartLinks();\n					}\n				}	\n			},\n			beforeClose : function () {\n				if( _check_tem_def){\n					product_zoom_ = \'undefined\';\n				}\n				if(_ceck_tem_rwd){\n					ProductMediaManager.destroyZoom();\n				}\n				\n			},\n			afterClose : function(){\n				\n				$(\'.price-box\').each(function(){\n					var $this = $(this), _id_price = $(\'[id]\', $this).attr(\'data-idprice\') ;\n						if(_id_price != \'\') {\n							$(\'[id]\', $this).removeAttr(\'data-idprice\');\n							$(\'[id]\', $this).attr(\'id\',_id_price);\n						}\n				});\n				\n				if($(\'#product_addtocart_form_qv_clone\').length > 0){\n					$(\'#product_addtocart_form\').remove();\n					$(\'#product_addtocart_form_qv_clone\').attr(\'id\',\'product_addtocart_form\');\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty_primary\');\n					_qty.attr(\'id\',\'qty\');\n					 if($(\'#product_addtocart_form\').length > 0){\n						productAddToCartForm = new VarienForm(\'product_addtocart_form\');\n					}\n				}\n					\n			}\n		});\n		\n		setInterval(function(){ _QuickView(); } ,1000);\n	});\n	//]]>\n</script>    \n</div>\n</body>\n</html>\n<script type=\"text/javascript\">\n	var data = \"\";\n	var active = false;\n	jQuery(function($){\n		if($(\'body\').find(\'#Vt_Ajaxfilter\').attr(\'id\') != \'Vt_Ajaxfilter\'){\n		$(\'body\').prepend(\'<div id=\"Vt_Ajaxfilter\" style=\"display:none\"><div class=\"process\"><img src=\"http://demo.7uptheme.com/olec/skin/frontend/vt_olec/default/vt/ajaxfilter/images/ajax-loader1.gif\"><div>Please wait...</div></div><div class=\"bg\"></div></div>\');}\n\n				$(\".block-layered-nav a\").live(\'click\',function(e){\n			ajaxFilter($(this).attr(\'href\'));\n			e.preventDefault();\n		});\n		\n\n				$(\'.toolbar a\').live(\'click\',function(e){\n			var url=$(this).attr(\'href\');\n			ajaxFilter(url);\n			e.preventDefault();\n		});\n		$(\'.toolbar select\').removeAttr(\'onchange\');\n		$(\'.toolbar select\').live(\'change\',function(){\n			var url=$(this).val(); alert(url);\n			ajaxFilter(url);\n			e.preventDefault();\n		});\n		\n\n	});\n\nfunction ajaxFilter(url) {\n    if (!active) {\n        active = true;\n        jQuery(function($) {\n            oldUrl = url;\n            $(\'#Vt_Ajaxfilter .bg\').height(\'100%\');\n            $(\'#Vt_Ajaxfilter\').fadeIn(300);\n            try {\n                $.ajax({\n                    url: url,\n                    dataType: \'json\',\n                    type: \'post\',\n                    data: data,\n                    success: function(data) {\n						//callback();\n                        if (data.viewpanel) {\n                            if ($(\'.block-layered-nav\')) {\n                                $(\'.block-layered-nav\').empty();\n                                $(\'.block-layered-nav\').append(data.viewpanel)\n                            }\n                        }\n                        if (data.productlist) {\n                            $(\'.category-products\').empty();\n                            $(\'.category-products\').append(data.productlist)\n                        }\n                        var hist = url.split(\'?\');\n                        if(window.history && window.history.pushState){\n							window.history.pushState(\'GET\', data.title, url);\n						}\n                        $(\'body\').find(\'.toolbar select\').removeAttr(\'onchange\');\n                        $(\'#Vt_Ajaxfilter .bg\').height(\'100%\');\n                        $(\'#Vt_Ajaxfilter\').fadeOut(300);\n                    }\n                })\n            } catch (e) {}\n        });\n        active = false\n    }\n    return false\n}\n\nfunction callback(){\n	// return;\n}\n</script>\n','0');
INSERT INTO `modx_site_templates` VALUES ('4','Обычная страница','','0','21','','0','<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"en\" lang=\"en\">\n<head>\n{{head}}\n	{{cart_actions}}\n	{{table_fix}}\n	{{fancybox}}\n</head>\n<body class=\"vt_olec   catalog-category-view categorypath-men category-men\">\n<script type=\"text/javascript\">\n//<![CDATA[\n	var ajaxcartConfig = null;\n    var defaultConfig = {\"enable\":1,\"loadingImage\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/media\\/flycart\\/config\\/default\\/ajax-loader1.gif\",\"loadingAlign\":\"top\",\"custom_cart\":false,\"visible_top_cart\":\"1\",\"loadingText\":\"\",\"show_confirmation\":null,\"updateqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateQty\\/\",\"updatecartqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateCartQty\\/\",\"updateattqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateAttQty\\/\",\"updateproductqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateProductQty\\/\",\"qty_update_cart_page\":\"0\",\"qty_update_category_page\":\"0\",\"qty_update_product_page\":0,\"qty_update_crosssell\":\"0\",\"show_window\":\"1\",\"auto_hide_window\":\"10\",\"redirect_to\":\"0\",\"effect\":\"1\",\"cart_button_color\":\"orange\",\"window_width\":\"550\",\"related_product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/relatedProduct\\/\",\"name_url_encoded\":\"uenc\"};     \n    var defaultQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyDown(#flycart_item, #validate_qty)\\\">down<\\/a>\\r\\n<input class=\\\"input-text qty flycart-qty\\\" type=\\\"text\\\" id=\\\"flycart_prod_id_#flycart_item\\\" value=\\\"1\\\" \\/>\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyUp(#flycart_item, #validate_qty)\\\">up<\\/a>\";\n    var cartQtyTemp = \"\";\n    var productQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyProductDown(#product_id)\\\">down<\\/a>\\r\\n#flycart_qty_input\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyProductUp(#product_id)\\\">up<\\/a>\";\n    var continueMessage = \'Continue Shopping\'; \n		Event.observe(window, \'load\', function() {\n		new Ajax.Request(\'http://demo.7uptheme.com/olec/index.php/flycart/index/topcart/isAjax/1/\', {\n			onSuccess: function(transport) {\n				eval(\'var response = \'+transport.responseText);\n				$$(\".header-container .top-link-cart\").each(function(s){\n					s.innerHTML = response.cart;\n				});	\n			}\n		});\n		\n	});\n	//]]>\n</script>\n\n<div id=\"flycart_confirm_window\" style=\"display: none;\" class=\"flycart-continue-gray flycart-checkout-orange\">\n	<div class=\"inner\">\n		<p class=\"flycart_msg_title\">\n			<span id=\"confirm_qty\"></span>	\n			<span class=\"flycart_msg_x\"></span>			\n			<span id=\"flycart_productname\"></span>\n			<span id=\"flycart_singular\" style=\"display: none;\">was</span>\n			<span id=\"flycart_plural\" style=\"display: none;\">were</span>\n			<span id=\"confirm_addtocart_cart\" class=\"confirm_addtocart\" style=\"display: none;\">added to your cart.</span>\n			<span id=\"confirm_addtocart_wishlist\" class=\"confirm_addtocart\" style=\"display: none;\">added to wishlist.</span>\n			<span id=\"confirm_addtocart_compare\" class=\"confirm_addtocart\" style=\"display: none;\">added to compare products.</span>\n		</p>\n		<div class=\"flycart_confirm_window_actions\">\n		<button onclick=\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide()\" class=\"flycart_msg_bnt flycart_msg_bnt_cs\"><span><span id=\"flycart_confirm_continue\">Continue Shopping</span></span></button>\n		<button class=\"flycart_msg_bnt flycart_msg_bnt_ptc\" onclick=\"setLocation(\'http://demo.7uptheme.com/olec/index.php/checkout/cart/\')\"><span><span id=\"flycart_confirm_checkout\">Go to Shopping Cart</span></span></button>\n						<script type=\"text/javascript\">\n			//<![CDATA[			\n				var _flycart_data = {\"cart\":{\"text\":\"Go to Shopping Cart\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/checkout\\/cart\\/\')\"},\"wishlist\":{\"text\":\"Go to Wishlist\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/wishlist\\/\')\"},\"compare\":{\"text\":\"Show Compare Products\",\"onclick\":\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide();popWin(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/catalog\\/product_compare\\/index\\/uenc\\/aHR0cDovL2RlbW8uN3VwdGhlbWUuY29tL29sZWMvaW5kZXgucGhwL21lbi8,\\/\',\'compare\',\'top:0,left:0,width=820,height=600,resizable=yes,scrollbars=yes\');\"}}			//]]>\n			</script>\n		</div>\n	</div>\n</div>\n<script type=\"text/javascript\">\n//<![CDATA[			\n	function showCartPopup()\n	{\n		//new Effect.Appear($(\'fly-cart-content\'));\n		new $(\'fly-cart-content\').show();\n	}\n	function hideCartPopup(element, event)\n	{\n		element = $(element.id); \n		var popup = $(\'fly-cart-content\'); if (!popup) return;\n		var current_mouse_target = null;\n		if (event.toElement)\n		{\n			current_mouse_target = event.toElement;\n		}\n		else if (event.relatedTarget)\n		{\n			current_mouse_target = event.relatedTarget;\n		}\n		if (!isChildOf(element, current_mouse_target) && element != current_mouse_target)\n		{\n			if (!isChildOf(popup, current_mouse_target) && popup != current_mouse_target)\n			{\n				$(\'fly-cart-content\').hide();\n			}\n		}\n	}\n\n	function isChildOf(parent, child)\n	{\n		if (child != null)\n		{\n			while (child.parentNode)\n			{\n				if ((child = child.parentNode) == parent)\n				{\n					return true;\n				}\n			}\n		}\n		return false;\n	}\n//]]>\n</script><div  id=\"box-wrapper\" class=\"wrapper\">\n        <noscript>\n        <div class=\"global-site-notice noscript\">\n            <div class=\"notice-inner\">\n                <p>\n                    <strong>JavaScript seems to be disabled in your browser.</strong><br />\n                    You must have JavaScript enabled in your browser to utilize the functionality of this website.                </p>\n            </div>\n        </div>\n    </noscript>\n    \n		<div id=\"box-header\" class=\"header1-wrap \">\n        	<div class=\"header-container \">\n    <div class=\"header\">     \n		{{box_header}}\n		<div class=\"container mainmegaMenu\">\n			<div class=\"row\">\n				<div class=\"s-logo col-lg-2 col-md-2 col-sm-12 col-xs-12\">\n					<a href=\"/\" title=\"Olec\"><img src=\"/assets/templates/olec/skin/frontend/vt_olec/default/images/brow/logo.png\" alt=\"Olec\" /></a>\n				</div>  \n				\n				<div id=\"vt_menu\" class=\"wrap col-lg-7 col-md-7 col-sm-7 col-xs-12\">\n					<div class=\"inner\">\n						<div id=\"vt-responsivemenu\" class=\"vt-responsivemenu\">\n								<button type=\"button\" class=\"button sidebar\">\n		<i class=\"icon-reorder\"></i>\n    </button>\n    <div id=\"s-menu-sidebar\">\n		{{menu_block1}}	   \n	</div>\n	<script type=\"text/javascript\">\n		jQuery(document).ready(function($){\n			$(\'body\').append(\'<div class=\"block-slidebar\"><nav id=\"inner-block-slidebar\"><ul class=\"siderbar-menu\"></ul></nav></div>\');\n			$(\'#inner-block-slidebar ul.siderbar-menu\').html($(\'#s-menu-sidebar ul.nav-menu\').html());\n\n			$(\'#vt-responsivemenu .button.sidebar\').click(function(){\n				if($(\'body\').hasClass(\'onpen-sidebar\')){\n					$(\'body\').removeClass(\'onpen-sidebar\');\n				}else{\n					$(\'body\').addClass(\'onpen-sidebar\');\n				}\n			});\n		});\n	</script>\n						</div>						\n						<div id=\"vt_megamenu_menu5b8ef0c3aa6e0\" class=\"container vt-megamenu-wrap horizontal-menu using-effect\">\n	{{menu_block}}\n</div>\n\n\n     \n					</div>                \n				</div>\n				<div class=\"header-cart col-lg-3 col-md-3 col-sm-3 col-xs-12\">\n					{{cart_block}}\n					<div class=\"quick-access\">\n						<form id=\"search_mini_form\" action=\"http://demo.7uptheme.com/olec/index.php/catalogsearch/result/\" method=\"get\">\n    <div class=\"form-search\">        \n        <input id=\"search\" type=\"text\" name=\"q\" value=\"\" class=\"input-text\" maxlength=\"128\" />\n        <button type=\"submit\" title=\"Search\" class=\"button\"><span><span>Search</span></span></button>\n        <div id=\"search_autocomplete\" class=\"search-autocomplete\"></div>\n        <script type=\"text/javascript\">\n        //<![CDATA[\n            var searchForm = new Varien.searchForm(\'search_mini_form\', \'search\', \'Enter keyword...\');\n            searchForm.initAutocomplete(\'http://demo.7uptheme.com/olec/index.php/catalogsearch/ajax/suggest/\', \'search_autocomplete\');\n        //]]>\n        </script>\n    </div>\n</form>\n					</div>\n				</div>\n			</div>                   \n        </div>                   \n    </div>\n</div>\n<div id=\"settings-box\">\n		<h2>Panel Tool</h2>	\n        <div class=\"box-store\">\n        	<h3>Store View and Color</h3>\n        	\n<div class=\"store-switcher\">\n    <span class=\"italy\">\n	    Brown    </span>\n    <ul>\n                <li>\n        	<a class=\"default\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=default\">\n        		Olec			</a>\n		</li>\n                <li>\n        	<a class=\"french\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=french\">\n        		Olec Layout Home 02			</a>\n		</li>\n                <li>\n        	<a class=\"german\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=german\">\n        		Boocdo			</a>\n		</li>\n                <li>\n        	<a class=\"spain\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=spain\">\n        		Blue			</a>\n		</li>\n                <li>\n        	<a class=\"sweden\" href=\"http://demo.7uptheme.com/olec/index.php/?___store=sweden\">\n        		Cyan			</a>\n		</li>\n                <li>\n        	<a class=\"italy actived\" href=\"http://demo.7uptheme.com/olec/index.php/\">\n        		Brown			</a>\n		</li>\n            </ul>  \n</div>\n        </div>\n        <div class=\"box-layout\">\n			<h3>Layout</h3>\n			<select name=\"cpitem_layoutstyle\" class=\"cpitem_layoutstyle\">\n				<option value=\"1\"  selected=\"selected\">Full Width</option>\n				<option value=\"2\" >Boxed</option>\n			</select>\n		</div>\n		<div class=\"box-menu\">\n			<h3>Menu</h3>\n			<select name=\"cpitem_menustyle\" class=\"cpitem_menustyle\">\n				<option value=\"mega\"  selected=\"selected\">Mega Menu</option>\n				<option value=\"css\" >Css Menu</option>\n			</select>\n		</div>\n		<!--<div class=\"box-btncp\">\n			<button class=\"btn-cpdefault\">Default</button>\n			<button class=\"btn-apply\">Apply</button>\n		</div>-->	\n		<div id=\"btn_toggle\" class=\"btnclose\"></div>\n</div>\n		</div>\n		<div id=\"box-content\">\n			<div class=\"box-breadcrumbs\">\n				<div class=\"container\">\n					<div class =\"row\">\n						{{breadcrumbs}}\n					</div>\n				</div>\n			</div>\n			<div class=\"box-main-container\">\n				<div class=\"container\">\n					<div class =\"row\">\n						<div class=\"main-container col2-left-layout\">	\n							<h1 class=\"cpad\">[[if? &is=`[*longtitle*]:!empty:` &then=`[*longtitle*]` &else=`[*pagetitle*]`]]</h1>							\n							<div class=\"main\">	\n									[*content*]											\n							</div>\n						</div>\n					</div>\n				</div>\n			</div>\n		</div>\n		{{footer}}\n                \n\n \n<script type=\"text/javascript\">\n	//<![CDATA[\n	jQuery(document).ready(function ($) {\n		var _check_tem_def = false,\n			_ceck_tem_rwd  = false ;\n	   function _QuickView(){	\n			var	pathbase = \'quickview/index/view\',\n				_item_cls = $(\'.products-grid .item .item-image, .products-list .item .item-image, .products-grid .item-wrap .item-image\'),\n				//_base_url = \'http://demo.7uptheme.com/olec/\',\n				_base_url = \'http://demo.7uptheme.com/olec/index.php/\',\n				pathbase = \'quickview/index/view\';\n			var baseUrl = _base_url + pathbase;\n			if(_item_cls.length > 0){\n				_item_cls.each(function(index, el) {\n					var $this = $(this)\n					if($this.find(\"a.vt_quickview_handler\").length <= 0){\n						if( $this.find(\'a\').length > 0 ){\n							var _href =	$($this.find(\'a\')[0]);				\n							var	producturlpath = _href.attr(\'href\').replace(_base_url,\"\");\n								producturlpath = ( producturlpath.indexOf(\'index.php\') >= 0 ) ? producturlpath.replace(\'index.php/\',\'\') : producturlpath;\n							var	reloadurl = baseUrl+ (\"/path/\"+producturlpath).replace(/\\/\\//g,\"/\"),\n								_quickviewbutton = \"<a  class=\'vt_quickview_handler\' title=\'Quick View\' href=\'\"+reloadurl+\"\'>Quick View</a>\";\n							$(el).append(_quickviewbutton);	\n						}\n					}\n				});\n			}\n		}\n		var _object  = \'\';\n		$(\'.vt_quickview_handler\').fancybox({\n			title: null,\n			 width				: \'75%\',\n			 height				: \'90%\',\n			 autoSize			:  0,\n			 scrolling          : \'auto\',\n			 type				: \'ajax\',\n			 openEffect		    : \'elastic\',\n			 closeEffect		: \'elastic\',\n			 helpers		    :{\n										overlay : {\n						showEarly : true\n					}\n								 },\n			 afterLoad : function () {\n				if($(\'#product_addtocart_form\').length > 0){\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty\');\n					_qty.attr(\'id\',\'qty_primary\');\n					if(typeof productAddToCartForm != \'undefined\' ) {\n						_object = productAddToCartForm ;\n					}\n					$(\'#product_addtocart_form\').attr(\'id\',\'product_addtocart_form_qv_clone\');\n				}\n			 },\n			 beforeShow : function(){\n				\n				var $this = this.element, _parent = $(\'.quickview-main\');\n					if(_parent.length > 0 ){\n						var _price_box =  _parent.find(\'.price-box\');\n						if(_price_box.length > 0){\n							var idprice = $(\'[id]\', _price_box ),\n								value_idprice =  idprice.attr(\'id\'),\n								_cls = idprice.attr(\'class\');\n								\n							if(idprice.length > 0){\n								idprice.addClass(\'price-box-qv\');\n								if($(\'.\'+_cls).length > 0) {\n									$(\'.\'+_cls).each(function(i, el){\n										if(!$(el).hasClass(\'price-box-qv\')) {\n											if($(el).attr(\'id\') == value_idprice){\n												$(el).attr(\'data-idprice\',value_idprice);\n												$(el).attr(\'id\',value_idprice+\'_qv_clone\');\n											}\n										}\n										\n									});	\n								}\n								\n							}\n						}\n					}\n					if(typeof product_zoom){\n						product_zoom = \'undefined\';\n					}\n			 },\n			 afterShow	: function(){\n				if( _check_tem_def){\n					product_zoom_ = new Product.Zoom(\'image\', \'track\', \'handle\', \'zoom_in\', \'zoom_out\', \'track_hint\');\n				} \n				if(_ceck_tem_rwd){ \n					ProductMediaManager.initZoom();\n					ProductMediaManager.wireThumbnails();\n				} \n				\n				if(typeof initcajax != \'undefined\' && $.isFunction(initcajax)){\n					initcajax();\n				}\n				\n				if(typeof updateProductCompareLinks != \'undefined\' && $.isFunction(updateProductCompareLinks)){\n					updateProductCompareLinks();\n				}else{\n					$(\"a.link-compare\").on (\"click\",function(e){\n							e.preventDefault();\n							urlcompare = $(this).attr(\"href\");\n							urlcompare = urlcompare.replace(\"catalog/product_compare/add\",\"quickview/index/compare\");\n							window.location =  urlcompare;\n							return false;\n					  });\n				} \n\n				if(typeof updateWishlistLinks != \'undefined\' && $.isFunction(updateWishlistLinks)) {\n	\n					if(enable_ajax_wishlist){\n					 updateRemoveWishLinks();\n					 if(islogin==\"1\"){\n						 updateWishlistLinks(); \n					 }\n					 updateWishlistAddCartLinks();\n					}\n				}	\n			},\n			beforeClose : function () {\n				if( _check_tem_def){\n					product_zoom_ = \'undefined\';\n				}\n				if(_ceck_tem_rwd){\n					ProductMediaManager.destroyZoom();\n				}\n				\n			},\n			afterClose : function(){\n				\n				$(\'.price-box\').each(function(){\n					var $this = $(this), _id_price = $(\'[id]\', $this).attr(\'data-idprice\') ;\n						if(_id_price != \'\') {\n							$(\'[id]\', $this).removeAttr(\'data-idprice\');\n							$(\'[id]\', $this).attr(\'id\',_id_price);\n						}\n				});\n				\n				if($(\'#product_addtocart_form_qv_clone\').length > 0){\n					$(\'#product_addtocart_form\').remove();\n					$(\'#product_addtocart_form_qv_clone\').attr(\'id\',\'product_addtocart_form\');\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty_primary\');\n					_qty.attr(\'id\',\'qty\');\n					 if($(\'#product_addtocart_form\').length > 0){\n						productAddToCartForm = new VarienForm(\'product_addtocart_form\');\n					}\n				}\n					\n			}\n		});\n		\n		setInterval(function(){ _QuickView(); } ,1000);\n	});\n	//]]>\n</script>    \n</div>\n</body>\n</html>\n<script type=\"text/javascript\">\n	var data = \"\";\n	var active = false;\n	jQuery(function($){\n		if($(\'body\').find(\'#Vt_Ajaxfilter\').attr(\'id\') != \'Vt_Ajaxfilter\'){\n		$(\'body\').prepend(\'<div id=\"Vt_Ajaxfilter\" style=\"display:none\"><div class=\"process\"><img src=\"http://demo.7uptheme.com/olec/skin/frontend/vt_olec/default/vt/ajaxfilter/images/ajax-loader1.gif\"><div>Please wait...</div></div><div class=\"bg\"></div></div>\');}\n\n				$(\".block-layered-nav a\").live(\'click\',function(e){\n			ajaxFilter($(this).attr(\'href\'));\n			e.preventDefault();\n		});\n		\n\n				$(\'.toolbar a\').live(\'click\',function(e){\n			var url=$(this).attr(\'href\');\n			ajaxFilter(url);\n			e.preventDefault();\n		});\n		$(\'.toolbar select\').removeAttr(\'onchange\');\n		$(\'.toolbar select\').live(\'change\',function(){\n			var url=$(this).val(); alert(url);\n			ajaxFilter(url);\n			e.preventDefault();\n		});\n		\n\n	});\n\nfunction ajaxFilter(url) {\n    if (!active) {\n        active = true;\n        jQuery(function($) {\n            oldUrl = url;\n            $(\'#Vt_Ajaxfilter .bg\').height(\'100%\');\n            $(\'#Vt_Ajaxfilter\').fadeIn(300);\n            try {\n                $.ajax({\n                    url: url,\n                    dataType: \'json\',\n                    type: \'post\',\n                    data: data,\n                    success: function(data) {\n						//callback();\n                        if (data.viewpanel) {\n                            if ($(\'.block-layered-nav\')) {\n                                $(\'.block-layered-nav\').empty();\n                                $(\'.block-layered-nav\').append(data.viewpanel)\n                            }\n                        }\n                        if (data.productlist) {\n                            $(\'.category-products\').empty();\n                            $(\'.category-products\').append(data.productlist)\n                        }\n                        var hist = url.split(\'?\');\n                        if(window.history && window.history.pushState){\n							window.history.pushState(\'GET\', data.title, url);\n						}\n                        $(\'body\').find(\'.toolbar select\').removeAttr(\'onchange\');\n                        $(\'#Vt_Ajaxfilter .bg\').height(\'100%\');\n                        $(\'#Vt_Ajaxfilter\').fadeOut(300);\n                    }\n                })\n            } catch (e) {}\n        });\n        active = false\n    }\n    return false\n}\n\nfunction callback(){\n	// return;\n}\n</script>\n','0');
INSERT INTO `modx_site_templates` VALUES ('6','Категории каталога','','0','21','','0','<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"en\" lang=\"en\">\n<head>\n{{head}}\n	{{cart_actions}}\n	{{table_fix}}\n	{{fancybox}}	\n	</head>\n<body class=\"vt_olec   catalog-category-view categorypath-womens category-womens\">\n<script type=\"text/javascript\">\n//<![CDATA[\n	var ajaxcartConfig = null;\n    var defaultConfig = {\"enable\":1,\"loadingImage\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/media\\/flycart\\/config\\/default\\/ajax-loader1.gif\",\"loadingAlign\":\"top\",\"custom_cart\":false,\"visible_top_cart\":\"1\",\"loadingText\":\"\",\"show_confirmation\":null,\"updateqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateQty\\/\",\"updatecartqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateCartQty\\/\",\"updateattqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateAttQty\\/\",\"updateproductqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateProductQty\\/\",\"qty_update_cart_page\":\"0\",\"qty_update_category_page\":\"0\",\"qty_update_product_page\":0,\"qty_update_crosssell\":\"0\",\"show_window\":\"1\",\"auto_hide_window\":\"10\",\"redirect_to\":\"0\",\"effect\":\"1\",\"cart_button_color\":\"orange\",\"window_width\":\"550\",\"related_product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/relatedProduct\\/\",\"name_url_encoded\":\"uenc\"};     \n    var defaultQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyDown(#flycart_item, #validate_qty)\\\">down<\\/a>\\r\\n<input class=\\\"input-text qty flycart-qty\\\" type=\\\"text\\\" id=\\\"flycart_prod_id_#flycart_item\\\" value=\\\"1\\\" \\/>\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyUp(#flycart_item, #validate_qty)\\\">up<\\/a>\";\n    var cartQtyTemp = \"\";\n    var productQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyProductDown(#product_id)\\\">down<\\/a>\\r\\n#flycart_qty_input\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyProductUp(#product_id)\\\">up<\\/a>\";\n    var continueMessage = \'Continue Shopping\'; \n		Event.observe(window, \'load\', function() {\n		new Ajax.Request(\'http://demo.7uptheme.com/olec/index.php/flycart/index/topcart/isAjax/1/\', {\n			onSuccess: function(transport) {\n				eval(\'var response = \'+transport.responseText);\n				$$(\".header-container .top-link-cart\").each(function(s){\n					s.innerHTML = response.cart;\n				});	\n			}\n		});\n		\n	});\n	//]]>\n</script>\n\n<div id=\"flycart_confirm_window\" style=\"display: none;\" class=\"flycart-continue-gray flycart-checkout-orange\">\n	<div class=\"inner\">\n		<p class=\"flycart_msg_title\">\n			<span id=\"confirm_qty\"></span>	\n			<span class=\"flycart_msg_x\"></span>			\n			<span id=\"flycart_productname\"></span>\n			<span id=\"flycart_singular\" style=\"display: none;\">was</span>\n			<span id=\"flycart_plural\" style=\"display: none;\">were</span>\n			<span id=\"confirm_addtocart_cart\" class=\"confirm_addtocart\" style=\"display: none;\">added to your cart.</span>\n			<span id=\"confirm_addtocart_wishlist\" class=\"confirm_addtocart\" style=\"display: none;\">added to wishlist.</span>\n			<span id=\"confirm_addtocart_compare\" class=\"confirm_addtocart\" style=\"display: none;\">added to compare products.</span>\n		</p>\n		<div class=\"flycart_confirm_window_actions\">\n		<button onclick=\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide()\" class=\"flycart_msg_bnt flycart_msg_bnt_cs\"><span><span id=\"flycart_confirm_continue\">Continue Shopping</span></span></button>\n		<button class=\"flycart_msg_bnt flycart_msg_bnt_ptc\" onclick=\"setLocation(\'http://demo.7uptheme.com/olec/index.php/checkout/cart/\')\"><span><span id=\"flycart_confirm_checkout\">Go to Shopping Cart</span></span></button>\n						<script type=\"text/javascript\">\n			//<![CDATA[			\n				var _flycart_data = {\"cart\":{\"text\":\"Go to Shopping Cart\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/checkout\\/cart\\/\')\"},\"wishlist\":{\"text\":\"Go to Wishlist\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/wishlist\\/\')\"},\"compare\":{\"text\":\"Show Compare Products\",\"onclick\":\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide();popWin(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/catalog\\/product_compare\\/index\\/uenc\\/aHR0cDovL2RlbW8uN3VwdGhlbWUuY29tL29sZWMvaW5kZXgucGhwL3dvbWVucy8,\\/\',\'compare\',\'top:0,left:0,width=820,height=600,resizable=yes,scrollbars=yes\');\"}}			//]]>\n			</script>\n		</div>\n	</div>\n</div>\n<script type=\"text/javascript\">\n//<![CDATA[			\n	function showCartPopup()\n	{\n		//new Effect.Appear($(\'fly-cart-content\'));\n		new $(\'fly-cart-content\').show();\n	}\n	function hideCartPopup(element, event)\n	{\n		element = $(element.id); \n		var popup = $(\'fly-cart-content\'); if (!popup) return;\n		var current_mouse_target = null;\n		if (event.toElement)\n		{\n			current_mouse_target = event.toElement;\n		}\n		else if (event.relatedTarget)\n		{\n			current_mouse_target = event.relatedTarget;\n		}\n		if (!isChildOf(element, current_mouse_target) && element != current_mouse_target)\n		{\n			if (!isChildOf(popup, current_mouse_target) && popup != current_mouse_target)\n			{\n				$(\'fly-cart-content\').hide();\n			}\n		}\n	}\n\n	function isChildOf(parent, child)\n	{\n		if (child != null)\n		{\n			while (child.parentNode)\n			{\n				if ((child = child.parentNode) == parent)\n				{\n					return true;\n				}\n			}\n		}\n		return false;\n	}\n//]]>\n</script><div  id=\"box-wrapper\" class=\"wrapper\">\n        <noscript>\n        <div class=\"global-site-notice noscript\">\n            <div class=\"notice-inner\">\n                <p>\n                    <strong>JavaScript seems to be disabled in your browser.</strong><br />\n                    You must have JavaScript enabled in your browser to utilize the functionality of this website.                </p>\n            </div>\n        </div>\n    </noscript>\n    \n		<div id=\"box-header\" class=\"header1-wrap \">\n        	<div class=\"header-container \">\n    <div class=\"header\">     \n		{{box_header}}\n		<div class=\"container mainmegaMenu\">\n			<div class=\"row\">\n				<div class=\"s-logo col-lg-2 col-md-2 col-sm-12 col-xs-12\">\n					<a href=\"/\" title=\"Olec\"><img src=\"/assets/templates/olec/skin/frontend/vt_olec/default/images/brow/logo.png\" alt=\"Olec\" /></a>\n				</div> \n				\n				<div id=\"vt_menu\" class=\"wrap col-lg-7 col-md-7 col-sm-7 col-xs-12\">\n					<div class=\"inner\">\n						<div id=\"vt-responsivemenu\" class=\"vt-responsivemenu\">\n								<button type=\"button\" class=\"button sidebar\">\n		<i class=\"icon-reorder\"></i>\n    </button>\n    <div id=\"s-menu-sidebar\">\n		{{menu_block1}}	   \n	</div>\n	<script type=\"text/javascript\">\n		jQuery(document).ready(function($){\n			$(\'body\').append(\'<div class=\"block-slidebar\"><nav id=\"inner-block-slidebar\"><ul class=\"siderbar-menu\"></ul></nav></div>\');\n			$(\'#inner-block-slidebar ul.siderbar-menu\').html($(\'#s-menu-sidebar ul.nav-menu\').html());\n\n			$(\'#vt-responsivemenu .button.sidebar\').click(function(){\n				if($(\'body\').hasClass(\'onpen-sidebar\')){\n					$(\'body\').removeClass(\'onpen-sidebar\');\n				}else{\n					$(\'body\').addClass(\'onpen-sidebar\');\n				}\n			});\n		});\n	</script>\n						</div>						\n						<div id=\"vt_megamenu_menu5b8ef0c59efd8\" class=\"container vt-megamenu-wrap horizontal-menu using-effect\">\n	{{menu_block}}\n</div>\n\n\n     \n					</div>                \n				</div>\n				<div class=\"header-cart col-lg-3 col-md-3 col-sm-3 col-xs-12\">\n					{{cart_block}}\n					<div class=\"quick-access\">\n						<form id=\"search_mini_form\" action=\"http://demo.7uptheme.com/olec/index.php/catalogsearch/result/\" method=\"get\">\n    <div class=\"form-search\">        \n        <input id=\"search\" type=\"text\" name=\"q\" value=\"\" class=\"input-text\" maxlength=\"128\" />\n        <button type=\"submit\" title=\"Search\" class=\"button\"><span><span>Search</span></span></button>\n        <div id=\"search_autocomplete\" class=\"search-autocomplete\"></div>\n        <script type=\"text/javascript\">\n        //<![CDATA[\n            var searchForm = new Varien.searchForm(\'search_mini_form\', \'search\', \'Enter keyword...\');\n            searchForm.initAutocomplete(\'http://demo.7uptheme.com/olec/index.php/catalogsearch/ajax/suggest/\', \'search_autocomplete\');\n        //]]>\n        </script>\n    </div>\n</form>\n					</div>\n				</div>\n			</div>                   \n        </div>                   \n    </div>\n</div>\n\n		</div>\n		<div id=\"box-content\">\n			<div class=\"box-breadcrumbs\">\n				<div class=\"container\">\n					<div class =\"row\">\n						{{breadcrumbs}}\n					</div>\n				</div>\n			</div>\n			<div class=\"box-main-container\">\n				<div class=\"container\">\n					<div class =\"row\">\n						<div class=\"main-container col2-left-layout\">	\n							<p class=\"category-image\"><img src=\"http://demo.7uptheme.com/olec/media/catalog/category/cate_04_1.jpg\" alt=\"Women\'s\" title=\"Women\'s\" /></p>							<div class=\"main\">	\n								\n								<div id=\"box-main\" class=\"col-lg-12 col-main\">\n																		\n		\n<div class=\"page-title category-title\">\n	<!--\n    -->\n   <h1>[[if? &is=`[*longtitle*]:!empty:` &then=`[*longtitle*]` &else=`[*pagetitle*]`]]</h1>\n</div>\n\n\n    <!--\n    <div class=\"category-description std\">\n        Collection    </div>\n    -->\n\n    <div id=\"catalog-listing\">\n		<div class=\"category-products\">\n    		\n        {{catalogItems}}\n    \n                   \n    \n    \n</div>\n</div>\n\n\n<script type=\"text/javascript\">\n//<![CDATA[	\n    var flycart_associated_products = {\"1\":{\"min_qty\":1,\"max_qty\":99,\"name\":\"Molestie suscipit\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/molestie-suscipit\"},\"14\":{\"min_qty\":1,\"max_qty\":10000,\"name\":\"My Virtual Product\",\"is_simple\":0,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/my-virtual-product\"},\"13\":{\"min_qty\":1,\"max_qty\":10000,\"name\":\"My Bundle Product\",\"is_simple\":0,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/my-bundle-product\"},\"11\":{\"min_qty\":1,\"max_qty\":10000,\"name\":\"My Group Products\",\"is_simple\":0,\"is_grouped\":1,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/my-group-products\"},\"10\":{\"min_qty\":1,\"max_qty\":60,\"name\":\"Magic marine breathable 10\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/magic-marine-breathable-10\"},\"9\":{\"min_qty\":1,\"max_qty\":70,\"name\":\"Magic marine breathable 9\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/magic-marine-breathable-9\"},\"8\":{\"min_qty\":1,\"max_qty\":600,\"name\":\"Magic marine breathable 8\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/magic-marine-breathable-8\"},\"7\":{\"min_qty\":1,\"max_qty\":60,\"name\":\"Magic marine breathable 7\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http: