) ? producturlpath.replace(\'index.php/\',\'\') : producturlpath;\n							var	reloadurl = baseUrl+ (producturlpath).replace(/\\/\\//g,\"/\"),\n								_quickviewbutton = \"<a  class=\'vt_quickview_handler\' title=\'Quick View\' href=\'\"+reloadurl+\"\'>Quick View</a>\";\n							$(el).append(_quickviewbutton);	\n						}\n					}\n				});\n			}\n		}\n		var _object  = \'\';\n		/*$(\'.vt_quickview_handler\').fancybox({\n			title: null,\n			 width				: \'75%\',\n			 height				: \'90%\',\n			 autoSize			:  0,\n			 scrolling          : \'auto\',\n			 type				: \'ajax\',\n			 openEffect		    : \'elastic\',\n			 closeEffect		: \'elastic\',\n			 helpers		    :{\n										overlay : {\n						showEarly : true\n					}\n								 },\n			 afterLoad : function () {\n				if($(\'#product_addtocart_form\').length > 0){\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty\');\n					_qty.attr(\'id\',\'qty_primary\');\n					if(typeof productAddToCartForm != \'undefined\' ) {\n						_object = productAddToCartForm ;\n					}\n					$(\'#product_addtocart_form\').attr(\'id\',\'product_addtocart_form_qv_clone\');\n				}\n			 },\n			 beforeShow : function(){\n				\n				var $this = this.element, _parent = $(\'.quickview-main\');\n					if(_parent.length > 0 ){\n						var _price_box =  _parent.find(\'.price-box\');\n						if(_price_box.length > 0){\n							var idprice = $(\'[id]\', _price_box ),\n								value_idprice =  idprice.attr(\'id\'),\n								_cls = idprice.attr(\'class\');\n								\n							if(idprice.length > 0){\n								idprice.addClass(\'price-box-qv\');\n								if($(\'.\'+_cls).length > 0) {\n									$(\'.\'+_cls).each(function(i, el){\n										if(!$(el).hasClass(\'price-box-qv\')) {\n											if($(el).attr(\'id\') == value_idprice){\n												$(el).attr(\'data-idprice\',value_idprice);\n												$(el).attr(\'id\',value_idprice+\'_qv_clone\');\n											}\n										}\n										\n									});	\n								}\n								\n							}\n						}\n					}\n					if(typeof product_zoom){\n						product_zoom = \'undefined\';\n					}\n			 },\n			 afterShow	: function(){\n				if( _check_tem_def){\n					product_zoom_ = new Product.Zoom(\'image\', \'track\', \'handle\', \'zoom_in\', \'zoom_out\', \'track_hint\');\n				} \n				if(_ceck_tem_rwd){ \n					ProductMediaManager.initZoom();\n					ProductMediaManager.wireThumbnails();\n				} \n				\n				if(typeof initcajax != \'undefined\' && $.isFunction(initcajax)){\n					initcajax();\n				}\n				\n				if(typeof updateProductCompareLinks != \'undefined\' && $.isFunction(updateProductCompareLinks)){\n					updateProductCompareLinks();\n				}else{\n					$(\"a.link-compare\").on (\"click\",function(e){\n							e.preventDefault();\n							urlcompare = $(this).attr(\"href\");\n							urlcompare = urlcompare.replace(\"catalog/product_compare/add\",\"quickview/index/compare\");\n							window.location =  urlcompare;\n							return false;\n					  });\n				} \n\n				if(typeof updateWishlistLinks != \'undefined\' && $.isFunction(updateWishlistLinks)) {\n	\n					if(enable_ajax_wishlist){\n					 updateRemoveWishLinks();\n					 if(islogin==\"1\"){\n						 updateWishlistLinks(); \n					 }\n					 updateWishlistAddCartLinks();\n					}\n				}	\n			},\n			beforeClose : function () {\n				if( _check_tem_def){\n					product_zoom_ = \'undefined\';\n				}\n				if(_ceck_tem_rwd){\n					ProductMediaManager.destroyZoom();\n				}\n				\n			},\n			afterClose : function(){\n				\n				$(\'.price-box\').each(function(){\n					var $this = $(this), _id_price = $(\'[id]\', $this).attr(\'data-idprice\') ;\n						if(_id_price != \'\') {\n							$(\'[id]\', $this).removeAttr(\'data-idprice\');\n							$(\'[id]\', $this).attr(\'id\',_id_price);\n						}\n				});\n				\n				if($(\'#product_addtocart_form_qv_clone\').length > 0){\n					$(\'#product_addtocart_form\').remove();\n					$(\'#product_addtocart_form_qv_clone\').attr(\'id\',\'product_addtocart_form\');\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty_primary\');\n					_qty.attr(\'id\',\'qty\');\n					 if($(\'#product_addtocart_form\').length > 0){\n						productAddToCartForm = new VarienForm(\'product_addtocart_form\');\n					}\n				}\n					\n			}\n		});\n		*/\n		_QuickView();\n		//setInterval(function(){ _QuickView(); } ,1000);\n	});\n	//]]>\n</script>    \n</div>\n</body>\n</html>','0');
INSERT INTO `modx_site_templates` VALUES ('7','Товар-Часы','','0','21','','0','<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"en\" lang=\"en\">\n<head>\n{{head}}\n{{cart_actions}}\n	{{table_fix}}\n	{{fancybox}}	\n</head>\n<body class=\"vt_olec   catalog-category-view categorypath-womens category-womens\">\n<script type=\"text/javascript\">\n//<![CDATA[\n	/*var ajaxcartConfig = null;\n    var defaultConfig = {\"enable\":1,\"loadingImage\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/media\\/flycart\\/config\\/default\\/ajax-loader1.gif\",\"loadingAlign\":\"top\",\"custom_cart\":false,\"visible_top_cart\":\"1\",\"loadingText\":\"\",\"show_confirmation\":null,\"updateqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateQty\\/\",\"updatecartqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateCartQty\\/\",\"updateattqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateAttQty\\/\",\"updateproductqty\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/updateProductQty\\/\",\"qty_update_cart_page\":\"0\",\"qty_update_category_page\":\"0\",\"qty_update_product_page\":0,\"qty_update_crosssell\":\"0\",\"show_window\":\"1\",\"auto_hide_window\":\"10\",\"redirect_to\":\"0\",\"effect\":\"1\",\"cart_button_color\":\"orange\",\"window_width\":\"550\",\"related_product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/flycart\\/index\\/relatedProduct\\/\",\"name_url_encoded\":\"uenc\"};     \n    var defaultQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyDown(#flycart_item, #validate_qty)\\\">down<\\/a>\\r\\n<input class=\\\"input-text qty flycart-qty\\\" type=\\\"text\\\" id=\\\"flycart_prod_id_#flycart_item\\\" value=\\\"1\\\" \\/>\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyUp(#flycart_item, #validate_qty)\\\">up<\\/a>\";\n    var cartQtyTemp = \"\";\n    var productQtyTemp = \"<a title=\\\"Decrement\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-left\\\" href=\\\"javascript:ajaxcartConfig.qtyProductDown(#product_id)\\\">down<\\/a>\\r\\n#flycart_qty_input\\r\\n<a title=\\\"Increment\\\" class=\\\"flycart-qty-btn flycart-qty-change flycart-qty-change-right\\\" href=\\\"javascript:ajaxcartConfig.qtyProductUp(#product_id)\\\">up<\\/a>\";\n    var continueMessage = \'Continue Shopping\'; \n		Event.observe(window, \'load\', function() {\n		new Ajax.Request(\'http://demo.7uptheme.com/olec/index.php/flycart/index/topcart/isAjax/1/\', {\n			onSuccess: function(transport) {\n				eval(\'var response = \'+transport.responseText);\n				$$(\".header-container .top-link-cart\").each(function(s){\n					s.innerHTML = response.cart;\n				});	\n			}\n		});\n		\n	});*/\n	//]]>\n</script>\n\n<div id=\"flycart_confirm_window\" style=\"display: none;\" class=\"flycart-continue-gray flycart-checkout-orange\">\n	<div class=\"inner\">\n		<p class=\"flycart_msg_title\">\n			<span id=\"confirm_qty\"></span>	\n			<span class=\"flycart_msg_x\"></span>			\n			<span id=\"flycart_productname\"></span>\n			<span id=\"flycart_singular\" style=\"display: none;\">was</span>\n			<span id=\"flycart_plural\" style=\"display: none;\">were</span>\n			<span id=\"confirm_addtocart_cart\" class=\"confirm_addtocart\" style=\"display: none;\">added to your cart.</span>\n			<span id=\"confirm_addtocart_wishlist\" class=\"confirm_addtocart\" style=\"display: none;\">added to wishlist.</span>\n			<span id=\"confirm_addtocart_compare\" class=\"confirm_addtocart\" style=\"display: none;\">added to compare products.</span>\n		</p>\n		<div class=\"flycart_confirm_window_actions\">\n		<button onclick=\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide()\" class=\"flycart_msg_bnt flycart_msg_bnt_cs\"><span><span id=\"flycart_confirm_continue\">Continue Shopping</span></span></button>\n		<button class=\"flycart_msg_bnt flycart_msg_bnt_ptc\" onclick=\"setLocation(\'http://demo.7uptheme.com/olec/index.php/checkout/cart/\')\"><span><span id=\"flycart_confirm_checkout\">Go to Shopping Cart</span></span></button>\n						<script type=\"text/javascript\">\n			//<![CDATA[			\n				var _flycart_data = {\"cart\":{\"text\":\"Go to Shopping Cart\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/checkout\\/cart\\/\')\"},\"wishlist\":{\"text\":\"Go to Wishlist\",\"onclick\":\"setLocation(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/wishlist\\/\')\"},\"compare\":{\"text\":\"Show Compare Products\",\"onclick\":\"$(\'flycart_confirm_window\').hide(); ajaxcartConfig.overlay.hide();popWin(\'http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/catalog\\/product_compare\\/index\\/uenc\\/aHR0cDovL2RlbW8uN3VwdGhlbWUuY29tL29sZWMvaW5kZXgucGhwL3dvbWVucy8,\\/\',\'compare\',\'top:0,left:0,width=820,height=600,resizable=yes,scrollbars=yes\');\"}}			//]]>\n			</script>\n		</div>\n	</div>\n</div>\n<script type=\"text/javascript\">\n//<![CDATA[			\n	function showCartPopup()\n	{\n		//new Effect.Appear($(\'fly-cart-content\'));\n		new $(\'fly-cart-content\').show();\n	}\n	function hideCartPopup(element, event)\n	{\n		element = $(element.id); \n		var popup = $(\'fly-cart-content\'); if (!popup) return;\n		var current_mouse_target = null;\n		if (event.toElement)\n		{\n			current_mouse_target = event.toElement;\n		}\n		else if (event.relatedTarget)\n		{\n			current_mouse_target = event.relatedTarget;\n		}\n		if (!isChildOf(element, current_mouse_target) && element != current_mouse_target)\n		{\n			if (!isChildOf(popup, current_mouse_target) && popup != current_mouse_target)\n			{\n				$(\'fly-cart-content\').hide();\n			}\n		}\n	}\n\n	function isChildOf(parent, child)\n	{\n		if (child != null)\n		{\n			while (child.parentNode)\n			{\n				if ((child = child.parentNode) == parent)\n				{\n					return true;\n				}\n			}\n		}\n		return false;\n	}\n//]]>\n</script><div  id=\"box-wrapper\" class=\"wrapper\">\n        <noscript>\n        <div class=\"global-site-notice noscript\">\n            <div class=\"notice-inner\">\n                <p>\n                    <strong>JavaScript seems to be disabled in your browser.</strong><br />\n                    You must have JavaScript enabled in your browser to utilize the functionality of this website.                </p>\n            </div>\n        </div>\n    </noscript>\n    \n		<div id=\"box-header\" class=\"header1-wrap \">\n        	<div class=\"header-container \">\n    <div class=\"header\">     \n		{{box_header}}\n		<div class=\"container mainmegaMenu\">\n			<div class=\"row\">\n				<div class=\"s-logo col-lg-2 col-md-2 col-sm-12 col-xs-12\">\n					<a href=\"/\" title=\"Olec\"><img src=\"/assets/templates/olec/skin/frontend/vt_olec/default/images/brow/logo.png\" alt=\"Olec\" /></a>\n				</div> \n				\n				<div id=\"vt_menu\" class=\"wrap col-lg-7 col-md-7 col-sm-7 col-xs-12\">\n					<div class=\"inner\">\n						<div id=\"vt-responsivemenu\" class=\"vt-responsivemenu\">\n								<button type=\"button\" class=\"button sidebar\">\n		<i class=\"icon-reorder\"></i>\n    </button>\n    <div id=\"s-menu-sidebar\">\n		{{menu_block1}} \n	</div>\n	<script type=\"text/javascript\">\n		jQuery(document).ready(function($){\n			$(\'body\').append(\'<div class=\"block-slidebar\"><nav id=\"inner-block-slidebar\"><ul class=\"siderbar-menu\"></ul></nav></div>\');\n			$(\'#inner-block-slidebar ul.siderbar-menu\').html($(\'#s-menu-sidebar ul.nav-menu\').html());\n\n			$(\'#vt-responsivemenu .button.sidebar\').click(function(){\n				if($(\'body\').hasClass(\'onpen-sidebar\')){\n					$(\'body\').removeClass(\'onpen-sidebar\');\n				}else{\n					$(\'body\').addClass(\'onpen-sidebar\');\n				}\n			});\n		});\n	</script>\n						</div>						\n						<div id=\"vt_megamenu_menu5b8ef0c59efd8\" class=\"container vt-megamenu-wrap horizontal-menu using-effect\">\n	{{menu_block}}\n</div>\n\n\n     \n					</div>                \n				</div>\n				<div class=\"header-cart col-lg-3 col-md-3 col-sm-3 col-xs-12\">\n					<!--<div class=\"block block-cart\">\n        <div class=\"block-title\">\n        <strong>\n			<span data-toggle=\"tooltip\" data-placement=\"left\" title=\"My Cart\">My Cart</span>\n			<span class=\"fa-stack\">0</span>\n		</strong>\n    </div>\n	</div>--> {{cart_block}}\n					<div class=\"quick-access\">\n						<form id=\"search_mini_form\" action=\"http://demo.7uptheme.com/olec/index.php/catalogsearch/result/\" method=\"get\">\n    <div class=\"form-search\">        \n        <input id=\"search\" type=\"text\" name=\"q\" value=\"\" class=\"input-text\" maxlength=\"128\" />\n        <button type=\"submit\" title=\"Search\" class=\"button\"><span><span>Search</span></span></button>\n        <div id=\"search_autocomplete\" class=\"search-autocomplete\"></div>\n        <script type=\"text/javascript\">\n        //<![CDATA[\n            var searchForm = new Varien.searchForm(\'search_mini_form\', \'search\', \'Enter keyword...\');\n            searchForm.initAutocomplete(\'http://demo.7uptheme.com/olec/index.php/catalogsearch/ajax/suggest/\', \'search_autocomplete\');\n        //]]>\n        </script>\n    </div>\n</form>\n					</div>\n				</div>\n			</div>                   \n        </div>                   \n    </div>\n</div>\n\n		</div>\n		<div id=\"box-content\">\n			<div class=\"box-breadcrumbs\">\n				<div class=\"container\">\n					<div class =\"row\">\n						{{breadcrumbs}}\n					</div>\n				</div>\n			</div>\n			<div class=\"box-main-container\">\n				<div class=\"container\">\n					<div class =\"row\">\n						<div class=\"main-container col2-left-layout\">	\n							<p class=\"category-image\"><img src=\"http://demo.7uptheme.com/olec/media/catalog/category/cate_04_1.jpg\" alt=\"Women\'s\" title=\"Women\'s\" /></p>							<div class=\"main\">	\n								\n								<div id=\"box-main\" class=\"col-lg-12 col-main\">\n	<script type=\"text/javascript\">\n    var optionsPrice = new Product.OptionsPrice([]);\n</script>\n<script type=\"text/javascript\">\n    var optionsPrice = new Product.OptionsPrice([]);     \n     jQuery(\"#vt_tab_products\").ready( function($) {\n        $(\"#vt_tab_products\").vtContentTabs();\n    } ); \n	\n	jQuery(document).ready(function($) {\n		$(\'.wrap-right ul li\').click(function(e) {\n			e.preventDefault();\n			var tabIndex = $(this).children(\'a\').attr(\'href\');\n			tabIndex	= tabIndex.split(\'#vt_tab_\');\n			tabIndex	= tabIndex[1];\n			var selector = \"a[href=\'#vt_tab_\" + tabIndex + \"\']\";\n			var tab = \"#vt_tab_\" + tabIndex;\n			$(\"#vt_tab_products ul li\").removeClass(\"active\");\n			$(selector).parent(\'li\').addClass(\"active\");\n			$(\".vt-tab-content div.tab-content\").hide();\n			$(\'.vt-tab-content \' + tab).fadeIn();\n			//$(\"html, body\").animate({ scrollTop: $(\'.vt-tab-content \' + tab).offset().top }, 2000);\n			$(\"html, body\").animate({ scrollTop: $(\'#vt_tab_products\').offset().top }, 2000);\n		});\n	});\n</script>																	\n<div class=\"product-view\">    \n    <div class=\"product-essential m-lr\">\n		<div class=\"container\">\n			<div class=\"row\">\n				\n					<div class=\"no-display\">\n						<input type=\"hidden\" name=\"product\" value=\"14\">\n						<input type=\"hidden\" name=\"related_product\" id=\"related-products-field\" value=\"\">\n					</div>\n					{{main_info}}\n					{{photoItem}}\n					\n					<div class=\"wrap-right col-lg-4 col-md-4 col-sm-4 col-xs-12\">\n						<div class=\"product-essential\">\n							<ul class=\"vt-tab-navi clearfix\">\n								<li class=\"vt-tab-description\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_decription\">Описание</a>\n								</li>\n								<li class=\"vt-tab-tags active\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_tags\">Характеристики</a>\n								</li>\n								<li class=\"vt-tab-reviews active\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_reviewform\">Оплата</a>\n								</li> \n								<li class=\"vt-tab-deliv\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_deliv\">Доставка</a>\n								</li>\n							</ul>\n						</div>\n					</div>\n					<div class=\"clr\"></div>\n					<div id=\"tab-upsell\">\n					</div>\n					<div class=\"clr\"></div>\n					<div id=\"vt_tab_products\" class=\"product-collateral\">\n						<ul class=\"vt-tab-navi clearfix\">\n							<li class=\"first active\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_decription\">Описание</a>\n							</li>\n						    <li class=\"\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_tags\">Характеристики</a>\n							</li>\n						    <li class=\"\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_reviewform\">Оплата</a>\n							</li>\n							<li class=\"\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_deliv\">Доставка</a>\n							</li>\n						</ul>\n						<div class=\"vt-tab-content\">\n							<div id=\"vt_tab_decription\" class=\"tab-content\" style=\"display: block;\">\n								<div class=\"collateral-box\">\n									<h2>Описание</h2>\n									<div class=\"std\">[*content*]</div>\n								</div>\n							</div>\n							<div id=\"vt_tab_tags\" class=\"tab-content\" style=\"display: none;\">\n								<div class=\"box-collateral box-tags\">\n    								<h2>Характеристики</h2>\n								<div class=\"form-add\">\n									<table>\n					<tr>\n						<td>Модель</td>\n						<td>[*model*]</td>\n					</tr>\n					<tr>\n						<td>Тип</td>\n						<td>[*tip*]</td>\n					</tr>\n					<tr>\n						<td>Механизм<