          }\n        }\n    //]]>\n    </script>\n</div>\n							</div>\n																					 {{oplata_dostavka}}\n																																		</div>     \n					</div>\n				\n				<div class=\"clr\"></div>\n				\n									<div id=\"tab-related\">\n					   						\n											</div>\n							</div>\n		</div>\n       \n        \n       \n    <script type=\"text/javascript\">    \n    //<![CDATA[\n        var productAddToCartForm = new VarienForm(\'product_addtocart_form\');\n        productAddToCartForm.submit = function(button, url) {\n            if (this.validator.validate()) {\n                var form = this.form;\n                var oldUrl = form.action;\n\n                if (url) {\n                   form.action = url;\n                }\n                var e = null;\n                try {\n                    this.form.submit();\n                } catch (e) {\n                }\n                this.form.action = oldUrl;\n                if (e) {\n                    throw e;\n                }\n\n                if (button && button != \'undefined\') {\n                    button.disabled = true;\n                }\n            }\n        }.bind(productAddToCartForm);\n\n        productAddToCartForm.submitLight = function(button, url){\n            if(this.validator) {\n                var nv = Validation.methods;\n                delete Validation.methods[\'required-entry\'];\n                delete Validation.methods[\'validate-one-required\'];\n                delete Validation.methods[\'validate-one-required-by-name\'];\n                // Remove custom datetime validators\n                for (var methodName in Validation.methods) {\n                    if (methodName.match(/^validate-datetime-.*/i)) {\n                        delete Validation.methods[methodName];\n                    }\n                }\n\n                if (this.validator.validate()) {\n                    if (url) {\n                        this.form.action = url;\n                    }\n                    this.form.submit();\n                }\n                Object.extend(Validation.methods, nv);\n            }\n        }.bind(productAddToCartForm);\n    //]]>\n    </script>\n    </div>\n    \n</div>\n									\n									\n									\n\n\n<script type=\"text/javascript\">\n//<![CDATA[	\n    var flycart_associated_products = {\"1\":{\"min_qty\":1,\"max_qty\":99,\"name\":\"Molestie suscipit\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/molestie-suscipit\"},\"14\":{\"min_qty\":1,\"max_qty\":10000,\"name\":\"My Virtual Product\",\"is_simple\":0,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/my-virtual-product\"},\"13\":{\"min_qty\":1,\"max_qty\":10000,\"name\":\"My Bundle Product\",\"is_simple\":0,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/my-bundle-product\"},\"11\":{\"min_qty\":1,\"max_qty\":10000,\"name\":\"My Group Products\",\"is_simple\":0,\"is_grouped\":1,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/my-group-products\"},\"10\":{\"min_qty\":1,\"max_qty\":60,\"name\":\"Magic marine breathable 10\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/magic-marine-breathable-10\"},\"9\":{\"min_qty\":1,\"max_qty\":70,\"name\":\"Magic marine breathable 9\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/magic-marine-breathable-9\"},\"8\":{\"min_qty\":1,\"max_qty\":600,\"name\":\"Magic marine breathable 8\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/magic-marine-breathable-8\"},\"7\":{\"min_qty\":1,\"max_qty\":60,\"name\":\"Magic marine breathable 7\",\"is_simple\":1,\"is_grouped\":0,\"product_url\":\"http:\\/\\/demo.7uptheme.com\\/olec\\/index.php\\/womens\\/m