omen\'s\" title=\"Women\'s\" /></p>							<div class=\"main\">	\n								\n								<div id=\"box-main\" class=\"col-lg-12 col-main\">\n	<script type=\"text/javascript\">\n    var optionsPrice = new Product.OptionsPrice([]);\n</script>\n<script type=\"text/javascript\">\n    var optionsPrice = new Product.OptionsPrice([]);     \n     jQuery(\"#vt_tab_products\").ready( function($) {\n        $(\"#vt_tab_products\").vtContentTabs();\n    } ); \n	\n	jQuery(document).ready(function($) {\n		$(\'.wrap-right ul li\').click(function(e) {\n			e.preventDefault();\n			var tabIndex = $(this).children(\'a\').attr(\'href\');\n			tabIndex	= tabIndex.split(\'#vt_tab_\');\n			tabIndex	= tabIndex[1];\n			var selector = \"a[href=\'#vt_tab_\" + tabIndex + \"\']\";\n			var tab = \"#vt_tab_\" + tabIndex;\n			$(\"#vt_tab_products ul li\").removeClass(\"active\");\n			$(selector).parent(\'li\').addClass(\"active\");\n			$(\".vt-tab-content div.tab-content\").hide();\n			$(\'.vt-tab-content \' + tab).fadeIn();\n			//$(\"html, body\").animate({ scrollTop: $(\'.vt-tab-content \' + tab).offset().top }, 2000);\n			$(\"html, body\").animate({ scrollTop: $(\'#vt_tab_products\').offset().top }, 2000);\n		});\n	});\n</script>																	\n<div class=\"product-view\">    \n    <div class=\"product-essential m-lr\">\n		<div class=\"container\">\n			<div class=\"row\">\n				\n					<div class=\"no-display\">\n						<input type=\"hidden\" name=\"product\" value=\"14\">\n						<input type=\"hidden\" name=\"related_product\" id=\"related-products-field\" value=\"\">\n					</div>\n					{{main_info}}\n					{{photoItem}}\n					\n					<div class=\"wrap-right col-lg-4 col-md-4 col-sm-4 col-xs-12\">\n						<div class=\"product-essential\">\n							<ul class=\"vt-tab-navi clearfix\">\n								<li class=\"vt-tab-description\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_decription\">Описание</a>\n								</li>\n								<li class=\"vt-tab-tags active\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_tags\">Характеристики</a>\n								</li>\n								<li class=\"vt-tab-reviews active\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_reviewform\">Оплата</a>\n								</li> \n								<li class=\"vt-tab-deliv\">\n									<span class=\"border-top\"><span></span></span>    \n									<a href=\"#vt_tab_deliv\">Доставка</a>\n								</li>\n							</ul>\n						</div>\n					</div>\n					<div class=\"clr\"></div>\n					<div id=\"tab-upsell\">\n					</div>\n					<div class=\"clr\"></div>\n					<div id=\"vt_tab_products\" class=\"product-collateral\">\n						<ul class=\"vt-tab-navi clearfix\">\n							<li class=\"first active\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_decription\">Описание</a>\n							</li>\n						    <li class=\"\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_tags\">Характеристики</a>\n							</li>\n						    <li class=\"\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_reviewform\">Оплата</a>\n							</li>\n							<li class=\"\">\n								<span class=\"border-top\"><span></span></span>    \n								<a href=\"#vt_tab_deliv\">Доставка</a>\n							</li>\n						</ul>\n						<div class=\"vt-tab-content\">\n							<div id=\"vt_tab_decription\" class=\"tab-content\" style=\"display: block;\">\n								<div class=\"collateral-box\">\n									<h2>Описание</h2>\n									<div class=\"std\">[*content*]</div>\n								</div>\n							</div>\n							<div id=\"vt_tab_tags\" class=\"tab-content\" style=\"display: none;\">\n								<div class=\"box-collateral box-tags\">\n    								<h2>Характеристики</h2>\n								<div class=\"form-add\">\n									<table>\n					[[if? &is=`[*material*]:!empty:` &then=`\n					<tr>\n						<td>Материал</td>\n						<td>[*material*]</td>\n					</tr>` &else=``]]\n					[[if? &is=`[*kolba*]:!empty:` &then=`\n					<tr>\n						<td>Пластиковая колба</td>\n						<td>[*kolba*]</td>\n					</tr>` &else=``]]\n					[[if? &is=`[*keyring*]:!empty:` &then=`\n					<tr>\n						<td>Кольцо для ключей</td>\n						<td>[*keyring*]</td>\n					</tr>` &else=``]]\n					[[if? &is=`[*size-brelok*]:!empty:` &then=`\n					<tr>\n						<td>Размеры маркера</td>\n						<td>[*size-brelok*]</td>\n					</tr>` &else=``]]\n					[[if? &is=`[*srok_sveta*]:!empty:` &then=`\n					<tr>\n						<td>Гарантийный срок свечения</td>\n						<td>[*srok_sveta*]</td>\n					</tr>` &else=``]]\n					[[if? &is=`[*water-brelok*]:!empty:` &then=`\n					<tr>\n						<td>Водонепроницаемость</td>\n						<td>[*water-brelok*]</td>\n					</tr>` &else=``]]\n					[[if? &is=`[*how-long*]:!empty:` &then=`\n					<tr>\n						<td>Видимость в темноте</td>\n						<td>[*how-long*]</td>\n					</tr>` &else=``]]\n					[[if? &is=`[*razmer_akssesuar*]:!empty:` &then=`\n					<tr>\n						<td>Размер изделия</td>\n						<td>[*razmer_akssesuar*]</td>\n					</tr>` &else=``]]	\n					[[if? &is=`[*proizvoditel*]:!empty:` &then=`		\n					<tr>\n						<td>Производитель подсветки</td>\n						<td>[*proizvoditel*][[showFlag? &t=`[*proizvoditel*]`]]</td>\n					</tr>` &else=``]]\n				</table>\n								</div>\n    \n    <p class=\"note\">Use spaces to separate tags. Use single quotes (\') for phrases.</p>\n    <script type=\"text/javascript\">\n    //<![CDATA[\n        var addTagFormJs = new VarienForm(\'addTagForm\');\n        function submitTagForm(){\n            if(addTagFormJs.validator.validate()) {\n                addTagFormJs.form.submit();\n            }\n        }\n    //]]>\n    </script>\n</div>\n							</div>\n																					 {{oplata_dostavka}}\n																																		</div>     \n					</div>\n				\n				<div class=\"clr\"></div>\n				\n									<div id=\"tab-related\">\n					   						\n											</div>\n							</div>\n		</div>\n       \n        \n       \n    <script type=\"text/javascript\">    \n    //<![CDATA[\n        var productAddToCartForm = new VarienForm(\'product_addtocart_form\');\n        productAddToCartForm.submit = function(button, url) {\n            if (this.validator.validate()) {\n                var form = this.form;\n                var oldUrl = form.action;\n\n                if (url) {\n                   form.action = url;\n                }\n                var e = null;\n                try {\n                    this.form.submit();\n                } catch (e) {\n                }\n                this.form.action = oldUrl;\n                if (e) {\n                    throw e;\n                }\n\n                if (button && button != \'undefined\') {\n                    button.disabled = true;\n                }\n            }\n        }.bind(productAddToCartForm);\n\n        productAddToCartForm.submitLight = function(button, url){\n            if(this.validator) {\n                var nv = Validation.methods;\n                delete Validation.methods[\'required-entry\'];\n                delete Validation.methods[\'validate-one-required\'];\n                delete Validation.methods[\'validate-one-required-by-name\'];\n                // Remove custom datetime validators\n                for (var methodName in Validation.methods) {\n                    if (methodName.match(/^validate-datetime-.*/i)) {\n                        delete Validation.methods[methodName];\n                    }\n                }\n\n                if (this.validator.validate()) {\n                    if (url) {\n                        this.form.action = url;\n                    }\n                    this.form.submit();\n                }\n                Object.extend(Validation.methods, nv);\n            }\n        }.bind(productAddToCartForm);\n    //]]>\n    </script>\n    </div>\n    \n</div>\n									\n									\n									\n\n\n<script type=\"text/javascript\">\n//<![CDATA[	\n    var flycart_associated_products = {\"1\":{\"min_qty\":1,\"max_qty\":99,\"nam