INSERT INTO `modx_site_templates` VALUES ('27','yml','','0','22','','0','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE yml_catalog SYSTEM \"shops.dtd\">\n<yml_catalog date=\"[*editedon:date=`%Y-%m-%d %H:%M`*]\"> [(site_name)] ООО «Гринвич+3» [(site_url)] [!Ditto? &id=`category` &parents=`10` &depth=`2` &display=`all` &filter=`isfolder,1,1` &tpl=`yml_cat_tpl`!] [!Ditto? &id=`yml` &parents=`10` &depth=`3` &display=`all` &tpl=`yml_tpl` &paginate=`0` &showPublishedOnly=`1` &hidefolder=`1`!] </yml_catalog>','0');
INSERT INTO `modx_site_templates` VALUES ('28','Duplicate of Главная страница','','0','0','','0','<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n\n	{{head}}\n	{{carousel_main}}\n	{{cart_actions}}\n	{{fancybox2}}\n	\n</head>\n<body>\n		\n	<div class=\"top_line\"></div>\n	<div class=\"wrapper_main\">\n<div class=\"header\">\n	<div class=\"wrapper\">\n		{{upmenu}}\n		\n		<div class=\"wrapper2 logowr\">\n			{{logo_block}}\n			{{menu_block}}\n			{{cart_block}}\n		</div>		\n	</div>\n</div>\n	<!-- <div class=\"wrapper2\">	<img src=\"http://traserh3.ru/images/top_banner_info_ng-2018.jpg\" alt=\"Расписание работы магазина в новогодние праздники\"></div> -->\n		<!-- <div class=\"wrapper2\">	<img src=\"http://traserh3.ru/images/top_banner_info_may_2018.jpg\" alt=\"Расписание работы магазина в майские праздники\"></div> -->\n		<div class=\"wrapper2\">	<img src=\"http://traserh3.ru/images/top_banner_24-08-2018.jpg\" alt=\"Бесплатная доставка по России при покупке любых часов\"></div>\n			<!-- <div class=\"wrapper2\">	<a href=\"http://traserh3.ru/katalog/chasy-traser/predzakaz-traser.html\"><img src=\"http://traserh3.ru/images/top_banner_p67_opa.jpg\" alt=\"Traser P67 Officer Pro Automatic\"></a></div> -->\n		  <!-- <div class=\"wrapper2\">	<a href=\"http://traserh3.ru/katalog/chasy-traser/predzakaz-aero-gmt-ii.html\"><img src=\"http://traserh3.ru/images/top_banner_aero_bb.jpg\" alt=\"Предзаказ часов BALL\"></a></div> \n		<div class=\"wrapper2\">	<a href=\"http://traserh3.ru/katalog/chasy-traser/chasy-ball-predzakaz-navigator.html\"><img src=\"http://traserh3.ru/images/top_banner_navigator.jpg\" alt=\"Предзаказ часов BALL\"></a></div> -->\n<div class=\"wrapper2\">\n	{{carousel_1}}\n	{{carousel_2}}\n	{{carousel_3}}\n	{{carousel_4}}\n</div>\n		\n<div class=\"wrapper\">\n	{{carousel_news}}\n	{{footer}}\n</div>\n	</div>\n	{{JivoSite}}\n	</body>\n</html>','0');
INSERT INTO `modx_site_templates` VALUES ('29','Duplicate of Обычная страница','','0','0','','0','     <!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n	{{head}}\n	{{cart_actions}}\n	{{table_fix}}\n	{{fancybox}}\n</head>\n<body>\n	<div class=\"top_line\"></div>\n	<div class=\"wrapper_main\">\n<div class=\"header\">\n	<div class=\"wrapper\">\n		{{upmenu}}\n		<div class=\"wrapper2 logowr\">\n			{{logo_block}}\n			{{menu_block}}\n			{{cart_block}}\n		</div>\n	</div>\n</div>\n<div class=\"wrapper2\">\n	{{breadcrumbs}}\n	<div class=\"content\">\n		<h1 class=\"cpad\">[[if? &is=`[*longtitle*]:!empty:` &then=`[*longtitle*]` &else=`[*pagetitle*]`]]</h1>\n		<hr />\n		<div class=\"cpad text-content\">\n			[*content*]\n		</div>\n	</div>\n	<div class=\"clear\"></div><br />\n</div>\n<div class=\"wrapper\">\n	{{footer}}\n</div>\n	</div>\n	{{JivoSite}}\n</body>\n</html>','0');
