m .item-image, .products-grid .item-wrap .item-image\'),\n				//_base_url = \'http://demo.7uptheme.com/olec/\',\n				_base_url = \'http://demo.7uptheme.com/olec/index.php/\',\n				pathbase = \'quickview/index/view\';\n			var baseUrl = _base_url + pathbase;\n			if(_item_cls.length > 0){\n				_item_cls.each(function(index, el) {\n					var $this = $(this)\n					if($this.find(\"a.vt_quickview_handler\").length <= 0){\n						if( $this.find(\'a\').length > 0 ){\n							var _href =	$($this.find(\'a\')[0]);				\n							var	producturlpath = _href.attr(\'href\').replace(_base_url,\"\");\n								producturlpath = ( producturlpath.indexOf(\'index.php\') >= 0 ) ? producturlpath.replace(\'index.php/\',\'\') : producturlpath;\n							var	reloadurl = baseUrl+ (\"/path/\"+producturlpath).replace(/\\/\\//g,\"/\"),\n								_quickviewbutton = \"<a  class=\'vt_quickview_handler\' title=\'Quick View\' href=\'\"+reloadurl+\"\'>Quick View</a>\";\n							$(el).append(_quickviewbutton);	\n						}\n					}\n				});\n			}\n		}\n		var _object  = \'\';\n		$(\'.vt_quickview_handler\').fancybox({\n			title: null,\n			 width				: \'75%\',\n			 height				: \'90%\',\n			 autoSize			:  0,\n			 scrolling          : \'auto\',\n			 type				: \'ajax\',\n			 openEffect		    : \'elastic\',\n			 closeEffect		: \'elastic\',\n			 helpers		    :{\n										overlay : {\n						showEarly : true\n					}\n								 },\n			 afterLoad : function () {\n				if($(\'#product_addtocart_form\').length > 0){\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty\');\n					_qty.attr(\'id\',\'qty_primary\');\n					if(typeof productAddToCartForm != \'undefined\' ) {\n						_object = productAddToCartForm ;\n					}\n					$(\'#product_addtocart_form\').attr(\'id\',\'product_addtocart_form_qv_clone\');\n				}\n			 },\n			 beforeShow : function(){\n				\n				var $this = this.element, _parent = $(\'.quickview-main\');\n					if(_parent.length > 0 ){\n						var _price_box =  _parent.find(\'.price-box\');\n						if(_price_box.length > 0){\n							var idprice = $(\'[id]\', _price_box ),\n								value_idprice =  idprice.attr(\'id\'),\n								_cls = idprice.attr(\'class\');\n								\n							if(idprice.length > 0){\n								idprice.addClass(\'price-box-qv\');\n								if($(\'.\'+_cls).length > 0) {\n									$(\'.\'+_cls).each(function(i, el){\n										if(!$(el).hasClass(\'price-box-qv\')) {\n											if($(el).attr(\'id\') == value_idprice){\n												$(el).attr(\'data-idprice\',value_idprice);\n												$(el).attr(\'id\',value_idprice+\'_qv_clone\');\n											}\n										}\n										\n									});	\n								}\n								\n							}\n						}\n					}\n					if(typeof product_zoom){\n						product_zoom = \'undefined\';\n					}\n			 },\n			 afterShow	: function(){\n				if( _check_tem_def){\n					product_zoom_ = new Product.Zoom(\'image\', \'track\', \'handle\', \'zoom_in\', \'zoom_out\', \'track_hint\');\n				} \n				if(_ceck_tem_rwd){ \n					ProductMediaManager.initZoom();\n					ProductMediaManager.wireThumbnails();\n				} \n				\n				if(typeof initcajax != \'undefined\' && $.isFunction(initcajax)){\n					initcajax();\n				}\n				\n				if(typeof updateProductCompareLinks != \'undefined\' && $.isFunction(updateProductCompareLinks)){\n					updateProductCompareLinks();\n				}else{\n					$(\"a.link-compare\").on (\"click\",function(e){\n							e.preventDefault();\n							urlcompare = $(this).attr(\"href\");\n							urlcompare = urlcompare.replace(\"catalog/product_compare/add\",\"quickview/index/compare\");\n							window.location =  urlcompare;\n							return false;\n					  });\n				} \n\n				if(typeof updateWishlistLinks != \'undefined\' && $.isFunction(updateWishlistLinks)) {\n	\n					if(enable_ajax_wishlist){\n					 updateRemoveWishLinks();\n					 if(islogin==\"1\"){\n						 updateWishlistLinks(); \n					 }\n					 updateWishlistAddCartLinks();\n					}\n				}	\n			},\n			beforeClose : function () {\n				if( _check_tem_def){\n					product_zoom_ = \'undefined\';\n				}\n				if(_ceck_tem_rwd){\n					ProductMediaManager.destroyZoom();\n				}\n				\n			},\n			afterClose : function(){\n				\n				$(\'.price-box\').each(function(){\n					var $this = $(this), _id_price = $(\'[id]\', $this).attr(\'data-idprice\') ;\n						if(_id_price != \'\') {\n							$(\'[id]\', $this).removeAttr(\'data-idprice\');\n							$(\'[id]\', $this).attr(\'id\',_id_price);\n						}\n				});\n				\n				if($(\'#product_addtocart_form_qv_clone\').length > 0){\n					$(\'#product_addtocart_form\').remove();\n					$(\'#product_addtocart_form_qv_clone\').attr(\'id\',\'product_addtocart_form\');\n					var _qty = $(\'#product_addtocart_form\').find(\'#qty_primary\');\n					_qty.attr(\'id\',\'qty\');\n					 if($(\'#product_addtocart_form\').length > 0){\n						productAddToCartForm = new VarienForm(\'product_addtocart_form\');\n					}\n				}\n					\n			}\n		});\n		\n		setInterval(function(){ _QuickView(); } ,1000);\n	});\n	//]]>\n</script>    \n</div>\n</body>\n</html>\n<script type=\"text/javascript\">\n	var data = \"\";\n	var active = false;\n	jQuery(function($){\n		if($(\'body\').find(\'#Vt_Ajaxfilter\').attr(\'id\') != \'Vt_Ajaxfilter\'){\n		$(\'body\').prepend(\'<div id=\"Vt_Ajaxfilter\" style=\"display:none\"><div class=\"process\"><img src=\"http://demo.7uptheme.com/olec/skin/frontend/vt_olec/default/vt/ajaxfilter/images/ajax-loader1.gif\"><div>Please wait...</div></div><div class=\"bg\"></div></div>\');}\n\n				$(\".block-layered-nav a\").live(\'click\',function(e){\n			ajaxFilter($(this).attr(\'href\'));\n			e.preventDefault();\n		});\n		\n\n				$(\'.toolbar a\').live(\'click\',function(e){\n			var url=$(this).attr(\'href\');\n			ajaxFilter(url);\n			e.preventDefault();\n		});\n		$(\'.toolbar select\').removeAttr(\'onchange\');\n		$(\'.toolbar select\').live(\'change\',function(){\n			var url=$(this).val(); alert(url);\n			ajaxFilter(url);\n			e.preventDefault();\n		});\n		\n\n	});\n\nfunction ajaxFilter(url) {\n    if (!active) {\n        active = true;\n        jQuery(function($) {\n            oldUrl = url;\n            $(\'#Vt_Ajaxfilter .bg\').height(\'100%\');\n            $(\'#Vt_Ajaxfilter\').fadeIn(300);\n            try {\n                $.ajax({\n                    url: url,\n                    dataType: \'json\',\n                    type: \'post\',\n                    data: data,\n                    success: function(data) {\n						//callback();\n                        if (data.viewpanel) {\n                            if ($(\'.block-layered-nav\')) {\n                                $(\'.block-layered-nav\').empty();\n                                $(\'.block-layered-nav\').append(data.viewpanel)\n                            }\n                        }\n                        if (data.productlist) {\n                            $(\'.category-products\').empty();\n                            $(\'.category-products\').append(data.productlist)\n                        }\n                        var hist = url.split(\'?\');\n                        if(window.history && window.history.pushState){\n							window.history.pushState(\'GET\', data.title, url);\n						}\n                        $(\'body\').find(\'.toolbar select\').removeAttr(\'onchange\');\n                        $(\'#Vt_Ajaxfilter .bg\').height(\'100%\');\n                        $(\'#Vt_Ajaxfilter\').fadeOut(300);\n                    }\n                })\n            } catch (e) {}\n        });\n        active = false\n    }\n    return false\n}\n\nfunction callback(){\n	// return;\n}\n</script>\n','0');
